INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('0903bb99-8ca6-533f-ac19-086d4cb8d8f2', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 9, 9, 'እግዚአብሔርም ለድኻዎች መጠጊያ ኾናቸው ርሱም በመከራቸው ጊዜ ረዳታቸው ነው'),
  ('7188d593-cc9e-55e5-a731-7f2571424053', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 10, 10, 'ስምኽን የሚያውቁ ዅሉ ባንተ ይታመናሉ አቤቱ የሚሹኽን አትተዋቸውምና'),
  ('2563cb62-fd83-5f2c-a4bc-5726314cd83f', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 11, 11, 'በጽዮን ለሚኖር ለእግዚአብሔር ዘምሩ በአሕዛብም መካከል አደራረጉን ንገሩ'),
  ('4d8dc0d0-f47b-5751-adfc-fdd9fb070c2d', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 12, 12, 'ደማቸውን የሚመራመር ርሱ ዐስቧልና የድኻዎችንም ጩኸት አልረሳምና'),
  ('452018b6-3416-5401-aaac-8ceda98e2327', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 13, 13, 'አቤቱ ዕዘንልኝ ጠላቶቼም የሚያመጡብኝን መከራ እይ ከሞት ደጆች ከፍ ከፍ የምታደርገኝ'),
  ('0da0b03e-1035-5749-a1d9-1d0e99064832', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 14, 14, 'ምስጋናውን ዅሉ እናገር ዘንድ በጽዮን ልጅ በደጆቿ በማዳንኽ ደስ ይለኛል'),
  ('eaf3f6e3-6bf6-5ad1-ac9c-70562eb858ca', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 15, 15, 'አሕዛብ በሠሩት ጕድጓድ ወደቁ በዚያችም በሸሸጓት ወጥመድ እግራቸው ተጠመደች'),
  ('9e20a4c6-42d2-54bc-a323-e82c7885ffbe', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 16, 16, 'እግዚአብሔር ፍርድን በማድረግ የታወቀ ነው ኀጢአተኛው በእጆቹ ሥራ ተጠመደ'),
  ('8c4c1517-4334-57bd-ab57-adb98ca37a67', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 17, 17, 'ኀጢአተኛዎች ወደ ሲኦል ይመለሳሉ እግዚአብሔርን የሚረሱ አሕዛብም ዅሉ'),
  ('0a0fb981-7bcc-5ba5-a0d0-815a98d85065', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 18, 18, 'ድኻ ለዘለዓለም አይረሳምና የችግረኛዎችም ተስፋቸው ለዘለዓለም አይጠፋም'),
  ('a51672d2-6def-5c90-a822-3b9b0e32ff86', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 19, 19, 'አቤቱ ተነሥ ሰውም አይበርታ አሕዛብም በፊትኽ ይፈረድባቸው'),
  ('997e8fcd-5082-5224-ad9e-6c65f18d4af7', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 20, 20, 'አቤቱ ፍርሀትን በላያቸው ጫንባቸው አሕዛብ ሰዎች እንደ ኾኑ ይወቁ (መዝሙረ 10 በዕብራይስጥ)'),
  ('6ff537c3-af95-5b69-ac76-36853987d277', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 21, 1, 'አቤቱ ለምን ርቀኽ ቆምኽ በመከራም ጊዜ ለምን ትሰወራለኽ'),
  ('e0caa99a-85b7-5a5b-a661-e2c56a6daac3', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 22, 2, 'በኀጢአተኛ ትዕቢት ድኻ ይናደዳል ባሰቡት ተንኰላቸው ተጠመዱ'),
  ('e534a46b-f923-52e5-a0b7-881c1f797cbb', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 23, 3, 'ኀጢአተኛ በነፍሱ ፈቃድ ይወደሳልና ዐመፀኛም ይባርካል'),
  ('d4f38857-3b4d-59e6-ab9e-92bc05da1490', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 24, 4, 'ኀጢአተኛ እግዚአብሔርን አበሳጨው እንደ ቍጣውም ብዛት አይመራመረውም በርሱ ፊት እግዚአብሔር የለ ም'),
  ('c67ae714-e321-56eb-a4f3-e47604f56a4e', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 25, 5, 'መንገዱ ዅሉ የረከሰ ነው ፍርድኽም በፊቱ የፈረሰ ነው ጠላቶችንም ዅሉ ይገዛቸዋል'),
  ('47d9c764-cc46-5f9e-a0b5-dd2d64d30b2b', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 26, 6, 'በልቡ ይላል፦ለልጅ ልጅ አልታወክም ክፉም አያገኘኝም'),
  ('bbaa8330-6a02-554d-a970-692d0256a9d9', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 27, 7, 'አፉ መርገምንና ሽንገላን ተንኰልን የተመላ ነው ከምላሱ በታች ጕዳትና መከራ ነው'),
  ('25932779-3cef-5429-a1c0-793d591694f7', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 28, 8, 'በመንደሮች መሸመቂያ ይቀመጣል ንጹሓንን በስውር ይገድል ዘንድ ዐይኖቹም ወደ ድኻ ይመለከታሉ'),
  ('91dad8a5-216f-5a0b-adcd-0204cdcd58dd', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 29, 9, 'እንደ አንበሳ በችፍግ ዱር በስውር ይሸምቃል ድኻውን ለመንጠቅ ያደባል ድኻውን ይነጥቀዋል በአሽክ ላውም ይስበዋል'),
  ('a3de3b08-8ed9-581a-a0fe-085c7739dca2', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 30, 10, 'ድኻ ይዋረዳል ይጐብጣል በኀያላኑም እጅግ ይወድቃል'),
  ('ec049cb9-398e-5097-a3f1-d7d75fdfde89', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 31, 11, 'በልቡም ይላል፦እግዚአብሔር ረስቶኛል ፈጽሞም እንዳያይ ፊቱን ሰወረ'),
  ('e04b81b2-0958-5992-a469-2fc53bd93e7a', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 32, 12, 'አቤቱ አምላክ ሆይ ተነሥ እጅኽም ከፍ ከፍ ትበል ድኻዎችን አትርሳ'),
  ('2aa3e4da-c608-5a4f-ab73-880bf1cf8dc1', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 33, 13, 'ኀጢአተኛ ስለ ምን እግዚአብሔርን አስቈጣው በልቡ፦አይመራመረኝም ይላልና'),
  ('42a48efb-db5a-5c17-aa7b-57596a944510', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 34, 14, 'አየኸው አንተ ክፋትንና ቍጣን ትመለከታለኽና በእጅኽ ፍዳውን ለመስጠት ድኻ ራሱን ለአንተ ይተዋ ል ለድኻ አደግም ረዳቱ አንተ ነኽ'),
  ('8cbcc251-6c9b-5665-a37b-62c3787664e0', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 35, 15, 'የኀጢአተኛንና የክፉን ክንድ ስበር የኀጢአቱንም ብድራት ክፈል ሌላ እስከማይገኝ ድረስ'),
  ('cd4b248c-9e1d-5632-a3b1-2946717f116d', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 36, 16, 'እግዚአብሔር ለዘለዓለም ይነግሣል አሕዛብ ከምድሩ ይጠፋሉ'),
  ('c53d2080-a190-5561-ada8-321bda677724', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 37, 17, 'እግዚአብሔር የድኻዎችን ምኞት ሰማ ዦሮውም የልባቸውን ዐሳብ አደመጠች'),
  ('9ab163ad-8075-5cde-a4be-baf4977019c1', 'f8b5acd8-a940-5949-a362-4ad14700a209', '455ca479-25d8-5c76-a98c-d768fe03d9cb', 38, 18, 'ፍርዱ ለድኻ አደግና ለችግረኛ ይደረግ ዘንድ ሰዎች በምድር ላይ አፋቸውን ከፍ ከፍ ማድረግ እን ዳይደግሙ'),
  ('61394410-6594-5a13-ae56-70669b95af31', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 1, 1, 'በእግዚአብሔር ታመንኹ ነፍሴን፦እንደ ወፍ ወደ ተራራዎች ተቅበዝበዢ እንዴት ትሏታላችኹ'),
  ('125ceb50-aa86-577c-ae7a-51be90712db2', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 2, 2, 'ኀጢአተኛዎች እንሆ ቀስታቸውን ገትረዋልና ፍላጻቸውንም በአውታር አዘጋጅተዋልና ልበ ቅኖችን በስው ር ይነድፉ ዘንድ'),
  ('60873c7c-d76a-55bc-a156-ac55b8ddb6fa', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 3, 3, 'አንተ የሠራኸውን እንሆ እነርሱ አፍርሰዋልና ጻድቅ ግን ምን አደረገ'),
  ('31e604e6-664e-56f5-ad27-b87057a6a9cb', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 4, 4, 'እግዚአብሔር በተቀደሰው መቅደሱ ነው እግዚአብሔር ዙፋኑ በሰማይ ነው ዐይኖቹ ወደ ድኻ ይመለከታሉ ቅንድቦቹም የሰው ልጆችን ይመረምራሉ'),
  ('62bb57b6-8adf-536c-a8c7-7786b314e68e', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 5, 5, 'እግዚአብሔር ጻድቅንና ኀጥእን ይመረምራል ዐመፃን የወደዳት ግን ነፍሱን ጠልቷል'),
  ('381b7dab-5a7d-576a-a442-28eab1f20b04', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 6, 6, 'ወጥመድ በኃጥኣን ላይ ያዘንባል እሳትና ዲን ዐውሎ ነፋስም የጽዋቸው ዕድል ፈንታ ነው'),
  ('f95e7ad7-9607-5b48-a036-427c6135d120', '84d04842-788a-5aeb-a5a3-0f24c822a152', '4137f07a-ced5-5923-abda-2574a057f1df', 7, 7, 'እግዚአብሔር ጻድቅ ነውና ጽድቅንም ይወዳ፟ል ቅንነት ግን ፊቱን ታየዋለች'),
  ('6477fdb6-00f6-5b4d-a60b-9d5ee33b6c07', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 1, 1, 'አቤቱ አድነኝ ደግ ሰው አልቋልና ከሰው ልጆችም መተማመን ጐድሏልና'),
  ('4a6de4e7-723e-55a8-a9eb-0eee4010cc09', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 2, 2, 'ርስ በርሳቸው ከንቱ ነገርን ይናገራሉ በሽንገላ ከንፈር ኹለት ልብ ኾነው ይናገራሉ'),
  ('34baafa1-f606-5bea-a56d-b98d5c146d3c', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 3, 3, 'የሽንገላን ከንፈሮች ዅሉ እግዚአብሔር ያጠፋቸዋል ታላቅ ነገርን የምትናገረውን ምላስ'),
  ('5ecf4ead-ddeb-5fc6-adab-54426bf52ee1', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 4, 4, 'ምላሳችንን እናበረታለን ከንፈራችን የእኛ ነው ጌታችን ማን ነው የሚሉትን'),
  ('9d9c4c88-f5e3-553c-a2a9-858b5a1d4992', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 5, 5, 'ስለድኻዎች መከራ ስለችግረኛዎች ጩኸት እግዚአብሔር፦አኹን እነሣለኹ ይላል መድኀኒትን አደርጋለኹ በላዩም እገልጣለኹ'),
  ('91cf8024-96ad-5b84-aa64-225d9655607d', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 6, 6, 'በምድር ላይ እንደ ተፈተነ ሰባት ጊዜ እንደ ተጣራ ብር የእግዚአብሔር ቃላት የነጹ ቃላት ናቸው'),
  ('c255a71c-1545-53e2-a196-66863d95d5a6', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 7, 7, 'አቤቱ አንተ ጠብቀን ከዚችም ትውልድ ለዘለዓለም ታደገን'),
  ('f14d20fc-1c54-511b-abd1-88ea4f88789f', '46a5720c-8e66-57b5-a0d6-d5a91d4a8673', '8db6640e-87b8-5e84-a1f4-3b2ae4fa8314', 8, 8, 'በሰው ልጆች ዘንድ ምናምንቴ ከፍ ከፍ ባለ ጊዜ ክፉዎች በዙሪያው ዅሉ ይመላለሳሉ'),
  ('19f9f77a-db05-535f-afb9-c9b94fbec399', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 1, 1, 'አቤቱ እስከ መቼ ፈጽመኽ ትረሳኛለኽ እስከ መቼስ ፊትኽን ከእኔ ትሰውራለኽ'),
  ('e36ddd91-9356-5f8a-a481-4db7370d8ec2', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 2, 2, 'እስከ መቼ በነፍሴ እመካከራለኹ ትካዜስ እስከ መቼ ዅልጊዜ ይኾናል እስከ መቼ ጠላቴ በላዬ ይጓደ ዳል'),
  ('837f1151-f590-589b-a763-1129c411fb17', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 3, 3, 'አቤቱ አምላኬ እየኝ ስማኝም ጠላቴ አሸነፍኹት እንዳይል'),
  ('03aee0bd-202b-5c3a-aebe-41e7d5712a9f', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 4, 4, 'የሚያስጨንቁኝም እኔ ብናወጥ ደስ እንዳይላቸው ለሞትም እንዳልተኛ ዐይኖቼን አብራ'),
  ('01e46eda-91bd-5eed-af83-878b7ac6d9e8', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 5, 5, 'እኔ ግን በቸርነትኽ ታመንኹ ልቤም በመድኀኒትኽ ደስ ይለዋል'),
  ('56ecc1ed-cc2f-5fc2-a11b-d66b01f8a05f', 'dfb6f6f6-f5e2-5d68-a719-d4a658a6bd5e', 'b4b33a7e-eb48-5883-ad56-be508558d814', 6, 6, 'የረዳኝን እግዚአብሔርን አመሰግናለኹ ለልዑል እግዚአብሔር ስምም እዘምራለኹ'),
  ('8efab5ee-d180-5646-a83f-afd0951973b2', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 1, 1, 'ሰነፍ በልቡ፦አምላክ የለም ይላል በሥራቸው ረከሱ ጐሰቈሉ በጎ ነገርን የሚሠራ የለም'),
  ('c5a6f357-5bed-5f8b-aaa9-995e1413fb19', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 2, 2, 'የሚያስተውል እግዚአብሔርንም የሚፈልግ እንዳለ ያይ ዘንድ እግዚአብሔር ከሰማይ የሰው ልጆችን ተመ ለከተ'),
  ('e48f630d-536c-5e3f-ae96-9c00dc2f6f97', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 3, 3, 'ዅሉ ዐመፁ በአንድነትም ረከሱ በጎ ነገርን የሚሠራ የለም አንድም ስንኳ የለም'),
  ('0b14257e-0c5c-5a91-aa85-a70d7c691ee7', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 4, 4, 'ጕረሯቸው የተከፈተ መቃብር ነው በምላሳቸው ሸነገሉ'),
  ('e7447163-391b-50f5-a578-91c4e54698df', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 5, 5, 'ከከንፈራቸው በታች የእባብ መርዝ አለ አፋቸው መርገምንና መራራን ተሞልቷል'),
  ('cf4ecd7a-684d-521a-a755-1b64affcfc56', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 6, 6, 'ደምን ለማፍሰስ እግራቸው ፈጣን ነው ጥፋትና ጕስቍልና በመንገዳቸው አለ የሰላምን መንገድ አላወቋ ትምና እግዚአብሔርን መፍራት በዐይናቸው ፊት የለም'),
  ('9dbb8f35-cdcc-5b0a-adc4-774900aa54e2', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 7, 7, 'ሕዝቤን እንደ እንጀራ የሚበሉ ኀጢአት የሚሠሩ ዅሉ በእውኑ አያውቁምን እግዚአብሔርንም አይጠሩትም'),
  ('ce7c79d1-1621-5ca6-a117-e5d6dbab9bca', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 8, 8, 'በዚያ በታላቅ ፍርሀት እጅግ ፈሩ እግዚአብሔር በጻድቃን ትውልድ ዘንድ ነውና'),
  ('db163d89-c29a-5bc7-a608-07a44eaf9803', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 9, 9, 'የድኻዎችን ምክር አሳፈራችኹ እግዚአብሔር ግን ተስፋቸው ነው'),
  ('116ce4cc-0236-511e-a138-fbea52117255', 'e0de2868-b5ea-5c6e-ab39-ee6c7d4c6efa', '562e7de5-8b5a-5796-a254-12861f7dce1f', 10, 10, 'ከጽዮን መድኀኒትን ለእስራኤል ማን ይሰጣል እግዚአብሔር የሕዝቡን ምርኮ በመለሰ ጊዜ ያዕቆብ ደ ስ ይለዋል እስራኤልም ሐሤት ያደርጋል'),
  ('7696b5a4-1290-5d8d-a502-400dc960580a', '47a6e274-8763-5c40-af7e-0aadc1e92e88', 'aba6406f-4cfb-51aa-a2f4-fe8c3b4ff1a4', 1, 1, 'አቤቱ በድንኳንኽ ውስጥ ማን ያድራል በተቀደሰውም ተራራኽ ማን ይኖራል'),
  ('c47a156a-ada4-56fd-a5bb-b18d915d041e', '47a6e274-8763-5c40-af7e-0aadc1e92e88', 'aba6406f-4cfb-51aa-a2f4-fe8c3b4ff1a4', 2, 2, 'በቅንነት የሚኼድ ጽድቅንም የሚያደርግ በልቡም እውነትን የሚናገር'),
  ('1d3d77f0-5242-5bae-ac4a-a9a4b780b017', '47a6e274-8763-5c40-af7e-0aadc1e92e88', 'aba6406f-4cfb-51aa-a2f4-fe8c3b4ff1a4', 3, 3, 'በአንደበቱ የማይሸነግል በባልንጀራው ላይ ክፋትን የማያደርግ ዘመዶቹንም የማይሰድብ'),
  ('c1cf6346-accb-529d-a58a-287f8757f3e5', '47a6e274-8763-5c40-af7e-0aadc1e92e88', 'aba6406f-4cfb-51aa-a2f4-fe8c3b4ff1a4', 4, 4, 'ኀጢአተኛ በፊቱ የተናቀ እግዚአብሔርንም የሚፈሩትን የሚያከብር ለባልንጀራው የሚምል የማይከዳም'),
  ('748772dd-89d7-5350-aefc-e9811866e258', '47a6e274-8763-5c40-af7e-0aadc1e92e88', 'aba6406f-4cfb-51aa-a2f4-fe8c3b4ff1a4', 5, 5, 'ገንዘቡን በዐራጣ የማያበድር በንጹሑ ላይ መማለጃን የማይቀበል እንዲህ የሚያደርግ ለዘለዓለም አይ ታወክም'),
  ('f32f9635-1ff4-566a-a748-e4eaf86a8807', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 1, 1, 'አቤቱ ባንተ ታምኛለኹና ጠብቀኝ'),
  ('c5a47da6-3238-53a6-ae7e-87deb5cfcace', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 2, 2, 'እግዚአብሔርን፦አንተ ጌታዬ ነኽ አልኹ ከአንተ በቀር በጎነት የለኝም'),
  ('e892aafe-63e9-5e81-a84f-525977f05f22', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 3, 3, 'ፈቃድኽ ዅሉ በምድር ባሉት ቅዱሳንና ክቡራን ላይ ነው'),
  ('2c6e93ea-8792-5fb9-a152-0a4a3373ad3b', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 4, 4, 'ወደ ሌላ ለሚፋጠኑት መከራቸው ይበዛል የቍርባናቸውን ደም እኔ አላፈሰ፟ውም ስማቸውንም በከንፈሬ አልጠራም'),
  ('bb0ac001-4530-50a8-ad4c-03131335aeb2', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 5, 5, 'እግዚአብሔር የርስቴ ዕድል ፈንታና ጽዋዬ ነው ዕጣዬንም የምታጠና አንተ ነኽ'),
  ('4e1dbdae-6bf5-5cbf-aa78-fabc9a6edd92', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 6, 6, 'ገመድ ባማረ ስፍራ ወደቀችልኝ ርስቴም ተዋበችልኝ'),
  ('6e21e6b3-2a74-53c5-a9c5-a4a8323f88ca', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 7, 7, 'የመከረኝን እግዚአብሔርን እባርካለኹ ደግሞም በሌሊት ኵላሊቶቼ ይገሥጹኛል'),
  ('48950453-b2dc-58cd-aab4-162fb8d3ab96', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 8, 8, 'ዅልጊዜ እግዚአብሔርን በፊቴ አየዋለኹ በቀኜ ነውና አልታወክም'),
  ('a7e64570-c8e0-5512-af14-af563fbef4c7', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 9, 9, 'ስለዚህ ልቤን ደስ አለው ምላሴም ሐሴት አደረገች ሥጋዬም ደግሞ በተስፋ ታድራለች'),
  ('f626de58-bcd3-50b3-a44f-da56ac04265a', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 10, 10, 'ነፍሴን በሲኦል አትተዋትምና ቅዱስኽንም መበስበስን ያይ ዘንድ አትተወውም'),
  ('6d7732fd-829a-5738-a74d-89fe711a26e8', '290b9414-fb65-5cb3-a0c4-6297f64d9b72', '5de935eb-4ef9-5a21-ae04-220a1aa6831c', 11, 11, 'የሕይወትን መንገድ አሳየኸኝ ከፊትኽ ጋራ ደስታን አጠገብኸኝ በቀኝኽም የዘለዓለም ፍሥሓ አለ'),
  ('06ae06f2-d6fd-51e4-a726-056db2410701', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 1, 1, 'አቤቱ ጽድቄን ስማ ጩኸቴንም አድምጥ በተንኰለኛም ከንፈር ያልኾነውን ጸሎቴን አድምጥ'),
  ('0cbe7b55-8d6a-541a-a61c-dcbee9cfa388', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 2, 2, 'ፍርዴ ከፊትኽ ይውጣ ዐይኖችኽም በቅንነት ይዩ'),
  ('59fa6844-3e0a-5f04-afde-1ff1b9c2604d', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 3, 3, 'ልቤን ፈተንኸው በሌሊትም ጐበኘኸኝ ፈተንኸኝ ምንም አላገኘኽብኝም'),
  ('cc638dbc-3b20-5839-a849-99fb6c1dde70', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 4, 4, 'የሰውን ሥራ አፌ እንዳይናገር ፈቃዴ ነው ስለከንፈሮችኽ ቃል ጭንቅ የኾኑ መንገዶችን ጠበቅኹ'),
  ('d83063f6-cd6d-55a8-aee6-9172d511a138', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 5, 5, 'እግሮች እንዳይናወጡ አረማመዴን በመንገድኽ አጽና'),
  ('d802c081-aa8f-5570-a827-4095a546c12c', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 6, 6, 'አቤቱ ሰምተኸኛልና ወዳንተ ጠራኹ ዦሮኽን ወደ እኔ አዘንብል ቃሌንም ስማ'),
  ('7a3ab7de-8397-5a9c-ada4-b8f34f19e180', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 7, 7, 'የሚያምኑኽን ከሚቃወሙ በቀኝኽ የምታድናቸው ቸርነትኽን ድንቅ አድርገኽ ግለጠው'),
  ('d930dd10-dbbd-554b-a7ee-2978c292ddb3', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 8, 8, 'እንደ ዐይን ብሌን ጠብቀኝ በክንፎችኽ ጥላ ሰውረኝ'),
  ('46e337ef-d978-5743-af2f-26e40c706e59', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 9, 9, 'ከሚያስጨንቁኝ ከኀጢአተኛዎች ነፍሴንም ከሚከቧ፟ት ከጠላቶቼ'),
  ('f4f6a1af-55a5-5828-a62e-74137332641b', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 10, 10, 'አንዠታቸውን በስብ ቋጠሩ በአፋቸውም ትንቢትን ተናገሩ'),
  ('25c6398d-7482-519e-a437-66db8a9f7e08', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 11, 11, 'አኹንም ርምጃችንን ከበቡ ዐይናቸውን ወደ ምድር ዝቅ ዝቅ አደረጉ'),
  ('e1a691e1-e7fa-5b2f-a909-65cfa7b4f15a', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 12, 12, 'ርሱ ንጥቂያን እንደሚናፍቅ አንበሳ ተሸጕጦም እንደሚኖር እንደ አንበሳ ደቦል ነው'),
  ('63233cc6-c652-5336-a89c-a8fb87486bd8', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 13, 13, 'አቤቱ ተነሥ ቀድመኽ ወደ ታች ጣለው ነፍሴን ከኀጢአተኛ በሰይፍኽ አድናት'),
  ('f9dd77ae-fe38-5998-ad69-046dca7888e2', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 14, 14, 'አቤቱ ከሰዎች ዕድል ፈንታቸው በሕይወታቸው ከኾነች ከዚህ ዓለም ሰዎች በእጅኽ አድነኝ ከሰወርኸ ው መዝገብኽ ሆዳቸውን አጠገብኽ ልጆቻቸው ብዙ ናቸው የተረፋቸውንም ለሕፃናታቸው ያተርፋሉ'),
  ('4d802915-7b5f-5db4-a052-dc87c0372efe', 'f2d50d05-7177-5920-a673-8fe1d3642fd4', 'a9733308-b9cf-5a72-a1ef-aa07b63fc15c', 15, 15, 'እኔ ግን በጽድቅ ፊትኽን አያለኹ ክብርኽን ሳይ እጠግባለኹ'),
  ('df26f382-5c28-5269-a79a-ee81830cc99f', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 1, 1, 'አቤቱ ጕልበቴ ሆይ እወድ፟ኻለኹ'),
  ('f3c3452f-da87-5ddc-a4e9-2d3678eec472', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 2, 2, 'እግዚአብሔር አለቴ ዐምባዬ መድኀኒቴ አምላኬ በርሱም የምተማመንበት ረዳቴ መታመኛዬና የደኅንነቴ ቀንድ መጠጊያዬም ነው'),
  ('79b5e77b-d905-59ff-aeaf-421b78b933a8', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 3, 3, 'ምስጋና የሚገ፟ባ፟ውን እግዚአብሔርን እጠራለኹ ከጠላቶቼም እድናለኹ'),
  ('fd335f7c-a309-531c-a90e-d9b581230475', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 4, 4, 'የሞት ጣር ያዘኝ የዐመፅ ፈሳሽም አስፈራኝ'),
  ('61de31db-48a9-5248-a092-66a8d0e279ec', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 5, 5, 'የሲኦል ጣር ከበበኝ የሞት ወጥመድም ደረሰብኝ'),
  ('0904798a-e158-5258-a50a-e35122b02988', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 6, 6, 'በጨነቀኝ ጊዜ እግዚአብሔርን ጠራኹት ወደ አምላኬም ጮኽኹ ከመቅደሱም ቃሌን ሰማኝ ጩኸቴም በፊቱ ወደ ዦሮው ገባ'),
  ('01fcb4fb-7d21-5b07-a2f3-3f541ed9bd74', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 7, 7, 'ምድርም ተንቀጠቀጠች ተናወጠችም የተራራዎችም መሠረቶች ተነቃነቁ እግዚአብሔርም ተቈጥቷልና ተንቀጠ ቀጡ'),
  ('66ea208f-8fd2-5ab1-a3cf-921122a62a64', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 8, 8, 'ከቍጣው ጢስ ወጣ ከፊቱም የሚበላ እሳት ነደደ ፍምም ከርሱ በራ'),
  ('3696699c-7ff7-579f-ab8e-e406a3a16ca3', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 9, 9, 'ሰማዮችን ዝቅ ዝቅ አደረገ ወረደም ጨለማ ከእግሩ በታች ነበረ'),
  ('c8fa5395-4c82-55b0-a715-02d74f59ad14', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 10, 10, 'በኪሩቤልም ላይ ተቀምጦ በረረ በነፋስም ክንፍ በረረ'),
  ('622d5f2d-5818-53f9-a2e8-fb9e1423cacc', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 11, 11, 'መሰወሪያውን ጨለማ አደረገ በዙሪያውም ድንኳኑ በደመናት ውስጥ የጨለማ ውሃ ነበረ'),
  ('0e3c8047-f492-5f59-a444-940072a69ded', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 12, 12, 'በፊቱ ካለው ብርሃን የተነሣ ደመናትና በረዶ የእሳት ፍምም ዐለፉ'),
  ('c41a9f1f-f3c7-5ae2-a082-c854b6a82af6', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 13, 13, 'እግዚአብሔርም ከሰማያት አንጐደጐደ ልዑልም ቃሉን ሰጠ'),
  ('54c1fe06-3b06-5b86-a152-b1b8c46e20a7', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 14, 14, 'ፍላጻውን ላከ በተናቸውም መብረቆችን አበዛ አወካቸውም'),
  ('4d458159-a949-58fe-ad5c-ffe5d76f4d0b', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 15, 15, 'አቤቱ ከዘለፋኽ ከመዓትኽም መንፈስ እስትንፋስ የተነሣ የውሃዎች ምንጮች ታዩ የዓለም መሠረቶችም ተገለጡ'),
  ('59a330fb-cfdc-561f-aaec-1f14e5d864a2', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 16, 16, 'ከላይ ሰደደ ወሰደኝም ከብዙ ውሃዎችም አወጣኝ'),
  ('5ff171cb-25b9-57c0-afde-48e3b9d8d298', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 17, 17, 'ከብርቱዎች ጠላቶቼ ከሚጠሉኝም አዳነኝ በርትተውብኝ ነበርና'),
  ('15a536e9-cc30-542b-a0d7-9a03e261209b', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 18, 18, 'በመከራዬ ቀን ደረሱብኝ እግዚአብሔር ግን ደገፋዬ ኾነ'),
  ('1e72b976-b38c-5b86-a49c-79d5d68b4d1a', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 19, 19, 'ወደ ሰፊ ስፍራም አወጣኝ ወዶ፟ኛልና አዳነኝ'),
  ('904cf3b3-c588-5a63-adb7-4302ea1a5d6e', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 20, 20, 'እግዚአብሔር እንደ ጽድቄ ይከፍለኛል እንደ እጄ ንጽሕና ይመልስልኛል'),
  ('10344a1f-ddad-5345-a090-8a29f093d033', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 21, 21, 'የእግዚአብሔርን መንገድ ጠብቄያለኹና በአምላኬም አላመፅኹም'),
  ('8ce9b672-603f-57de-a4be-7e5feb90a79d', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 22, 22, 'ፍርዱ ዅሉ በፊቴ ነበረና ሥርዐቱንም ከፊቴ አላራቅኹም'),
  ('ce1fd56d-26d8-5169-af36-5e1410e90760', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 23, 23, 'በርሱ ዘንድ ቅን ነበርኹ ከኀጢአቴም ተጠበቅኹ'),
  ('93941c83-ff79-5c0f-af39-79a8b6eecabc', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 24, 24, 'እግዚአብሔርም እንደ ጽድቄ እንደ እጄም ንጽሕና በዐይኖቹ ፊት መለሰልኝ'),
  ('cb07b24e-6980-5515-a1a3-25d13616723d', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 25, 25, 'ከቸር ሰው ጋራ ቸር ኾነኽ ትገኛለኽ ከቅን ሰው ጋራ ቅን ኾነኽ ትገኛለኽ'),
  ('6ddd904c-aaf5-5741-a758-7c26fc42ac14', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 26, 26, 'ከንጹሕ ጋራ ንጹሕ ኾነኽ ትገኛለኽ ከጠማማም ጋራ ጠማማ ኾነኽ ትገኛለኽ'),
  ('a3ca3941-4c01-55a8-a3e9-821008faa919', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 27, 27, 'አንተ የተጠቃውን ሕዝብ ታድናለኽና የትዕቢተኛዎችን ዐይን ግን ታዋርዳለኽ'),
  ('31a15fbb-3c11-568c-a4b8-1212488cdc23', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 28, 28, 'አንተ መብራቴን ታበራለኽና እግዚአብሔር አምላኬ ጨለማዬን ያበራል'),
  ('db0bfba5-08ea-58bc-a621-278c74876cbb', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 29, 29, 'ባንተ ከጥፋት እድናለኹና በአምላኬም ቅጥሩን እዘላ፟ለኹ'),
  ('e70b51ff-351c-5283-aeb0-eaee0c5c82c8', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 30, 30, 'የአምላኬ መንገድ ፍጹም ነው የእግዚአብሔር ቃል የነጠረ ነው በርሱ ለሚታመኑት ዅሉ ጋሻ ነው'),
  ('951a02d1-5475-5b18-a6ee-db3faf63d900', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 31, 31, 'ከእግዚአብሔር በቀር አምላክ ማን ነው ከአምላካችን በቀር አምላክ ማን ነው'),
  ('b1bc5b8d-8512-5c88-afe6-27dffce1cc0f', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 32, 32, 'ኀይልን የሚያስታጥቀኝ መንገዴንም የሚያቃና'),
  ('6b680f11-2fb6-5766-ae84-fa61b1472aad', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 33, 33, 'እግሮቼን እንደ ብሖር እግሮች የሚያረታ በኰረብታዎችም የሚያቆመኝ እግዚአብሔር ነው'),
  ('6171a9a8-1897-5cd2-aba8-d1905687eebb', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 34, 34, 'እጆቼን ሰልፍ ያስተምራል በክንዴም የናስ ቀስት እገትራለኹ'),
  ('9b5716d6-7093-52d9-a3ff-e07c9d6e8de5', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 35, 35, 'ለደኅንነቴም መታመኛን ሰጠኸኝ ቀኝኽም ትረዳኛለች ትምህርትኽም ለዘለዓለም ታጠናኛለች ተግሣጽኽም ታስተምረኛለች'),
  ('a2bacb23-1b49-5ac5-ac60-641074b182c3', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 36, 36, 'አረማመዴን በበታቼ አሰፋኽ እግሮቼም አልተንሸራተቱም'),
  ('fd45ba06-13c8-50b4-a8f4-43840296de17', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 37, 37, 'ጠላቶቼን አሳድዳቸዋለኹ እይዛቸዋለኹም እስካጠፋቸውም ድረስ አልመለስም'),
  ('720e8254-f7a3-5b7b-a6a4-3969ffa07e78', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 38, 38, 'አስጨንቃቸዋለኹ መቆምም አይችሉም ከእግሬም በታች ይወድቃሉ'),
  ('bb2966fc-7534-5318-aba4-03ae6fde1d7f', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 39, 39, 'ለሰልፍም ኀይልን ታስታጥቀኛለኽ በበላዬ የቆሙትን ዅሉ በበታቼ ታስገዛቸዋለኽ'),
  ('5e6ec950-887d-57b1-ad5e-4ba121bf9f84', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 40, 40, 'የጠላቶቼን ዠርባ ሰጠኸኝ የሚጠሉኝንም አጠፋኻቸው'),
  ('8550d910-d4c3-5e79-abaf-75bd43b35081', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 41, 41, 'ጮኹ የሚረዳቸውም አልነበረም ወደ እግዚአብሔርም ጮኹ አልሰማቸውም'),
  ('19a540bd-4049-5450-af60-8786605eed25', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 42, 42, 'እንደ ትቢያ በነፋስ ፊት እፈጫቸዋለኹ እንደ አደባባይም ጭቃ እረግጣቸዋለኹ'),
  ('ebf324bc-a411-5132-a04c-564543900ad7', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 43, 43, 'ከሕዝብ ክርክር ታድነኛለኽ የአሕዛብም ራስ አድርገኽ ትሾመኛለኽ የማላውቀው ሕዝብም ይገዛልኛል'),
  ('72231fbe-e9de-5f25-a4ac-e45d68f8032e', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 44, 44, 'በዦሮ ሰምተው ተገዙልኝ የባዕድ ልጆች ደለሉኝ'),
  ('fdbe0dde-cc40-572f-af4e-62f56c3ef3ae', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 45, 45, 'የባዕድ ልጆች አረጁ በመንገዳቸውም ተሰናከሉ'),
  ('da5b4cee-adae-5e44-a08f-ac145a867125', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 46, 46, 'እግዚአብሔር ሕያው ነው አምላኬም ቡሩክ ነው የመድኀኒቴም አምላክ ከፍ ከፍ ይበል'),
  ('30c5ba59-f393-5204-a7d2-ddd2b2737425', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 47, 47, 'በቀሌን የሚመልስልኝ አምላክ አሕዛብን በበታቼ ያስገዛልኛል'),
  ('d946abfc-62fb-5098-a0c6-0a8609183e98', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 48, 48, 'ከጠላቶቼ የሚታደገኝ ርሱ ነው በእኔም ላይ ከቆሙ ከፍ ከፍ ታደርገኛለኽ ከግፈኛ ሰው ታድነኛለኽ'),
  ('3a7140e6-77d1-5140-ab9d-f8c43377ddb7', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 49, 49, 'አቤቱ ስለዚህ በአሕዛብ ዘንድ አመሰግንኻለኹ ለስምኽም እዘምራለኹ'),
  ('148d5f8a-88de-537c-a361-8b5f0aa5c9a6', '03ff2814-8526-53f6-ae2a-cb61c41cf517', '5d942b21-6be6-54eb-a018-f3e03379f3fa', 50, 50, 'የንጉሡን መድኀኒት ታላቅ ያደርጋል ቸርነቱንም ለቀባው ለዳዊትና ለዘሩ ለዘለዓለም ይሰጣል'),
  ('9b7e53b6-524f-58b1-aa30-603680c44f80', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 1, 1, 'ሰማያት የእግዚአብሔርን ክብር ይናገራሉ የሰማይም ጠፈር የእጁን ሥራ ያወራል'),
  ('9daa0e61-b953-549f-a5de-c0c4d8f7450a', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 2, 2, 'ቀን ለቀን ነገርን ታወጣለች ሌሊትም ለሌሊት ዕውቀትን ትናገራለች'),
  ('c76bb221-c6ef-598c-abca-750d0d979ac7', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 3, 3, 'ነገር የለም መናገርም የለም ድምፃቸውም አይሰማም'),
  ('25342c69-9903-5b1f-a3c6-0d7c4cdd08ac', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 4, 4, 'ድምፃቸው ወደ ምድር ዅሉ ቃላቸውም እስከዓለም ዳርቻ ወጣ'),
  ('113e2299-5072-56b2-af58-90fa77dfd1f7', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 5, 5, 'በእነርሱም ውስጥ የፀሓይን ድንኳን አደረገ ርሱም እንደ ሙሽራ ከዕልፍኙ ይወጣል እንደ ዐርበኛ በ መንገዱ ለመሮጥ ደስ ይለዋል'),
  ('126b7fcc-6c58-5dc3-ac73-ebcbaab80122', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 6, 6, 'አወጣጡ ከሰማያት ዳርቻ ነው ዙረቱም እስከ ዳርቻቸው ነው ከትኵሳቱም የሚሰወር የለም'),
  ('6a206cdf-539f-53cf-a804-5fecff5a2ef5', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 7, 7, 'የእግዚአብሔር ሕግ ፍጹም ነው ነፍስን ይመልሳል የእግዚአብሔር ምስክር የታመነ ነው ሕፃናትን ጠቢ ባን ያደርጋል'),
  ('8aa1bfc5-6ac6-501c-a293-703f335872b6', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 8, 8, 'የእግዚአብሔር ሥርዐት ቅን ነው ልብንም ደስ ያሠኛል የእግዚአብሔር ትእዛዝ ብሩህ ነው ዐይንንም ያበራል'),
  ('f3df5a44-21d1-5e3d-a79f-b35c84756cdc', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 9, 9, 'የእግዚአብሔር ፍርሀት ንጹሕ ነው ለዘለዓለም ይኖራል የእግዚአብሔር ፍርድ እውነትና ቅንነት በአን ድነት ነው'),
  ('bab25683-a1a7-53ea-a5dd-b66b987bc4bc', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 10, 10, 'ከወርቅና ከክቡር ዕንቍ ይልቅ ይወደዳል ከማርና ከማር ወለላም ይጣፍጣል'),
  ('7642af28-4ae3-50c2-adf7-98e99412e661', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 11, 11, 'ባሪያኽ ደግሞ ይጠብቀዋል በመጠበቁም እጅግ ይጠቀማል'),
  ('8d03bdb9-f0f6-53c7-a0f9-9437dc56e38e', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 12, 12, 'ስሕተትን ማን ያስተውላታል ከተሰወረ ኀጢአት አንጻኝ'),
  ('b2933d48-6f6f-54bb-ad98-f380853810e3', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 13, 13, 'የድፍረት ኀጢአት እንዳይገዛኝ ባሪያኽን ጠብቅ የዚያን ጊዜ ፍጹም እኾናለኹ ከታላቁም ኀጢአት እ ነጻለኹ'),
  ('535f6020-e76f-5a02-adad-6fc3734619c3', '0276e2eb-805b-59d6-a42e-6dc895985a91', '55b3b51e-aa26-5ef3-aee7-6b9cba448332', 14, 14, 'አቤቱ ረድኤቴ መድኀኒቴም የአፌ ቃልና የልቤ ዐሳብ በፊትኽ ያማረ ይኹን'),
  ('99c7ab71-8c9e-5713-a02b-59bef395ba73', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 1, 1, 'በመከራ ቀን እግዚአብሔር ይስማኽ የያዕቆብ አምላክ ስም ያቁምኽ'),
  ('1bdfec45-7b42-586e-a534-27ced88d83f8', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 2, 2, 'ከመቅደሱ ረድኤትን ይላክልኽ ከጽዮንም ያጥናኽ'),
  ('4a3c1693-43bc-5932-a5cb-1f43ca3c3789', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 3, 3, 'ቍርባንኽን ዅሉ ያስብልኽ የሚቃጠል መሥዋዕትኽን ያለምልምልኽ'),
  ('79a66f68-7b07-5343-a1bb-ae5f44d8c68c', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 4, 4, 'እንደ ልብኽ ይስጥኽ ፈቃድኽንም ዅሉ ይፈጽምልኽ'),
  ('f909ba1d-936a-586a-a9df-6620fa80d077', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 5, 5, 'በማዳንኽ ደስ ይለናል በአምላካችን ስም ከፍ ከፍ እንላለን ልመናኽን ዅሉ እግዚአብሔር ይፈጽምልኽ'),
  ('3e3251b2-6240-57e7-a7ca-6f6b305d5bd1', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 6, 6, 'እግዚአብሔር የቀባውን እንዳዳነው ዛሬ ዐወቅኹ ከሰማይ መቅደሱ ይመልስለታል በቀኙ ብርታት ማዳን'),
  ('29169e0b-722e-5cfc-a2da-93e7616b6f65', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 7, 7, 'እነዚያ በሠረገላ እነዚያም በፈረስ ይታመናሉ እኛ ግን በአምላካችን በእግዚአብሔር ስም ከፍ ከፍ እንላለን'),
  ('5737e175-34d3-54aa-afdd-6a279e433a2c', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 8, 8, 'እነርሱ ተሰነካክለው ወደቁ እኛ ግን ተነሣን ጸንተንም ቆምን'),
  ('cb4b6537-59a7-5886-a0d8-dbc13dbe156a', '2953abc8-fc9c-5a0a-aa04-22428d1b6faa', 'e5a4f070-6c45-5638-afb9-f04d75d296fd', 9, 9, 'አቤቱ ንጉሥን አድነው በጠራንኽም ቀን ስማን'),
  ('e97e21ca-6590-5b0a-a8dc-6358033e1cad', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 1, 1, 'አቤቱ በኀይልኽ ንጉሥ ደስ ይለዋል በማዳንኽ እጅግ ሐሤትን ያደርጋል'),
  ('d5b8897b-23a5-5709-a6e2-4e8b2506b065', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 2, 2, 'የልቡን ፈቃድ ሰጠኸው የከንፈሩንም ልመና አልከለከልኸውም'),
  ('24024c55-9fc1-5b7b-a023-7d2db6ba6024', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 3, 3, 'በበጎ በረከት ደርሰኽለታልና ከክቡር ዕንቍ የኾነ ዘውድን በራሱ ላይ አኖርኽ'),
  ('c8c2a097-2da8-5d9b-ad2b-0f0a81984c3b', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 4, 4, 'ሕይወትን ለመነኽ ሰጠኸውም ለረዥም ዘመን ለዘለዓለሙ'),
  ('62f04e9a-d968-573f-a8a7-722f901145bb', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 5, 5, 'በማዳንኽ ክብሩ ታላቅ ነው ክብርንና ምስጋናን ጨመርኽለት'),
  ('d6ae03d7-301a-5667-a303-9a5f3384ae8c', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 6, 6, 'የዘለዓለም በረከትን ሰጥተኸዋልና በፊትኽም ደስታ ደስ ታሠኘዋለኽ'),
  ('ef25d0d0-1dbe-5588-a1be-397ec06b269f', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 7, 7, 'ንጉሥ በእግዚአብሔር ተማምኗልና በልዑልም ምሕረት አይናወጥም'),
  ('b2eb5e3a-113a-5828-a605-6eb32cdc13fe', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 8, 8, 'እጅኽ ጠላቶችኽን ዅሉ ታግኛቸው ቀኝኽም የሚጠሉኽን ዅሉ ታግኛቸው'),
  ('83ea785b-26f8-59de-a7ee-b26fa6d0b479', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 9, 9, 'በተቈጣኽም ጊዜ እንደ እሳት እቶን አድርጋቸው እግዚአብሔር በቍጣው ያጠፋቸዋል እሳትም ትበላቸዋለ ች'),
  ('f4fc5dbb-0667-530c-a9ee-79daa5756c6c', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 10, 10, 'ፍሬያቸውን ከምድር ዘራቸውንም ከሰው ልጆች ታጠፋለኽ'),
  ('2edcd4ee-83bd-5da3-a020-a6bad539d170', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 11, 11, 'ክፋትን ባንተ ላይ ዘርግተዋልና የማይቻላቸውንም ምክር ዐሰቡ'),
  ('a9f92407-a27b-5c7f-afa4-21787d13824f', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 12, 12, 'ወደ ዃላቸው ትመልሳቸዋለኽ ፍላጻን በፊታቸው ላይ ታዘጋጃለኽ'),
  ('917f0adb-62da-51b2-a483-0921b2a89f4f', '85657aea-71b5-5792-a4a4-2cd9dfaac87d', '89551a1e-bcdb-546b-af07-e1bf7390de02', 13, 13, 'አቤቱ በኀይልኽ ከፍ ከፍ በል ጽናትኽንም እናመሰግናለን እንዘምርማለን'),
  ('70e914e9-a223-5fba-a979-3106c1411362', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 1, 1, 'አምላኬ አምላኬ ለምን ተውኸኝ እኔን ከማዳንና ከጩኸቴ ቃል ሩቅ ነኽ'),
  ('1dfae62c-657d-5297-a733-9dfce34d22e8', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 2, 2, 'አምላኬ በቀን ወዳንተ እጠራለኹ አልመለስኽልኝም በሌሊትም እንኳ ዕረፍት የለኝም'),
  ('32d78374-8928-5a1e-a5b3-22e9aa058635', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 3, 3, 'በእስራኤል የተመሰገንኽ አንተ ግን በቅድስና ትኖራለኽ'),
  ('c996db4f-87a7-56f3-ac2a-b8649fea8249', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 4, 4, 'አባቶቻችን አንተን ተማመኑ ተማመኑ አንተም አዳንኻቸው'),
  ('74ccb0f2-24ae-57fe-a705-ec39f5d5d678', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 5, 5, 'ወዳንተ ጮኹ አመለጡም አንተንም ተማመኑ አላፈሩም'),
  ('37f52f18-42b4-5a2f-a57c-7b87579bc8a0', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 6, 6, 'እኔ ግን ትል ነኝ ሰውም አይደለኹም የሰው ማላገጫ በሕዝብም ዘንድ የተናቅኹ ነኝ'),
  ('f3893b59-2fbc-589f-ac61-916a90547cc6', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 7, 7, 'የሚያዩኝ ዅሉ ይላገዱብኛል ራሳቸውን እየነቀነቁ በከንፈሮቻቸው እንዲህ ይላሉ'),
  ('0e8e01ef-54e1-5b72-a7a0-906ab413ef0b', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 8, 8, 'በእግዚአብሔር ተማመነ ርሱንም ያድነው ቢወደ፟ውስ ያድነው'),
  ('2620f9d8-cd20-540b-adaf-b70991f56a90', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 9, 9, 'አንተ ግን ከሆድ አውጥተኸኛልና በእናቴ ጡት ሳለኹም ባንተ ታመንኹ'),
  ('1c43b82f-3af0-58ea-ac20-11fc67ec89bd', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 10, 10, 'ከማሕፀን ዠምሮ ባንተ ላይ ተጣልኹ ከእናቴ ሆድ ዠምረኽ አንተ አምላኬ ነኽ'),
  ('282ee55a-4ee6-5f1d-ab59-0980276b03da', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 11, 11, 'ጭንቀት ቀርባለችና የሚረዳኝም የለምና ከእኔ አትራቅ'),
  ('a0c022d8-ef13-5f5a-a167-d8cddda227a9', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 12, 12, 'ብዙ በሬዎች ከበቡኝ የሰቡትም ፍሪዳዎች ያዙኝ'),
  ('c4004bf9-d9aa-5c84-ae98-09db75f393bd', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 13, 13, 'እንደ ነጣቂና እንደሚጮኽ አንበሳ በላዬ አፋቸውን ከፈቱ'),
  ('9a98c5b8-b39e-5edd-ab1a-f42b1583f594', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 14, 14, 'እንደ ውሃ ፈሰስኹ ዐጥንቶቼም ዅሉ ተለያዩ ልቤ እንደ ሠም ኾነ በአንዠቴም መካከል ቀለጠ'),
  ('5bc97bbe-fa5a-591b-a84f-ae9e3d458d2b', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 15, 15, 'ኀይሌ እንደ ገል ደረቀ በጕረሮዬም ምላሴ ተጣጋ ወደሞትም አሸዋ አወረድኸኝ'),
  ('847e12ce-90ad-571b-a16c-f71eeec9f37a', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 16, 16, 'ብዙ ውሻዎች ከበ፟ውኛልና የክፋተኛዎች ጉባኤም ያዘኝ እጆቼንና እግሮቼን ቸነከሩኝ'),
  ('0fcd2697-e149-55f4-a742-706ffdbefe46', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 17, 17, 'ዐጥንቶቼ ዅሉ ተቈጠሩ እነርሱም አዩኝ ተመለከቱኝም'),
  ('f25f218f-82fe-5e43-ac5b-07447db7c671', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 18, 18, 'ልብሶቼን ለራሳቸው ተከፋፈሉ በቀሚሴም ላይ ዕጣ ተጣጣሉ'),
  ('c0a86b16-eaa8-5d0e-aa72-7793f4a77aa7', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 19, 19, 'አንተ ግን አቤቱ ከእኔ አትራቅ አንተ ጕልበቴ እኔን ለመርዳት ፍጠን'),
  ('3c3687f4-54c7-58cc-a5ff-1c3f30db9e5c', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 20, 20, 'ነፍሴን ከሰይፍ አድናት ብቻነቴንም ከውሻዎች እጅ'),
  ('b6f0dd75-81f1-5783-a8fd-c23d0fdf2fdd', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 21, 21, 'ከአንበሳ አፍ አድነኝ ብቻነቴንም አንድ ቀንድ ካላቸው'),
  ('c1bd6cce-66f0-57df-ac6a-a1a7d998abb5', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 22, 22, 'ስምኽን ለወንድሞቼ እነግራቸዋለኹ በጉባኤም መካከል አመሰግንኻለኹ'),
  ('4c2a4a7a-8d0c-52ce-a4a1-d876e770e0cb', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 23, 23, 'እግዚአብሔርን የምትፈሩ አመስግኑት የያዕቆብ ዘር ዅላችኹ አክብሩት የእስራኤልም ዘር ዅላችኹ ፍ ሩት'),
  ('1216ecdd-bd75-586f-a685-c62d3a9714dd', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 24, 24, 'የችግረኛን ችግር አልናቀምና ቸልም አላለምና ፊቱንም ከእኔ አልሰወረምና ነገር ግን ወደ ርሱ በ ጮኽኹ ጊዜ ሰማኝ'),
  ('e3b79b00-8868-5928-a976-b246924b80e0', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 25, 25, 'በታላቅ ጉባኤ ምስጋናዬ ከአንተ ዘንድ ነው ርሱን በሚፈሩት ፊት ስእለቴን እሰጣለኹ'),
  ('74179ca7-9481-5ea9-a618-f5c2cb26f3fd', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 26, 26, 'ችግረኛዎች ይበላሉ ይጠግቡማል እግዚአብሔርንም የሚሹት ያመሰግኑታል ልባቸውም ለዘለዓለም ሕያው ይኾናል'),
  ('f909aa2c-2a05-5b56-af0e-37192cd2a060', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 27, 27, 'የምድር ዳርቻዎች ዅሉ ያስቡ ወደ እግዚአብሔርም ይመለሱ የአሕዛብ ነገዶች ዅሉ በፊቱ ይሰግዳሉ'),
  ('21661f8c-010b-5eea-ae4d-18d2e8d6b01f', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 28, 28, 'መንግሥት ለእግዚአብሔር ነውና ርሱም አሕዛብን ይገዛል'),
  ('d552eb0f-2672-5948-aa8a-c3abede22206', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 29, 29, 'የምድር ደንዳናዎች ዅሉ ይበላሉ ይሰግዳሉም ወደ መሬት የሚወርዱት ዅሉ በፊቱ ይንበረከካሉ ነፍሴ ም ስለ ርሱ በሕይወት ትኖራለች'),
  ('68905edc-30b1-59c6-adcb-a7c68dfa5a6b', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 30, 30, 'ዘሬ ይገዛለታል የምትመጣው ትውልድ ለእግዚአብሔር ትነግረዋለች'),
  ('72d8f2fc-b6c5-51d2-ae4b-f2d9b7cf39f4', 'b2235508-4b41-5ade-a324-c7236a61d511', 'ec24006e-9b95-544c-a3c3-a715b99d8a99', 31, 31, 'ጽድቁንም ለሚወለደው ሕዝብ እግዚአብሔር ያደረገውን ጽድቁን ይነግራሉ'),
  ('a8363299-e733-5d80-ac34-0db791657b8b', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 1, 1, 'እግዚአብሔር እረኛዬ ነው የሚያሳጣኝም የለም'),
  ('7e88c666-d0f2-53e8-a442-29974f628ec1', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 2, 2, 'በለመለመ መስክ ያሳድረኛል በዕረፍት ውሃ ዘንድ ይመራኛል'),
  ('6d27559d-21bb-57c9-ab7c-3050c85e2681', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 3, 3, 'ነፍሴን መለሳት ስለ ስሙም በጽድቅ መንገድ መራኝ'),
  ('fd83a952-2604-5d69-aa79-e1769b5b9e32', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 4, 4, 'በሞት ጥላ መካከል እንኳ ብኼድ አንተ ከእኔ ጋራ ነኽና ክፉን አልፈራም በትርኽና ምርኵዝኽ እነር ሱ ያጸናኑኛል'),
  ('78d0fddb-82bc-5371-a399-388b203ac5c3', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 5, 5, 'በፊቴ ገበታን አዘጋጀኽልኝ በጠላቶቼ ፊት ለፊት ራሴን በዘይት ቀባኽ ጽዋዬም የተረፈ ነው'),
  ('5bb8d7cc-0a14-5565-a22c-5283e1c38497', 'ff236573-5df3-51cc-a4dd-fcdfe99a3cce', '00731de2-0f69-5ee8-a430-ade3a639f2a1', 6, 6, 'ቸርነትኽና ምሕረትኽ በሕይወቴ ዘመን ዅሉ ይከተሉኛል በእግዚአብሔርም ቤት ለዘለዓለም እኖራለኹ'),
  ('84bf1212-188c-5b0a-a5ac-884227545f5a', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 1, 1, 'ምድርና ሞላዋ ለእግዚአብሔር ናት ዓለምም በርሷም የሚኖሩ ዅሉ'),
  ('ff1a2077-85f2-5e4f-a371-6d040f534c81', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 2, 2, 'ርሱ በባሕሮች መሥርቷታልና በፈሳሾችም አጽንቷታልና'),
  ('2d85fb7a-0417-5972-a403-7eab1b248d44', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 3, 3, 'ወደእግዚአብሔር ተራራ ማን ይወጣል በቅድስናውስ ስፍራ ማን ይቆማል'),
  ('372cec2e-78de-52b4-a60d-776e10c52035', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 4, 4, 'እጆቹ የነጹ ልቡም ንጹሕ የኾነ ነፍሱን ለከንቱ ያላነሣ ለባልንጀራውም በሽንገላ ያልማለ'),
  ('dc0491c3-9754-5349-a394-57513460e639', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 5, 5, 'ርሱ ከእግዚአብሔር ዘንድ በረከትን ከመድኀኒቱ አምላክም ምሕረትን ይቀበላል'),
  ('4a84745a-49a3-5714-a793-e1aa13aac651', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 6, 6, 'ይህች ትውልድ ርሱን የምትፈልግ ናት የያዕቆብን አምላክ ፊት የምትፈልግ'),
  ('59e9df63-3898-5b87-a6b3-0f99c44a309d', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 7, 7, 'እናንት መኳንንቶች በሮችን ክፈቱ የዘለዓለም ደጆችም ይከፈቱ የክብርም ንጉሥ ይግባ'),
  ('508b288e-d2ab-5c91-a1d4-bf022bf84eb3', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 8, 8, 'ይህ የክብር ንጉሥ ማን ነው እግዚአብሔር ነው ብርቱና ኀያል እግዚአብሔር ነው በሰልፍ ኀያል'),
  ('3b418a78-89d3-5cc4-a270-9052175e8f38', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 9, 9, 'እናንተ መኳንንቶች በሮችን ክፈቱ የዘለዓለም ደጆችም ይከፈቱ የክብርም ንጉሥ ይግባ'),
  ('792f524d-09b1-5f10-acc6-b304c0d01581', 'f3fb6054-03b9-554f-a602-302a8eb2b7f5', 'add324d5-e5f9-502b-a691-66b8bb6c09e5', 10, 10, 'ይህ የክብር ንጉሥ ማን ነው የጭፍራዎች አምላክ እግዚአብሔር ርሱ የክብር ንጉሥ ነው'),
  ('a7b27520-2325-5901-ab3a-c42bd998c67c', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 1, 1, 'አቤቱ ወዳንተ ነፍሴን አነሣለኹ'),
  ('b8727ad0-cf55-5693-a21b-6fdd3d079dd5', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 2, 2, 'አምላኬ አንተን ታመንኹ አልፈር ጠላቶቼ በእኔ አይሣቁብኝ'),
  ('688746cb-c12e-5608-ab1e-fe0d84f3ca7c', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 3, 3, 'አንተን ተስፋ የሚያደርጉ አያፍሩም በከንቱ የሚገበዙ ያፍራሉ'),
  ('515ea81e-3ed8-5595-a2fc-719380a39d06', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 4, 4, 'አቤቱ መንገድኽን አመልክተኝ ፍለጋኽንም አስተምረኝ'),
  ('430d9958-d3fe-5625-a453-487a84f8b7da', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 5, 5, 'አንተ የመድኀኒቴ አምላክ ነኽና በእውነትኽ ምራኝ አስተምረኝም ቀኑን ዅሉ አንተን ተስፋ አድርጌያ ለኹ'),
  ('8caa7975-b9e8-53c7-af17-caba83de8033', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 6, 6, 'አቤቱ ምሕረትኽንና ቸርነትኽን ዐስብ ከጥንት ዠምሮ ናቸውና'),
  ('7f0e95c1-4948-52ee-a960-3d2ccce0e7ab', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 7, 7, 'የልጅነቴን ኀጢአትና መተላለፍ አታስብብኝ አቤቱ ስለቸርነትኽ ብዛት እንደ ምሕረትኽ ዐስበኝ'),
  ('85932fa0-1d21-5f88-a7b3-823f984d9dab', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 8, 8, 'እግዚአብሔር ቸር ቅንም ነው ስለዚህ ኀጢአተኛዎችን በመንገድ ይመራቸዋል'),
  ('4bf41d37-9c8a-5fda-a778-bc5b6d2a3e17', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 9, 9, 'ገሮችን በፍርድ ይመራል ለገሮችም መንገድን ያስተምራቸዋል'),
  ('62fb60e2-0a11-5498-ac83-7a50c2d0acea', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 10, 10, 'የእግዚአብሔር መንገድ ዅሉ ቸርነትና እውነት ነው ቃል ኪዳኑንና ምስክሩን ለሚጠብቁ'),
  ('c8f19a3d-dec9-5a3e-a54a-1987c2b3bca1', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 11, 11, 'አቤቱ ኀጢአቴ እጅግ ነውና ስለ ስምኽ ይቅር በለኝ'),
  ('eda24d44-b37a-5b2a-aff6-327edc223afe', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 12, 12, 'እግዚአብሔርን የሚፈራ ሰው ማን ነው በሚመርጠው መንገድ ያስተምረዋል'),
  ('34b15abe-64f3-5a02-ae3b-86daf9f44b68', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 13, 13, 'ነፍሱ በመልካም ታድራለች ዘሩም ምድርን ይወርሳል'),
  ('192682a3-ac78-563e-a074-c61e4a5abc9b', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 14, 14, 'እግዚአብሔር ለሚፈሩት ኀይላቸው ነው ቃል ኪዳኑንም ያስታውቃቸዋል'),
  ('268a50ba-df61-5dbd-a9e3-08bf4ad95c1c', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 15, 15, 'ርሱ እግሮቼን ከወጥመድ ያወጣቸዋልና ዐይኖቼ ዅልጊዜ ወደ እግዚአብሔር ናቸው'),
  ('feaca1d8-6875-5ada-afa5-e9e57a1b45d0', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 16, 16, 'እኔ ብቻዬንና ችግረኛ ነኝና ፊትኽን ወደ እኔ አድርግ ማረኝም'),
  ('8fc01322-82be-50b2-ae80-5ddcada3f20d', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 17, 17, 'የልቤ ችግር ብዙ ነው ከጭንቀቴ አውጣኝ'),
  ('502b33b9-7cf8-51af-afbe-2bd2d0441abb', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 18, 18, 'ድካሜንና መከራዬን እይ ኀጢአቴንም ዅሉ ይቅር በለኝ'),
  ('ad7be2ec-1323-597b-a7fc-b93fcb8c43d7', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 19, 19, 'ጠላቶቼ እንደ በዙ እይ የግፍም ጥል ጠልተውኛል'),
  ('81fb8f2b-c8bc-5a0e-a4c9-4ae9aeea6571', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 20, 20, 'ነፍሴን ጠብቅና አድነኝ አንተን ታምኛለኹና አልፈር'),
  ('7ceb4ec2-94cc-5aa0-ab37-6f8456f05914', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 21, 21, 'አንተን ተስፋ አድርጌያለኹና የውሀትና ቅንነት ይጠብቁኝ'),
  ('2774db03-023f-55d2-aecb-bd249909c405', 'c82eb2ae-928b-57c6-a85f-112254ca7b93', 'c490873e-72bd-52de-af1c-e769fba77ce5', 22, 22, 'አቤቱ እስራኤልን ከመከራው ዅሉ አድነው'),
  ('d829ca0a-0da2-5122-aeed-4dabbd4be3ae', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 1, 1, 'አቤቱ እኔ በየውሀቴ ኼጃለኹና ፍረድልኝ በእግዚአብሔርም አምኛለኹና አልናወጥም'),
  ('7fc86bdc-7e72-56e9-ac97-c8e20b4f2595', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 2, 2, 'አቤቱ ፍተነኝ መርምረኝም ኵላሊቴንና ልቤን ፍተን'),
  ('7025121b-8a7f-516a-a703-29856828dc9c', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 3, 3, 'ምሕረትኽ በዐይኔ ፊት ነውና በእውነትኽም ተመላለስኹ')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('a0941b53-e8cd-5cb5-a5bf-e44eda17b60d', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 4, 4, 'በከንቱ ሸንጎ አልተቀመጥኹም ከዐመፀኛዎችም ጋራ አልገባኹም'),
  ('caf02260-b3bc-5cb3-af37-87a98af8f97b', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 5, 5, 'የክፉዎችን ማኅበር ጠላኹ ከዝንጉዎችም ጋራ አልቀመጥም'),
  ('7d5593f9-5772-5143-a3e5-f4971819f00b', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 6, 6, 'እጆቼን በንጽሕና ዐጥባለኹ አቤቱ መሠዊያኽን እዞራለኹ'),
  ('c5e91308-602b-5c3d-ac9b-6cc45a2c33bd', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 7, 7, 'የምስጋናን ድምፅ እሰማ ዘንድ ተኣምራትኽንም ዅሉ እነግር ዘንድ'),
  ('29adeffb-7d09-5dad-ac46-cfe21ad26b49', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 8, 8, 'አቤቱ የቤትኽን ስፍራ የክብርኽንም ማደሪያ ቦታ ወደድኹ'),
  ('b537beca-c6e2-5d8c-ac50-0c1d80247de3', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 9, 9, 'ከኀጢአተኛዎች ጋራ ነፍሴን ከደም ሰዎችም ጋራ ሕይወቴን አታጥፋ'),
  ('337da4af-7e4c-534e-affb-c5b8d6c3ced5', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 10, 10, 'በእጃቸው ተንኰል አለባቸው ቀኛቸውም መማለጃ ተሞልታለች'),
  ('abd4d7d2-d0b1-504c-ab4a-eda6f7299a56', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 11, 11, 'እኔ ግን በየውሀቴ ኼጃለኹ አድነኝ ማረኝም'),
  ('a8db064c-0067-5c80-af17-5ad0f74a442a', 'f68ec400-a110-56d4-aeae-f413ac2e1075', '5cf164e6-b5f4-5d36-adb2-0888b1bd985b', 12, 12, 'እግሮቼ በቅንነት ቆመዋልና አቤቱ በማኅበር አመሰግንኻለኹ'),
  ('232f5ec3-9b3b-520f-a47b-12f811791bd7', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 1, 1, 'እግዚአብሔር ብርሃኔና መድኀኒቴ ነው የሚያስፈራኝ ማን ነው እግዚአብሔር የሕይወቴ መታመኛዋ ነው የሚያስደነግጠኝ ማን ነው'),
  ('4cbdaaac-105c-52d6-a224-9b27a716fd04', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 2, 2, 'ክፉዎች አስጨናቂዎቼ ጠላቶቼም ሥጋዬን ይበሉ ዘንድ በቀረቡ ጊዜ እነርሱ ተሰናከሉና ወደቁ'),
  ('896b6576-edb3-552b-aa3c-534f2f2ce804', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 3, 3, 'ሰራዊትም ቢሰፍርብኝ ልቤ አይፈራም ሰልፍም ቢነሣብኝ በዚህ እተማመናለኹ'),
  ('8b97648e-bb5f-5ea1-a078-b0c3beb2a611', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 4, 4, 'እግዚአብሔርን አንዲት ነገር ለመንኹት ርሷንም እሻለኹ በሕይወቴ ዘመን ዅሉ በእግዚአብሔር ቤት እ ኖር ዘንድ እግዚአብሔርን ደስ የሚያሠኘውንም አይ ዘንድ መቅደሱንም እመለከት ዘንድ'),
  ('e616e72e-8a0f-5b1b-a0f9-a0bb685fa5a6', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 5, 5, 'በመከራዬ ቀን በድንኳኑ ሰውሮኛልና በድንኳኑም መሸሸጊያ ሸሽጎኛልና በአለት ላይ ከፍ ከፍ አድርጎ ኛልና'),
  ('23c42a2a-5820-5e2a-a094-04279149e6e0', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 6, 6, 'እንሆ አኹን በዙሪያ ባሉ በጠላቶቼ ላይ ራሴን ከፍ ከፍ አደረገ በድንኳኑም የእልልታ መሥዋዕትን ሠዋኹ ለእግዚአብሔር እቀኛለኹ እዘምርለትማለኹ'),
  ('7e368d6e-b57a-55d5-ac52-125364d6e08e', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 7, 7, 'አቤቱ ወዳንተ የጮኽኹትን ቃሌን ስማኝ ማረኝና አድምጠኝ'),
  ('e0a7fc0c-6576-51a2-addb-7c8afde27975', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 8, 8, 'አንተ ፊቴን ሹት ባልኽ ጊዜ፦አቤቱ ፊትኽን እሻለኹ ልቤ አንተን አለ'),
  ('181a2114-8bc0-5819-a24b-0ab56a24eb33', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 9, 9, 'ፊትኽን ከእኔ አትሰውር ተቈጥተኽ ከባሪያኽ ፈቀቅ አትበል ረዳት ኹነኝ አትጣለኝም የመድኀኒቴም አ ምላክ ሆይ አትተወኝ'),
  ('3ab5a081-e5a8-5b16-afbb-a0456e3b0065', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 10, 10, 'አባቴና እናቴ ትተውኛልና እግዚአብሔር ግን ተቀበለኝ'),
  ('c6e271d6-4f89-5704-a4e5-a0f33bc67846', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 11, 11, 'አቤቱ መንገድኽን አስተምረኝ ስለ ጠላቶቼም በቀና መንገድ ምራኝ'),
  ('951fcc9e-548a-5ddd-abba-199a9d79c0af', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 12, 12, 'የሐሰት ምስክሮችና ዐመፀኛዎች ተነሥተውብኛልና ለጠላቶቼ ፈቃድ አትስጠኝ'),
  ('29a4408b-a0b3-51af-afd5-e5ed113e4442', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 13, 13, 'የእግዚአብሔርን ቸርነት በሕያዋን ምድር አይ ዘንድ አምናለኹ'),
  ('015249ba-7b19-587d-a319-f3b357535ac0', '5178f536-f1b0-5815-a0a3-2f2d1e51408e', 'eefed1c9-bb2f-5fd1-ab1c-6e4c0af812f7', 14, 14, 'እግዚአብሔርን ተስፋ አድርግ በርታ ልብኽም ይጽና እግዚአብሔርን ተስፋ አድርግ'),
  ('d12ce09b-c266-5e0f-a9a4-93e62a1a7882', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 1, 1, 'አቤቱ ወዳንተ እጠራለኹ ዝም ብትለኝ ወደ ጕድጓድ እንደሚወርዱት እንዳልመስል አንተ አምላኬ ዝም አትበለኝ'),
  ('59bd44a0-e250-59ec-aeb8-10111c6632ae', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 2, 2, 'ወደ መቅደስኽ ማደሪያ እጄን ባነሣኹ ጊዜ ወዳንተ የጮኽኹትን የልመናዬን ቃል ስማ'),
  ('0fa85d25-22e5-55a7-a963-1f9ef3fb435e', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 3, 3, 'ከኃጥኣንና ከክፉ አድራጊዎች ጋራ ነፍሴን አትውሰዳት ክፋትም በልባቸው እያለ ከባልንጀራቸው ጋራ ሰላም ከሚናገሩት ጋራ አትጣለኝ'),
  ('2544f0cb-13ed-541d-a54f-9583bb8bf957', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 4, 4, 'እንደ ሥራቸው እንደ አካኼዳቸውም ክፋት ስጣቸው እንደ እጃቸውም ሥራ ስጣቸው ፍዳቸውን ወደ ራሳቸ ው መልስ'),
  ('8686f35b-458a-5b87-a2a1-f1b4409976e1', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 5, 5, 'ወደእግዚአብሔር ሥራ ወደ እጆቹም አደራረግ አላሰቡምና ያፈርሳቸዋል እንጂ አይሠራቸውም'),
  ('05345c3c-8646-5965-ac88-93941df902db', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 6, 6, 'የልመናዬን ቃል ሰምቶኛልና እግዚአብሔር ይመስገን'),
  ('9be2998b-2ed9-595f-a522-7a1234a706ff', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 7, 7, 'እግዚአብሔር ኀይሌና ጋሻዬ ነው ልቤ በርሱ ታመነ እኔም ተረዳኹ ሥጋዬም ደስ ይለዋል ፈቅጄም አመ ሰግነዋለኹ'),
  ('a345d4c6-4268-52dc-a2c5-f61be0cca52a', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 8, 8, 'እግዚአብሔር ለሕዝቡ ኀይላቸው ነው ለቀባውም የመድኀኒቱ መታመኛ ነው'),
  ('9aabec7e-27bf-573e-a8c1-3b31442bf188', '332e14d3-62c3-53dc-a6fc-52e9e81c9df4', '5515d411-36cf-5237-a808-63a10e7dfbf4', 9, 9, 'ሕዝብኽን አድን ርስትኽንም ባርክ ጠብቃቸው ለዘለዓለሙም ከፍ ከፍ አድርጋቸው'),
  ('6a0af8b1-b12d-515b-afe6-5223745addc7', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 1, 1, 'የአምላክ ልጆች ሆይ ለእግዚአብሔር አምጡ ክብርንና ምስጋናን ለእግዚአብሔር አምጡ'),
  ('b9027290-8494-5c67-a9c7-00c73949ec2b', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 2, 2, 'የስሙን ክብር ለእግዚአብሔር አምጡ በቅድስናው ስፍራ ለእግዚአብሔር ስገዱ'),
  ('d871caeb-0680-5a7f-a2ab-9c86aa708344', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 3, 3, 'የእግዚአብሔር ድምፅ በውሃዎች ላይ የክብር አምላክ አንጐደጐደ እግዚአብሔር በብዙ ውሃዎች ላይ'),
  ('0a1fd840-450c-51ad-a6bb-ed84000b705e', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 4, 4, 'የእግዚአብሔር ድምፅ በኀይል ነው የእግዚአብሔር ድምፅ በታላቅ ክብር ነው'),
  ('48fc54a3-829f-5d08-a152-f932bc89d8c7', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 5, 5, 'የእግዚአብሔር ድምፅ ዝግባን ይሰብራል እግዚአብሔር የሊባኖስን ዝግባ ይቀጠቅጣል'),
  ('55775634-d28c-57c9-ab76-96146526f960', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 6, 6, 'እንደ ጥጃ ሊባኖስን አንድ ቀን እንዳለው አውሬ ልጅ ስርዮንን ያዘልላቸዋል'),
  ('65bf5740-e2f3-533a-a218-e0b3595ccbae', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 7, 7, 'የእግዚአብሔር ድምፅ የእሳቱን ነበልባል ይቈርጣል'),
  ('70a36d5b-aa5f-5317-a5c8-5fbe3e7d7d06', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 8, 8, 'የእግዚአብሔር ድምፅ ምድረ በዳውን ያናውጣል እግዚአብሔር የቃዴስን ምድረ በዳ ያናውጣል'),
  ('e5ac9ef2-d266-5875-a3c1-9dbd51ec142b', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 9, 9, 'የእግዚአብሔር ድምፅ ዋላዎችን ያጠነክራቸዋል ጫካዎቹንም ይገልጣል ዅሉም በመቅደሱ፦ምስጋና ይላል'),
  ('6d0f493c-e739-5e89-a076-329508485d3a', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 10, 10, 'እግዚአብሔር የጥፋት ውሃን ሰብስቧል እግዚአብሔር ለዘለዓለም ንጉሥ ኾኖ ይቀመጣል'),
  ('1c86fbd1-ce9d-5b34-aa5c-0de8411b52f3', 'e24b452b-ebe0-5d51-a4ed-fa90c20e4e11', 'a04f3b61-b747-5d16-ab27-3c7f634748bd', 11, 11, 'እግዚአብሔር ለሕዝቡ ኀይልን ይሰጣል እግዚአብሔር ሕዝቡን በሰላም ይባርካል'),
  ('c1852d58-ffac-5a3f-a5df-0defad37f875', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 1, 1, 'አቤቱ ተቀብለኸኛልና ጠላቶቼንም ደስ አላሠኘኽብኝምና ከፍ ከፍ አደርግኻለኹ'),
  ('d7cd5405-9fcf-5d76-a238-70e50188cfd7', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 2, 2, 'አቤቱ አምላኬ ወዳንተ ጮኽኹ ምሕረትም አደረግኽልኝ'),
  ('49e1a43b-f329-577e-ac28-c04196d28abe', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 3, 3, 'አቤቱ ነፍሴን ከሲኦል አወጣኻት ወደ ጕድጓድም እንዳልወርድ አዳንኸኝ'),
  ('6a1e5b93-4836-5829-a8da-e489daca6609', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 4, 4, 'ቅዱሳን ሆይ ለእግዚአብሔር ዘምሩ ለቅድስናውም መታሰቢያ አመስግኑ'),
  ('269c47e6-9230-536a-afb6-48211cc6be47', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 5, 5, 'ቍጣው ለጥቂት ጊዜ ነው ሞገሱ ግን ለሕይወት ዘመን ልቅሶ ማታ ይመጣል ጧት ግን ደስታ ይኾናል'),
  ('a6f552da-1029-5e3c-a5b2-ff1531a03982', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 6, 6, 'እኔም በደስታዬ ለዘለዓለም አልታወክም አልኹ'),
  ('da17e0b3-409d-5f3c-a67a-ee8e7d594a5d', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 7, 7, 'አቤቱ በፈቃድኽ ለሕይወቴ ኀይልን ሰጠኻት ፊትኽን መለስኽ እኔም ደነገጥኹ'),
  ('daaeb6a4-7833-595d-ac5b-d9be6d562cdd', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 8, 8, 'አቤቱ ወዳንተ ጠራኹ ወደ አምላኬም ለመንኹ'),
  ('fff7339a-be52-52a7-a18f-93fe6f39a05c', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 9, 9, 'ወደ ጥፋት ብወርድ በደሜ ምን ጥቅም አለ ዐፈር ያመሰግንኻልን እውነትኽንም ይናገራልን'),
  ('4fe138a6-83b9-5cc1-a7c2-e2ec034a382e', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 10, 10, 'እግዚአብሔር ሰማ ማረኝም እግዚአብሔር ረዳቴ ኾነኝ'),
  ('e92317b1-a53f-5e75-a6fd-0611c2d01c4b', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 11, 11, 'ክብሬ ትዘምርልኽ ዘንድ ዝምም እንዳትል ልቅሶዬን ለደስታ ለወጥኽልኝ ማቄን ቀደ፟ኽ ደስታንም አ ስታጠቅኸኝ'),
  ('53fb0235-05aa-55fa-a174-fed14efe0173', 'e6abbde5-fabd-5552-a427-da045444acec', '9c1736b9-ec3a-5ae3-a100-f30bb7bc5290', 12, 12, 'አቤቱ አምላኬ ለዘለዓለም አመሰግንኻለኹ'),
  ('d5a9134b-6748-5993-aa31-fbf459be6622', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 1, 1, 'አቤቱ አንተን ታመንኹ ለዘለዓለም አልፈር በጽድቅኽም አድነኝ'),
  ('01805e2a-b0ae-5eb3-abee-635804142e61', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 2, 2, 'ዦሮኽን ወደ እኔ አዘንብል ፈጥነኽም አድነኝ ታድነኝ ዘንድ መታመኛ አምላክና የመጠጊያ ቤት ኹነኝ'),
  ('187ce5bc-e825-5104-a633-ec5100508c94', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 3, 3, 'ዐምባዬና መጠጊያዬ አንተ ነኽና ስለ ስምኽ መንገዴን አቅና ምራኝም'),
  ('77c31181-1774-5977-a439-3ddc411fa221', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 4, 4, 'አንተ መታመኛዬ ነኽና ከደበቁብኝ ወጥመድ አውጣኝ'),
  ('a665248f-f067-51cb-ad4d-e0134b5c8b03', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 5, 5, 'በእጅኽ ነፍሴን እሰጣለኹ የእውነት አምላክ አቤቱ ተቤዥተኸኛል'),
  ('2530c432-4896-536f-aa9e-78e1581452e3', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 6, 6, 'ከንቱ ምናምንቴነትን የጠበቁትን ጠላኽ እኔ ግን በእግዚአብሔር ታመንኹ'),
  ('bdd5efcf-eba6-5ddd-a81e-52a990c165a1', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 7, 7, 'መከራዬን አይተኻልና ነፍሴንም ከጭንቀት አድነኻታልና በምሕረትኽ ደስ ይለኛል ሐሤትም አደርጋለኹ'),
  ('2da7a2d9-5e32-5dd1-a368-252bbf1b678e', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 8, 8, 'በጠላቴ እጅ አልዘጋኸኝም በሰፊም ስፍራ እግሮቼን አቆምኽ'),
  ('dd70a60b-03eb-516f-a5ca-ebfbc14bc88f', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 9, 9, 'ተቸግሬያለኹና አቤቱ ምራኝ ዐይኔም ከሐዘን የተነሣ ተፈጀች ነፍሴም ሆዴም'),
  ('3f73846d-5ae8-58ae-ade9-81c7c6c249ba', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 10, 10, 'ሕይወቴ በሐዘን አልቃለችና ዓመታቴም በልቅሶ ጩኸት ኀይሌ በችግር ደከመ ዐጥንቶቼም ተነዋወጡ'),
  ('dbc0cb44-0e8f-5634-a734-e0253d26c3c8', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 11, 11, 'በጠላቶቼ ዘንድ ተነወርኹ ይልቁንም በጎረቤቶቼ ዘንድ ለሚያውቁኝም ፍርሀት ኾንኹ በሜዳ ያዩኝም ከእኔ ሸሹ'),
  ('0c7de7c0-831d-5d21-a3e8-697228954b0d', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 12, 12, 'እንደ ሞተ ሰው ከልብ ተረሳኹ እንደ ተበላሸ ዕቃም ኾንኹ'),
  ('56795672-777f-5d3a-a478-aa1383920021', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 13, 13, 'የብዙ ሰዎችን ስድብ ሰምቻለኹና በዙሪያው ፍርሀት ነበረ በላዬ በአንድነት በተሰበሰቡ ጊዜ ነፍሴ ን ለመንጠቅ ተማከሩ'),
  ('c5feb1bb-3eb5-5b32-a1d1-c35b70a1f8ec', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 14, 14, 'አቤቱ እኔ ግን ባንተ ታመንኹ አንተ አምላኬ ነኽ አልኹ'),
  ('ce8204f2-d1ba-5575-a211-d32a348aa20c', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 15, 15, 'ርስቴ በእጅኽ ነው ከጠላቶቼ እጅና ከሚያሳድዱኝ አድነኝ'),
  ('abf826e4-6676-5232-a9d4-011ae78bc2a0', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 16, 16, 'ፊትኽን በባሪያኽ ላይ አብራ ስለ ምሕረትኽም አድነኝ'),
  ('20e2e158-25ee-5246-a33b-dd69adf7182c', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 17, 17, 'አቤቱ አንተን ጠርቻለኹና አልፈር ክፉዎች ይፈሩ በሲኦልም ዝም ይበሉ'),
  ('a9ff2cde-2aa6-53ef-a76a-ff35a7a90d0f', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 18, 18, 'በድፍረትና በትዕቢት በመናቅም በጻድቅ ላይ የሚናገሩ የሽንገላ ከንፈሮች ድዳ ይኹኑ'),
  ('299a2b79-8330-5e2f-ae78-1245400fcf9d', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 19, 19, 'ባንተ ለሚያምኑ በሰው ልጆች ፊት ያዘጋጀኻት ለሚፈሩኽም የሰወርኻት ቸርነትኽ እንደ ምን በዛች!'),
  ('1d80a3d8-b296-5b5b-ab55-530fc5b77ffd', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 20, 20, 'በፊትኽ መጋረጃ ከሰው ክርክር ትጋርዳቸዋለኽ በድንኳንኽም ከአንደበት ክርክር ትሸፍናቸዋለኽ'),
  ('67e57575-cab5-5285-af8b-8a6bca6aeb4f', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 21, 21, 'በተከበበ ከተማ የሚያስደንቅ ምሕረቱን በእኔ የገለጠ እግዚአብሔር ይመስገን'),
  ('51633750-7f65-5f42-ae8c-3d73cd45236c', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 22, 22, 'እኔስ ከዐይንኽ ፊት ተጣልኹ በድንጋጤ አልኹ አንተ ግን ወዳንተ በጮኽኹ ጊዜ የልመናዬን ቃል ሰ ማኸኝ'),
  ('c72794a7-88d4-5a61-ac2e-bbc7913252ee', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 23, 23, 'ዅላችኹ ቅዱሳኑ እግዚአብሔርን ውደዱት እግዚአብሔር እውነተኛዎችን ይፈልጋል ትዕቢተኛዎችንም ፈጽ ሞ ይበቀላቸዋል'),
  ('611c2664-5ad6-51a3-a2e3-5ed35e7aae61', 'faa53375-3e9c-5675-a1d6-573ccf5824e1', '93d5f491-2133-5997-a6bc-05882cc4a6f0', 24, 24, 'በእግዚአብሔር የምታምኑ ዅላችኹ በርቱ ልባችኹም ይጥና'),
  ('3b95763b-ddb9-5b63-a807-ae81ca345325', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 1, 1, 'መተላለፉ የቀረችለት ኀጢአቱም የተከደነችለት ምስጉን ነው'),
  ('a1540429-d2fe-5ea5-aa04-3a4fccf39efa', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 2, 2, 'እግዚአብሔር በደልን የማይቈጥርበት በመንፈሱም ሽንገላ የሌለበት ሰው ምስጉን ነው'),
  ('eedd07f4-2ea9-5dd2-a57e-870a1a0450e1', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 3, 3, 'ዅልጊዜ ከመጮኼ የተነሣ ዝም ባልኹ ጊዜ ዐጥንቶቼ ተበላሹ'),
  ('546b28d3-a765-5499-af12-1e4819ec5349', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 4, 4, 'በቀንና በሌሊት እጅኽ ከብዳብኛለችና ርጥበቴም ለበጋ ትኵሳት ተለወጠ'),
  ('ce8f11f5-4d8c-579f-a800-96a9d53abcc9', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 5, 5, 'ኀጢአቴን ለአንተ አስታወቅኹ በደሌንም አልሸፈንኹም ለእግዚአብሔር መተላለፌን እነግራለኹ አልኹ አ ንተም የልቤን ኀጢአት ተውኽልኝ'),
  ('296bef99-62e5-51c2-a71d-e2b947f7c776', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 6, 6, 'ስለዚህ ቅዱስ ዅሉ በምቹ ጊዜ ወዳንተ ይለምናል ብዙ የጥፋት ውሃም ወደ ርሱ አይቀርብም'),
  ('aa3e66e1-8e05-5cb1-a999-0eef782efe16', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 7, 7, 'አንተ ለእኔ መሸሸጊያዬ ነኽ ከጣርም ትጠብቀኛለኽ ከከበቡኝ ታድነኝ ዘንድ ደስታዬ ነኽ'),
  ('a3cf0b17-7d74-5992-a686-24ae78c90270', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 8, 8, 'አስተምርኻለኹ በምትኼድበትም መንገድ እመራኻለኹ ዐይኖቼን ባንተ ላይ አጠናለኹ'),
  ('3722e0e6-f0f4-556d-ac93-4d02ecd11049', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 9, 9, 'ወዳንተ እንዳይቀርቡ በልባብና በልጓም ጕንጫቸውን እንደሚለጕሟቸው ልብ እንደሌላቸው እንደ ፈረስና እንደ በቅሎ አትኹኑ'),
  ('23ba646d-b925-5a64-afe6-489d9d83cdf3', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 10, 10, 'በኀጢአተኛ ብዙ መቅሠፍት አለበት በእግዚአብሔር የሚታመነውን ግን ምሕረት ይከበ፟ዋል'),
  ('b561d387-b605-51b3-a13d-49ba460151f4', '45cc5225-5614-57a0-a7b4-35dbc9440398', '8cfdb7bc-1be6-5832-a95a-dff9bc0f04a9', 11, 11, 'ጻድቃን ሆይ በእግዚአብሔር ደስ ይበላችኹ ሐሤትም አድርጉ ልባችኹም የቀና ዅላችኹ እልል በሉ'),
  ('49abb471-5e5b-5475-a948-b6a0042c6b86', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 1, 1, 'ጻድቃን ሆይ በእግዚአብሔር ደስ ይበላችኹ ለቅኖች ምስጋና ይገ፟ባ፟ል'),
  ('32669e30-bdba-5e8a-a534-03247762e3fd', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 2, 2, 'እግዚአብሔርን በመሰንቆ አመስግኑት ዐሥር አውታርም ባለው በበገና ዘምሩለት'),
  ('890121bd-fd27-5bac-a742-085612925020', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 3, 3, 'ዐዲስ ቅኔም ተቀኙለት በእልልታም መልካም ዝማሬ ዘምሩ'),
  ('7d288867-9f3a-5def-ab54-4bc4e51d98c8', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 4, 4, 'የእግዚአብሔር ቃል ቅን ነውና ሥራውም ዅሉ በእምነት ነውና'),
  ('6764e909-ed28-5d91-a512-47a7365ba901', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 5, 5, 'ጽድቅንና ፍርድን ይወዳ፟ል የእግዚአብሔር ቸርነት ምድርን ሞላች'),
  ('2d714813-5c16-5623-a498-eb58757f664d', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 6, 6, 'በእግዚአብሔር ቃል ሰማዮች ጸኑ ሰራዊታቸውም ዅሉ በአፉ እስትንፋስ'),
  ('8f580bad-cd50-587f-a5dc-d41a85fe1b5b', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 7, 7, 'የባሕርን ውሃ እንደ ረዋት የሚሰበስበው ቀላዮችንም በመዝገቦች የሚያኖራቸው'),
  ('e24b13ce-8f35-55d7-ac33-4402509f9af0', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 8, 8, 'ምድር ዅሉ እግዚአብሔርን ትፍራው በዓለም የሚኖሩ ዅሉም ከርሱ የተነሣ ይደንግጡ'),
  ('40483de4-b16f-50b4-a74e-db0ffc3865f3', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 9, 9, 'ርሱ ተናግሯልና ኾኑም ርሱ አዘዘ ጸኑም'),
  ('a8c150a1-e7d7-59d5-a7f7-1869e3b04d92', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 10, 10, 'እግዚአብሔር የአሕዛብን ምክር ያጠፋል የአሕዛብንም ዐሳብ ይመልሳል'),
  ('138f2093-4e0d-52fe-a39a-ca6ea7b6b11a', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 11, 11, 'የእግዚአብሔር ምክር ግን ለዘለዓለም ይኖራል የልቡም ዐሳብ ለልጅ ልጅ ነው'),
  ('586c39c2-3eb0-5e6b-ac69-8ab215064cee', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 12, 12, 'እግዚአብሔር አምላኩ የሚኾንለት ሕዝብ ምስጉን ነው ርሱ ለርስቱ የመረጠው ሕዝብ'),
  ('cff6b283-0902-5939-a620-6bc03b37c261', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 13, 13, 'እግዚአብሔር ከሰማይ ተመለከተ የሰውንም ልጆች ዅሉ አየ'),
  ('cfe5ccbf-402e-569d-abd5-cfdccf7e034a', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 14, 14, 'ከማደሪያው ቦታ ኾኖ በምድር ወደሚኖሩ ዅሉ ተመለከተ'),
  ('b2b8e833-ef98-52c2-aa1c-dc910a7f59bd', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 15, 15, 'ርሱ ብቻውን ልባቸውን የሠራ ሥራቸውንም ዅሉ የሚያስተውል'),
  ('23afa20c-b599-5d6e-a36b-a90e208863f0', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 16, 16, 'ንጉሥ በሰራዊቱ ብዛት አይድንም ኀያልም በኀይሉ ብዛት አያመልጥም'),
  ('34d5e4a0-ea26-5384-a54e-a0b19cc4dc4a', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 17, 17, 'ፈረስም ከንቱ ነው አያድንም በኀይሉም ብዛት አያመልጥም'),
  ('e63bff54-727c-55aa-ae5f-fadcae05b14b', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 18, 18, 'እንሆ የእግዚአብሔር ዐይኖች ወደሚፈሩት ናቸው በምሕረቱም ወደሚታመኑ'),
  ('372fda48-f9fb-571d-a659-4c7897039ee3', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 19, 19, 'ነፍሳቸውን ከሞት ያድን ዘንድ በራብም ጊዜ ይመግባቸው ዘንድ'),
  ('b44ffc74-bf35-5037-ab43-4b8c98abb3c6', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 20, 20, 'ነፍሳችን እግዚአብሔርን ተስፋ ታደርገዋለች ረዳታችንና መጠጊያችን ርሱ ነውና'),
  ('810369f5-2294-579d-a254-03291bbbd062', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 21, 21, 'ልባችን በርሱ ደስ ይለዋልና በቅዱስ ስሙም ታምነናልና'),
  ('ea802631-7154-52a6-a386-e8947f430278', 'f706cb84-d286-5eb8-a99f-bf1cb913fa64', 'ae7e94ba-3d7d-5ded-a588-f7234c4f93dd', 22, 22, 'አቤቱ ምሕረትኽ በላያችን ትኹን ባንተ እንደ ታመን፟'),
  ('ce561b1b-e395-517a-a57b-7322a8f514e6', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 1, 1, 'እግዚአብሔርን ዅልጊዜ እባርከዋለኹ ምስጋናውንም ዘወትር በአፌ ነው'),
  ('6f4a0e4b-f1c3-5fea-a03f-7820111b979f', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 2, 2, 'ነፍሴ በእግዚአብሔር ትከብራለች ገሮችም ሰምተው ደስ ይላቸዋል'),
  ('b76f9809-7cba-54c2-ab7b-b18019a3cb70', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 3, 3, 'እግዚአብሔርን ከእኔ ጋራ ታላቅ አድርጉት በአንድነትም ስሙን ከፍ ከፍ እናድርግ'),
  ('09062af2-367a-5372-afe4-1a8419fcdeac', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 4, 4, 'እግዚአብሔርን ፈለግኹት መለሰልኝም ከመከራዬም ዅሉ አዳነኝ'),
  ('b27b653c-bb78-59f5-a0e5-c926b56044ee', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 5, 5, 'ወደ ርሱ ቅረቡ ያበራላችኹማል ፊታችኹም አያፍርም'),
  ('5039e001-3e60-564d-af10-8672ed45ecd8', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 6, 6, 'ይህ ችግረኛ ጮኸ እግዚአብሔርም ሰማው ከመከራውም ዅሉ አዳነው'),
  ('b744ce44-bff7-5f5a-af6f-5e60bbe10337', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 7, 7, 'የእግዚአብሔር መልአክ በሚፈሩት ሰዎች ዙሪያ ይሰፍራል ያድናቸውማል'),
  ('893953a5-dac0-5a34-ac71-636fb8aab9b4', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 8, 8, 'እግዚአብሔር ቸር እንደ ኾነ ቅመሱ እዩም በርሱ የሚታመን ሰው ምስጉን ነው'),
  ('e37b083e-25e9-5ee7-a8ef-d98ed41d6e55', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 9, 9, 'የሚፈሩት አንዳችን አያጡምና ቅዱሳኑ ዅሉ እግዚአብሔርን ፍሩት'),
  ('0b5e5fae-bad9-5e74-aa25-0a992f7ad239', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 10, 10, 'ባለጠጋዎች ደኸዩ ተራቡም እግዚአብሔርን የሚፈልጉትን ግን ከመልካም ነገር ዅሉ አይጐድሉም'),
  ('20c26ac8-7996-54d3-ac01-168cd205af81', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 11, 11, 'ልጆቼ ኑ ስሙኝ እግዚአብሔርን መፍራት አስተምራችዃለኹ'),
  ('4cdf6cea-7e34-5fd8-a6ed-a3576773022a', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 12, 12, 'ሕይወትን የሚፈቅድ ሰው ማን ነው በጎንም ዘመን ለማየት የሚወድ፟'),
  ('1310b204-6d03-5088-a04e-e18500244ec0', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 13, 13, 'አንደበትኽን ከክፉ ከልክል ከንፈሮችኽም ሽንገላን እንዳይናገሩ'),
  ('712753d8-4429-5d4f-a70e-ce56285959dd', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 14, 14, 'ከክፉ ሽሽ መልካምንም አድርግ ሰላምን ሻ ተከተላትም'),
  ('9592af3e-f12a-5cfb-a456-7d3856a3c081', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 15, 15, 'የእግዚአብሔር ዐይኖች ወደ ጻድቃን ዦሮዎቹም ወደ ጩኸታቸው ናቸውና'),
  ('d9f21972-f152-5120-a9ca-d169f27f6150', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 16, 16, 'መታሰቢያቸውን ከምድር ያጠፋ ዘንድ የእግዚአብሔር ፊት ክፉን በሚያደርጉ ላይ ነው'),
  ('e59e01cd-4326-5de0-a77b-eb499afb599f', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 17, 17, 'ጻድቃን ጮኹ እግዚአብሔርም ሰማቸው ከመከራቸውም ዅሉ አዳናቸው'),
  ('9db7a925-d6cd-5634-a006-b23144700161', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 18, 18, 'እግዚአብሔር ልባቸው ለተሰበረ ቅርብ ነው መንፈሳቸው የተሰበረውንም ያድናቸዋል'),
  ('0f87844d-172e-5bd7-a3d4-d35e52ea7a8d', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 19, 19, 'የጻድቃን መከራቸው ብዙ ነው እግዚአብሔርም ከዅሉ ያድናቸዋል'),
  ('46d858ea-1f4a-5a4c-a4eb-dc26791303d3', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 20, 20, 'እግዚአብሔር ዐጥንቶቻቸውን ዅሉ ይጠብቃል ከነርሱም አንድ አይሰበርም'),
  ('7c9bc2e8-c740-5f0a-ad5a-430ef10edc9b', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 21, 21, 'ኀጢአተኛዎችን ክፋት ይገድላቸዋል ጻድቃንንም የሚጠሉ ይጸጸታሉ'),
  ('dc279fe5-9236-52a4-a8cb-449d65cff268', '669dd0ad-e463-50e2-a8ea-d9372bae831d', '0c4da6eb-0bbc-59f1-ab60-281275a5ce6a', 22, 22, 'የባሪያዎቹን ነፍስ እግዚአብሔር ይቤዣል በርሱም የሚያምኑ ዅሉ አይጸጸቱም'),
  ('ea9077bd-0505-5b0b-a59e-415b55848da2', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 1, 1, 'አቤቱ የሚበድሉኝን በድላቸው የሚዋጉኝንም ተዋጋቸው'),
  ('1534e7b0-56ce-5781-aa64-9442d065764e', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 2, 2, 'ጥሩርና ጋሻ ያዝ እኔንም ለመርዳት ተነሥ'),
  ('5504489c-5bfb-586b-a2ea-f537e419a0bb', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 3, 3, 'ሰይፍኽን ምዘዝ የሚያሳድዱኝንም መንገዳቸውን ዝጋ ነፍሴን፦መድኀኒትሽ እኔ ነኝ በላት'),
  ('78db1585-bca9-5484-a852-0fc18b0e9218', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 4, 4, 'ነፍሴን የሚሹ ዅሉ ይፈሩ ይጐስቈሉም ክፋትን በእኔ ላይ የሚያስቡ ይፈሩ ወደ ዃላቸውም ይበሉ'),
  ('428cd311-0da7-55f2-a1bd-719ed1f1d9d7', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 5, 5, 'በነፋስ ፊት እንዳለ ትቢያ ይኹኑ የእግዚአብሔርም መልአክ ያስጨንቃቸው'),
  ('02fc81d9-fb95-5ad6-a340-37a50eba5c55', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 6, 6, 'መንገዳቸው ድጥና ጨለማ ይኹን የእግዚአብሔርም መልአክ ያሳ፟ዳ፟ቸው'),
  ('610255ed-4a28-55b2-a9c1-4205733ce3e1', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 7, 7, 'በከንቱ ያጠፉኝ ዘንድ ወጥመዳቸውን ሸሽገውብኛልና ነፍሴን በከንቱ አበሳጭተዋልና'),
  ('c56d85db-9ca8-5dbd-ac61-40541193fd5e', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 8, 8, 'ያላወቁት ወጥመድ ይምጣባቸው የሸሸጉትም ወጥመድ ይያዛቸው በዚህ ወጥመድ ውስጥ ይውደቁ'),
  ('02d025fe-86dc-5980-ab1b-070ea096cbf7', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 9, 9, 'ነፍሴ ግን በእግዚአብሔር ደስ ይላታል በማዳኑም ሐሴት ታደርጋለች'),
  ('323eeeb0-5dd6-5dee-a141-39f90ec1746c', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 10, 10, 'ዐጥንቶቼ ዅሉ እንዲህ ይሉኻል፦አቤቱ እንደ አንተ ማን ነው ችግረኛን ከሚቀማው እጅ ችግረኛንና ድኻውንም ከሚነጥቀው እጅ ታድነዋለኽ'),
  ('c842eddb-b019-5fbc-aee7-dfae3b06331d', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 11, 11, 'የክፋት ምስክሮች ተነሡብኝ የማላውቀውንም በእኔ ላይ ተናገሩ'),
  ('81ae980f-774c-5ed2-ab0e-d6f918610d34', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 12, 12, 'ስለ በጎ ክፋትን መለሱልኝ ነፍሴንም ልጆችን አሳጧት'),
  ('5ac41a7e-d55a-5aab-a491-ad5beca2e4a5', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 13, 13, 'እኔስ እነርሱ በታመሙ ጊዜ ማቅ ለበስኹ ነፍሴንም በጾም አደከምዃት ጸሎቴም ወደ ብብቴ ተመለሰ'),
  ('8e91ba8a-093d-5e3f-a9e3-0b22b6ea233a', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 14, 14, 'ለወዳጄና ለወንድሜ እንደማደርግ አደረግኹ ለእናቱም እንደሚያለቅስ ራሴን ዝቅ ዝቅ አደረግኹ'),
  ('819eef84-4b59-542b-af5b-4fc44b0816b0', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 15, 15, 'በእኔ ላይ ተሰበሰቡ ደስም አላቸው ግፈኛዎች በእኔ ላይ ተሰበሰቡ እኔም አላውቅኹም ቀደዱኝ አል ተዉኝምም'),
  ('c076b6f9-b9e9-5238-aa89-fa28d089219c', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 16, 16, 'ፈተኑኝ በሣቅም ዘበቱብኝ ጥርሳቸውንም በእኔ ላይ አንቀጫቅጩ'),
  ('d4dd3e88-6821-55b5-ad69-12a9aa129c37', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 17, 17, 'አቤቱ እስከ መቼ ድረስ ታይልኛለኽ ነፍሴን ከክፉ ሥራቸው ብችነቴንም ከአንበሳዎች አድናት'),
  ('d85f2049-3f9b-5178-a8db-5d1597dfbb1d', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 18, 18, 'አቤቱ በታላቁ ጉባኤ ውስጥ እገዛልኻለኹ በብዙ ሕዝብ መካከልም አመሰግንኻለኹ'),
  ('e8565287-130d-55d4-ac0d-c7e136cc734f', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 19, 19, 'በግፍ የሚጠሉኝ በላዬ ደስ አይበላቸው በከንቱ የሚጣሉኝም በዐይናቸው አይጣቀሱብኝ'),
  ('9a90a641-de08-5fa5-a4b0-46aa68c1fa74', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 20, 20, 'ለኔስ ሰላምን ይናገሩኛልና በቍጣም ሽንገላን ይመክራሉ'),
  ('1c224f5e-6c31-5dd1-a130-964e11a23766', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 21, 21, 'አፋቸውንም በእኔ ላይ አላቀቁ ዕሠይ ዕሠይ ዐይናችን አየው ይላሉ'),
  ('06edba16-e90e-5c90-a1f4-11878508fa6d', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 22, 22, 'አቤቱ አንተ አየኸው ዝም አትበል አቤቱ ከእኔ አትራቅ'),
  ('74c845b1-dccd-5683-ad9c-0b0487179783', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 23, 23, 'አምላኬ ጌታዬም ወደ ፍርዴ ተነሥ አቤቱ ፍርዴን አድምጥ'),
  ('2b7ece85-d274-51e8-aaf2-6736d05b23b7', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 24, 24, 'አቤቱ አምላኬ እንደ ጽድቅኽ ፍረድልኝ በላዬም ደስ አይበላቸው'),
  ('ad788d6d-7588-57a4-a3e7-3f5f4ad16dc5', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 25, 25, 'በልባቸው፦ዕሠይ ዕሠይ ነፍሳችንን ደስ አላት አይበሉ ደግሞም፦ዋጥነው አይበሉ'),
  ('9a9a08e0-957d-5b56-a9d3-1a758c8a7128', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 26, 26, 'በመከራዬ ደስ የሚላቸው ይፈሩ በአንድነትም ይጐስቍሉ በእኔ ላይ የሚታበዩ ዕፍረትንና ጕስቍልናን ይልበሱ'),
  ('08d5a77e-c168-5a4d-a818-a4132f246842', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 27, 27, 'ጽድቄን የሚወዷ፟ት ደስ ይበላቸው ሐሴትንም ያድርጉ የባሪያውን ሰላም የሚወድ፟ እግዚአብሔር ታላ ቅ ይኹን ዘወትር ይበሉ'),
  ('6abb044b-674a-589b-a43c-2a41947f3414', '22da561d-06a3-5c27-af1e-2371f08f8dc2', 'cce1ae0e-f10d-5906-acf6-79f1e2470cbd', 28, 28, 'ምላሴ ጽድቅኽን ዅልጊዜም ምስጋናኽን ይናገራል'),
  ('11ec0d6e-8c60-5a87-a52b-c50e0b12d138', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 1, 1, 'ኀጢአተኛ በራሱ የሚያስት ነገርን ይናገራል የእግዚአብሔርም ፍርሀት በዐይኖቹ ፊት የለም'),
  ('886083b5-318a-5dc1-a7e6-3113b01e485c', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 2, 2, 'በአንደበቱ ሸንግሏልና ኀጢአቱ ባገኘችው ጊዜ ይጠላታል'),
  ('db879773-a9df-56da-a4bb-816e8970a8f1', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 3, 3, 'የአፉ ቃል ግፍና ሽንገላ ነው ማስተዋልን በጎ ማድረግንም ተወ'),
  ('bc2de4c2-df5f-50eb-a645-32f9a6dd099c', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 4, 4, 'በመኝታው ጠማማነትን ዐሰበ መልካም ባልኾነች መንገድ ቆሟል ክፋትን አይንቃትም'),
  ('98a57968-e4bc-59da-a609-c9298a5a31a3', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 5, 5, 'አቤቱ ምሕረትኽ በሰማይ ነው እውነትኽም ወደ ደመናት ትደርሳለች'),
  ('26c4a9b3-f716-55a0-a220-2e74ec3a1b6b', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 6, 6, 'ጽድቅኽም እንደእግዚአብሔር ተራራዎች ፍርድኽም እጅግ ጥልቅ ናት አቤቱ ሰውንና እንስሳን ታድናለኽ'),
  ('5b2c36fc-32fc-58db-a3b0-bfae0b0c5a48', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 7, 7, 'አቤቱ ምሕረትኽን እንዴት አበዛኽ! የሰው ልጆች በክንፎችኽ ጥላ ይታመናሉ'),
  ('081fd5e6-7806-5557-a6fc-0de4aa3d05ce', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 8, 8, 'ከቤትኽ ጠል ይጠጣሉ ከተድላም ፈሳሽ ታጠጣቸዋለኽ'),
  ('e41b39bd-b467-566d-aa3f-1fa38af488e1', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 9, 9, 'የሕይወት ምንጭ ከአንተ ዘንድ ነውና በብርሃንኽ ብርሃንን እናያለን'),
  ('f236ba31-d900-59df-a43b-d78f6df634a2', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 10, 10, 'ምሕረትኽን በሚያውቁኽ ላይ ጽድቅኽንም ልባቸው በቀና ላይ ዘርጋ'),
  ('70d7f9cd-f2f3-56be-a0b2-66fb912ff264', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 11, 11, 'የትዕቢት እግር አይምጣብኝ የኀጢአተኛዎችም እጅ አያውከኝ'),
  ('f1d3b739-0574-53c6-a49a-acb270d746c7', 'e1c71e8d-91ef-51a3-aa31-bf51e2d87d26', '620d092c-7743-50a3-a4ae-96c12551d6f8', 12, 12, 'ዐመፃን የሚያደርጉ ዅሉ ከዚያ ወደቁ ወድቀዋል መቆምም አይችሉም'),
  ('b9819d4c-da3f-5045-a78c-587bda101350', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 1, 1, 'በክፉዎች ላይ አትቅና ዐመፃንም በሚያደርጉ ላይ አትቅና'),
  ('c7ee942b-1138-5bce-ae44-99db13dc03e5', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 2, 2, 'እንደ ሣር ፈጥነው ይደርቃሉና እንደ ለመለመ ቅጠልም ይረግፋሉና'),
  ('94c3136c-26e8-57f6-a9d9-bc0cfbf832cb', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 3, 3, 'በእግዚአብሔር ታመን መልካምንም አድርግ በምድርም ተቀመጥ ታምነኽም ተሰማራ'),
  ('3262f535-9f04-503b-ae98-3287f840b49e', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 4, 4, 'በእግዚአብሔር ደስ ይበልኽ የልብኽንም መሻት ይሰጥኻል'),
  ('8df0abf9-5184-5c71-a66c-c83e7c7869cb', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 5, 5, 'መንገድኽን ለእግዚአብሔር ዐደራ ስጥ በርሱም ታመን ርሱም ያደርግልኻል'),
  ('eaa62277-a4a9-50e8-a8ce-7f496649e22d', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 6, 6, 'ጽድቅኽን እንደ ብርሃን ፍርድኽንም እንደ ቀትር ያመጣል'),
  ('8128cfd7-8e77-5708-a1d5-d5ddf3502b48', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 7, 7, 'ለእግዚአብሔር ተገዛ ተስፋም አድርገው መንገድም በቀናችለትና ጥመትን በሚያደርግ ሰው አትቅና'),
  ('a448a8e2-771c-5bb1-ae28-e63e4d12f58d', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 8, 8, 'ከቍጣ ራቅ መዓትንም ተው እንዳትበድል አትቅና'),
  ('065c5cce-4075-5aea-a9c9-7babde26f6a8', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 9, 9, 'ክፉ አድራጊዎች ይጠፋሉና እግዚአብሔርን ተስፋ የሚያደርጉ ግን እነርሱ ምድርን ይወርሳሉ'),
  ('884e438d-1a9b-5db3-a990-b16b8ad5aee7', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 10, 10, 'ገና ጥቂት ኀጢአተኛም አይኖርም ትፈልገዋለኽ ቦታውንም አታገኝም'),
  ('7561e1ea-560d-5e5b-ac92-7682f2877d4d', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 11, 11, 'ገሮች ግን ምድርን ይወርሳሉ በብዙም ሰላም ደስ ይላቸዋል'),
  ('fd4bcc71-32f6-5ed4-a59b-dd0dc700955c', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 12, 12, 'ኀጢአተኛ ጻድቁን ይመለካከተዋል ጥርሱንም በርሱ ላይ ያንገጫግጫል'),
  ('0306094e-1222-566c-a80d-948d3e5b9176', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 13, 13, 'እግዚአብሔር ይሥቅበታል ቀኑ እንደሚደርስ አይቷልና'),
  ('b2835b10-191f-52c0-aa91-bd1190f764a3', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 14, 14, 'ኀጢአተኛዎች ሰይፋቸውን መዘዙ ቀስታቸውንም ገተሩ ድኻውንና ችግረኛውን ይጥሉ ዘንድ ልበ ቅኖችን ም ይወጉ ዘንድ'),
  ('e5559e1e-0d5a-5501-a9df-858c01cd6de2', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 15, 15, 'ሰይፋቸው ወደ ልባቸው ይግባ ቀስታቸውም ይሰበር'),
  ('7f303d19-b4e2-57cc-a405-871d1ab84ccb', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 16, 16, 'ለጻድቅ ያለው ጥቂት ከብዙ ከኀጢአተኛዎች ሀብት ይበልጣል'),
  ('3b518759-1950-5c0a-adf6-fc8baf61f415', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 17, 17, 'የኃጥኣን ክንድ ትሰበራለችና እግዚአብሔር ግን ጻድቃንን ይደግፋቸዋል'),
  ('d7a0fd3c-cba9-54e5-a36c-58e738f77800', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 18, 18, 'የንጹሓንን መንገድ እግዚአብሔር ያውቃል ርስታቸውም ለዘለዓለም ነው'),
  ('08549841-28a9-5a05-a3a3-6b24526f86a1', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 19, 19, 'በክፉ ዘመንም አያፍሩም በራብ ዘመንም ይጠግባሉ'),
  ('63362a1a-370c-5b05-ac44-09dc069f83ad', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 20, 20, 'ኃጥኣን ግን ይጠፋሉ የእግዚአብሔር ጠላቶች በከበሩና ከፍ ከፍ ባሉ ጊዜ እንደ ጢስ ይጠፋሉ'),
  ('cdb2b409-f92d-5386-adb5-355dc98cfd0f', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 21, 21, 'ኀጢአተኛ ይበደራል አይከፍልምም ጻድቅ ግን ይራራል ይሰጣልም'),
  ('2d8814c8-ae9e-53b4-a85f-4e3f35974ab2', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 22, 22, 'ርሱን የሚባርኩት ምድርን ይወርሳሉና የሚረግሙት ግን ይጠፋሉ'),
  ('bc2f1207-0db1-53a3-abf3-bcab4eef5bfe', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 23, 23, 'የሰው አካኼድ ከእግዚአብሔር ዘንድ ይጸናል መንገዱንም ይወዳ፟ል'),
  ('0825dba1-df89-5b79-af1e-aaad26bea079', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 24, 24, 'ቢወድቅም ለድንጋፄ አይጣልም እግዚአብሔር እጁን ይዞ ይደግፈዋልና'),
  ('789e4aa7-4749-52eb-aa3f-643bd39da8cc', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 25, 25, 'ጐለመስኹ አረጀኹም ጻድቅ ሲጣል ዘሩም እኽል ሲለምን አላየኹም'),
  ('374321b0-dec8-51b4-abe1-4360c69f19fe', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 26, 26, 'ዅልጊዜ ይራራል ያበድርማል ዘሩም በበረከት ይኖራል'),
  ('dde25611-c3ee-5ffd-adff-b3837544f783', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 27, 27, 'ከክፉ ሽሽ መልካምንም አድርግ ለዘለዓለምም ትኖራለኽ'),
  ('653f7133-7821-5252-a48e-10f62b3edd5b', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 28, 28, 'እግዚአብሔር ፍርዱን ይወዳ፟ልና ቅዱሳኑንም አይጥላቸውምና ለዘለዓለምም ይጠብቃቸዋል ለንጹሓንም ይበቀልላቸዋል የኃጥኣን ዘር ግን ይጠፋል'),
  ('208e5c74-9b68-5472-a38c-d100a7692b5c', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 29, 29, 'ጻድቃን ምድርን ይወርሳሉ በርሷም ለዘለዓለም ይኖራሉ'),
  ('a43b3096-d315-5504-a031-5a96ac289d1a', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 30, 30, 'የጻድቅ አፍ ጥበብን ያስተምራል አንደበቱም ፍርድን ይናገራል'),
  ('0b4d3cc0-618b-58b6-a6ef-c59dd38d814f', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 31, 31, 'የአምላኩ ሕግ በልቡ ውስጥ ነው በርምጃውም አይሰናከልም'),
  ('c188de94-7527-5ca2-a846-a3d37e39a13d', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 32, 32, 'ኀጢአተኛ ጻድቁን ይመለከተዋል ሊገድለውም ይወዳ፟ል'),
  ('2c4cc1cf-ac5a-5acf-a2e9-2184bbb4ae84', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 33, 33, 'እግዚአብሔር ግን በእጁ አይተወውም በተፋረደውም ጊዜ አያሸንፈውም'),
  ('175f7348-ba57-57be-ac44-17dcf81bf4f6', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 34, 34, 'እግዚአብሔርን ደጅ ጥና መንገዱንም ጠብቅ ምድርንም ትወርስ ዘንድ ከፍ ከፍ ያደርግኻል ኀጢአተኛ ዎችም ሲጠፉ ታያለኽ'),
  ('e61f244f-ee99-5bc4-afc3-cc00fac86650', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 35, 35, 'ኃጥኣን ከፍ ከፍ ብሎ እንደ ሊባኖስ ዝግባም ለምልሞ አየኹት'),
  ('f50aa10b-2f7e-55d7-ac3b-a9a769354850', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 36, 36, 'ብመለስ ግን ዐጣኹት ፈለግኹት ቦታውንም አላገኘኹም'),
  ('818c0169-e474-5387-a439-cc09af814d0c', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 37, 37, 'ቅንነትን ጠብቅ ጽድቅንም እይ ለሰላም ሰው ቅሬታ አለውና'),
  ('9e2d7f7c-7e5b-56c5-a409-c0e884648b0a', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 38, 38, 'በደለኛዎች በአንድነት ይጠፋሉ የኀጢአተኛዎች ቅሬታ ይጠፋል'),
  ('1a878d75-7090-544e-a1cc-326f1f580cfc', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 39, 39, 'የጻድቃን መድኀኒታቸው ከእግዚአብሔር ዘንድ ነው በመከራቸውም ጊዜ መጠጊያቸው ርሱ ነው'),
  ('49c58770-8cf8-514c-afe5-be54944ea758', '377993de-10d3-505a-a465-dc3e58896d01', 'acfb075f-952d-5834-a3ee-dfb326996bb4', 40, 40, 'እግዚአብሔር ይረዳቸዋል ያድናቸዋልም ከኀጢአተኛዎችም እጅ ያወጣቸዋል ያድናቸዋል በርሱ ታምነዋል ና'),
  ('1c2e9e5a-f081-572b-a56c-6dcbba55d568', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 1, 1, 'አቤቱ በቍጣኽ አትቅሠፈኝ በመዓትኽም አትገሥጸኝ'),
  ('c1624b58-6a5e-567a-a9e8-ce6063daa72a', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 2, 2, 'ፍላጻዎችኽ ወግተውኛልና እጅኽንም አክብደኽብኛልና'),
  ('0a009de0-fb67-5bcd-a7ee-5c882cc7e239', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 3, 3, 'ከቍጣኽ የተነሣ ለሥጋዬ ጤና የለውም ከኀጢአቴም የተነሣ ለዐጥንቶቼ ሰላም የላቸውም'),
  ('90118812-aa1a-5b38-a1d3-96756c0f46ee', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 4, 4, 'ኀጢአቴ በራሴ ላይ ከፍ ከፍ ብሏልና እንደ ከባድ ሸክምም በላዬ ከብዷልና'),
  ('d5f33864-d828-5093-abb4-5c9078abd809', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 5, 5, 'ከስንፍናዬ የተነሣ ቍስሌ ሸተተ በሰበሰም'),
  ('712fd93e-9283-5169-ade5-c500052f7179', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 6, 6, 'እጅግ ጐሰቈልኹ ተዋረድኹም ዅልጊዜም በትካዜ እመላለሳለኹ'),
  ('9d2672f9-0e7a-5bba-abb8-659dc3180865', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 7, 7, 'ነፍሴ ስድብን ተሞልታለችና ለሥጋዬም ጤና የላትምና'),
  ('42dc2812-d3eb-5291-a9db-1a216ca59b05', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 8, 8, 'ታመምኹ እጅግም ተቸገርኹ ከልቤ ውዝዋዜም የተነሣ ጮኽኹ'),
  ('3ee81dc6-6b90-5cb2-a53d-3d6417f2a767', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 9, 9, 'አቤቱ ፈቃዴ ዅሉ በፊትኽ ነው ጭንቀቴም ከአንተ አይሰወርም'),
  ('37e582a3-16ed-5bca-aabd-1941f888ebb1', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 10, 10, 'ልቤ ደነገጠብኝ ኀይሌም ተወችኝ የዐይኖቼም ብርሃን ፈዘዘ'),
  ('232369c7-5259-510d-a4c1-cc72f0730d99', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 11, 11, 'ወዳጆቼም ባልንጀራዎቼም ከቍስሌ ገለል ብለው ቆሙ ዘመዶቼም ርቀው ቆሙ'),
  ('17e84cfa-3356-5413-a5ce-e3e750bc63a6', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 12, 12, 'ነፍሴንም የሚሿት በረቱብኝ መከራዬንም የሚፈልጉ ከንቱን ተናገሩ ዅልጊዜም በሽንገላ ይመክራሉ'),
  ('6277eb96-3dd9-59d1-a6d6-ae862e32d134', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 13, 13, 'እኔ ግን እንደማይሰማ ደንቈሮ አፉንም እንደማይከፍት ዲዳ ኾንኹ'),
  ('1657813b-f5bb-568d-a590-cb8afc037a60', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 14, 14, 'እንደማይሰማ ሰው በአፉም ተግሣጽ እንደሌለው ሰው ኾንኹ'),
  ('fbc0419e-372a-5c74-a7cb-5895fcdc2393', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 15, 15, 'አቤቱ ባንተ ታምኛለኹና አቤቱ አምላኬ አንተ ትሰማኛለኽ'),
  ('49bce40d-1e89-5eeb-a783-007f8695ce84', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 16, 16, 'ጠላቶቼ በእኔ ላይ ደስ እንዳይላቸው ብያለኹና እግሮቼም ቢሰናከሉ ራሳቸውን በእኔ ላይ ከፍ ከፍ ያደርጋሉ'),
  ('f719002b-1fde-5f10-ad5f-dd5225a7e8ec', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 17, 17, 'እኔስ ወደ ማንከስ ቀርቤያለኹና ቍስሌም ዅልጊዜም በፊቴ ነውና'),
  ('84a4cdd3-cbac-5d5c-ae09-f67d06d9b581', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 18, 18, 'በደሌን እናገራለኹና ስለ ኀጢአቴም እተክዛለኹ'),
  ('be4ce26e-edd3-5b09-a338-0412ec95b318', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 19, 19, 'ጠላቶቼ ሕያዋን ናቸው ይበረቱብኝማል በጠማማነትም የሚጠሉኝ በዙ'),
  ('9c5841e3-2c4d-5769-a860-d148d6c6746e', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 20, 20, 'ጽድቅን ስለ ተከተልኹ በበጎ ፋንታ ክፉን የሚመልሱልኝ ይጠሉኛል'),
  ('7eb70270-ea40-50d9-a6da-a8ca4c2111e0', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 21, 21, 'አቤቱ አንተ አትጣለኝ አምላኬ ከእኔ አትራቅ'),
  ('7f31dfc3-7069-5b33-adb5-055286e992bd', '32e7e72b-b4d9-5d83-a67e-d5689ba876a3', '53f9a0e4-5f73-500c-a32f-e0ea56de8941', 22, 22, 'አቤቱ መድኀኒቴ እኔን ለመርዳት ፍጠን'),
  ('23a46562-e076-5728-a520-0352f3f163f8', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 1, 1, 'በአንደበቴ እንዳልስት መንገዴን እጠብቃለኹ ኀጢአተኛ በፊቴ በተቃወመኝ ጊዜ በአፌ ላይ ጠባቂ አኖ ራለኹ አልኹ'),
  ('fd16bbfa-df53-559b-a786-5d3ebb4d7fe7', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 2, 2, 'ከዝምታ የተነሣ እንደ ዲዳ ኾንኹ ለበጎ እንኳ ዝም አልኹ ቍስሌም ታደሰብኝ'),
  ('3ec25e3a-49c1-5b0a-ad30-8043a8c6d804', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 3, 3, 'ልቤም በውስጤ ሞቀብኝ ከማሰቤም የተነሣ እሳት ነደደ በአንደበቴም ተናገርኹ'),
  ('02a27051-7dc4-5bfd-ab35-8c8182338889', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 4, 4, 'አቤቱ ፍጻሜዬን አስታውቀኝ የዘመኔ ቍጥሮች ምን ያኽል እንደ ኾኑ እኔ ምን ያኽል ወደ ዃላ እንደ ምቀር ዐውቅ ዘንድ'),
  ('292b7780-31ab-558f-aea9-13dc6f3d5650', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 5, 5, 'እንሆ ዘመኖቼን አስረጀኻቸው አካሌም በፊትኽ እንደ ኢምንት ነው ሕያው የኾነ ሰው ዅሉ በእውነት ከንቱ ብቻ ነው'),
  ('0d78474c-d4b9-5baf-a0f1-e87bce1c0082', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 6, 6, 'በከንቱ ይታወካል እንጂ በእውነት ሰው እንደ ጣላ ይመላለሳል ያከማቻል የሚሰበስብለትንም አያውቅም'),
  ('c991e15c-4e46-51ad-a5cb-b1223bec2597', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 7, 7, 'አኹንስ ተስፋዬ ማን ነው እግዚአብሔር አይደለምን ትዕግሥቴም ከአንተ ዘንድ ነው'),
  ('d0758b65-028c-5b50-a9fb-a6d9c406aafe', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 8, 8, 'ከኀጢአቴ ዅሉ አድነኝ ለሰነፎችም ስድብ አታድርገኝ'),
  ('157a1f42-d5c4-5f5a-ae9e-aff4419f1ad4', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 9, 9, 'አንተ ሠርተኸኛልና ዝም አልኹ አፌንም አልከፈትኹም'),
  ('84d557bc-fb71-5838-a627-f47a8a150808', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 10, 10, 'መቅሠፍትኽን ከእኔ አርቅ ከእጅኽ ብርታት የተነሣ አልቄያለኹና'),
  ('8100cd0f-7ef5-5c25-a189-b5096ef98b08', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 11, 11, 'በተግሣጽኽ ስለ ኀጢአቱ ሰውን ዘለፍኸው ነፍሱም እንደ ሸረሪት ድር ታልቃለች በእውነት ሰው ዅሉ ከንቱ ነው'),
  ('b03f6304-72be-5683-a777-21d46b2b0203', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 12, 12, 'አቤቱ ጸሎቴን ስማ ጩኸቴንም አድምጥ ልቅሶዬንም ቸል አትበለኝ እኔ በምድር ላይ መጻተኛ ነኝና እንደ አባቶችም እንግዳ ነኝና'),
  ('02bebccc-a95c-56d8-ad8d-a7a6ad723062', '07d7be18-0369-5735-a787-4984db05ee50', 'c6d7dfda-3737-5842-aa66-f6c6b628c9f1', 13, 13, 'ወደማልመለስበት ሳልኼድ ዐርፍ ዘንድ ተወኝ'),
  ('5af3dc13-deb5-5bd3-abce-a3446c55131b', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 1, 1, 'ቈይቼ እግዚአብሔር ደጅ ጠናኹት ርሱም ዘንበል አለልኝ ጩኸቴንም ሰማኝ')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('cdeb1689-9d7c-5681-ac74-34a040f1b8c2', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 2, 2, 'ከጥፋት ጕድጓድ ከረግረግም ጭቃ አወጣኝ እግሮቼንም በድንጋይ ላይ አቆማቸው አረማመዴንም አጸና'),
  ('ce0b28a0-d17c-5c0d-aaf7-f3e3de4dcdc2', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 3, 3, 'ዐዲስ ዝማሬን ለአምላካችን ምስጋና በአፌ ጨመረ ብዙዎች ያያሉ ይፈሩማል በእግዚአብሔርም ይታመናሉ'),
  ('3a6fa3e9-7676-530a-adc3-f15ea6b8422a', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 4, 4, 'እግዚአብሔርን የታመነ ወደ ትዕቢተኛና ወደ ሐሰተኛ ያልተመለከተ ሰው ምስጉን ነው'),
  ('b77c59fb-7345-5d8a-ad12-a77e1927d9ca', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 5, 5, 'አቤቱ አምላኬ ያደረግኸው ተኣምራት ብዙ ነው ዐሳብኽንም ምንም የሚመስለው የለም ባወራም ብናገርም ከቍጥር ዅሉ በዛ'),
  ('57f59d3e-d831-5907-a4a8-38ab51c0f4bf', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 6, 6, 'መሥዋዕትንና ቍርባንን አልወደድኽም ሥጋን አዘጋጀኽልኝ የሚቃጠለውንና ስለ ኀጢአት የሚቀርበውን መ ሥዋዕት አልሻኽም'),
  ('ba295027-9f79-5770-a265-e60729bd5b73', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 7, 7, 'በዚያን ጊዜ አልኹ፦እንሆ መጣኹ ስለ እኔ በመጽሐፍ ራስ ተጽፏል'),
  ('acbdc466-4bb9-585f-acfa-d38c6e0d7c88', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 8, 8, 'አምላኬ ሆይ ፈቃድኽን ለማድረግ ወደድኹ ሕግኽም በልቤ ውስጥ ነው'),
  ('945cecf1-f00e-5314-a425-1a2b90dbe7eb', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 9, 9, 'በታላቅ ጉባኤ ጽድቅን አወራኹ እንሆ ከንፈሮቼን አልከለክልም አቤቱ አንተ ጽድቄን ታውቃለኽ'),
  ('d52aa0b8-dfcd-5fbd-a519-40de608b45f3', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 10, 10, 'እውነትኽንም በልቤ ውስጥ አልሰወርኹም ማዳንኽንም ተናገርኹ ምሕረትኽንና እውነትኽን ከታላቅ ጉባ ኤ አልሰወርኹም'),
  ('fa6694e6-2e6b-577e-a849-8f9c149637bd', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 11, 11, 'አቤቱ አንተ ምሕረትኽን ከእኔ አታርቅ ቸርነትኽና እውነትኽ ዘወትር ይጠብቁኝ'),
  ('8b5a668b-0ac1-59c3-a37f-868ece4cc28f', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 12, 12, 'ቍጥር የሌላት ክፋት አግኝታኛለችና ኀጢአቶቼ ያዙኝ ማየትም ተስኖኛል ከራሴ ጠጕር ይልቅ በዙ ል ቤም ተወኝ'),
  ('f7badafc-6202-5773-a716-3a873f4f706f', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 13, 13, 'አቤቱ ታድነኝ ዘንድ ፍቀድ አቤቱ እኔን ለመርዳት ፍጠን'),
  ('56db1c57-5dd7-566f-a9d7-142906540d7f', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 14, 14, 'ነፍሴን ለማጥፋት የሚወዱ ይፈሩ በአንድነትም ይጐስቍሉ በእኔ ላይ ክፋትን ሊያደርጉ የሚወዱ ወደ ዃላቸው ይመለሱ ይጐስቍሉም'),
  ('15918b92-8369-5b34-a533-5fd6c663db3f', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 15, 15, 'ዕሠይ ዕሠይ የሚሉኝ ዕፍረታቸውን ወዲያው ይከፈሉ'),
  ('008057e9-ca3c-54d1-a1a7-d0d3c0bca09d', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 16, 16, 'አቤቱ የሚፈልጉኽ ዅሉ ባንተ ደስ ይበላቸው ሐሤትም ያድርጉ ዅልጊዜ ማዳንኽን የሚወዱ ዘወትር እ ግዚአብሔር ታላቅ ይኹን ይበሉ'),
  ('4179c3ad-bae1-5971-a15b-734157993a06', '967dbd4d-b262-57e8-a008-fe2c1782f2f3', 'd36fde14-1739-5e73-a4b5-58c992f040de', 17, 17, 'እኔ ችግረኛና ምስኪን ነኝ ጌታ ግን ያስብልኛል አንተ ረዳቴና መድኀኒቴ ነኽ አምላኬ ሆይ አትዘ ግይ'),
  ('5f2da866-d84b-51c3-a26c-09c5ba7560c1', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 1, 1, 'ለችግረኛና ለምስኪን የሚያስብ ምስጉን ነው እግዚአብሔር በክፉ ቀን ያድነዋል'),
  ('3ede08a2-7f3f-5262-a5cd-4fd2f51dd16e', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 2, 2, 'እግዚአብሔር ይጠብቀዋል ሕያውም ያደርገዋል በምድር ላይም ያስመሰግነዋል በጠላቶቹም እጅ አያሳልፈ ውም'),
  ('285a558d-449a-5fa3-a349-9487e713dee1', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 3, 3, 'እግዚአብሔር በደዌው ዐልጋ ሳለ ይረዳዋል መኝታውን ዅሉ በበሽታው ጊዜ ያነጥፍለታል'),
  ('c2b4d412-7593-5236-a317-3150d8212202', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 4, 4, 'እኔስ፦አቤቱ ማረኝ አንተን በድያለኹና ነፍሴን ፈውሳት አልኹ'),
  ('ac69a96b-9f00-586b-adce-094cddb83afc', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 5, 5, 'ጠላቶቼም በላዬ ክፋትን ይናገራሉ፦መቼም ይሞታል ስሙስ መቼ ይሻራል ይላሉ'),
  ('a7a4ba2d-f53a-524b-af00-7be96d556110', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 6, 6, 'እኔን ለማየት ቢገባ ከንቱን ይናገራል ልቡ ኀጢአትን ሰበሰበለት ወደ ሜዳ ይወጣል ይናገራልም'),
  ('b6300793-c23f-5cde-a7a9-7d6b99944333', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 7, 7, 'በላዬ በመተባበር ጠላቶቼ ዅሉ ይሾካሾኩብኛል በእኔ ላይም ክፋትን ያስባሉ'),
  ('b80a9915-071b-5b1f-add9-9fc0ed298ca1', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 8, 8, 'ክፉ ነገር መጣበት ተኝቷል ከእንግዲህ ወዲህ አይነሣም ይላሉ'),
  ('0c80b727-6335-5a53-a90e-74b723f5f370', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 9, 9, 'ደግሞ የሰላሜ ሰው የታመንኹበት እንጀራዬን የበላ በእኔ ላይ ተረከዙን አነሣ'),
  ('2f9403a7-0001-59c7-a278-17ca6b916471', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 10, 10, 'አንተ ግን አቤቱ ማረኝ እመልስላቸውም ዘንድ አስነሣኝ'),
  ('d228307d-b1d6-5b8d-a3f7-9b3e0818f17b', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 11, 11, 'ጠላቴ እልል አይልብኝምና ስለዚህ እንደ ወደድኸኝ ዐወቅኹ'),
  ('f78a6d75-a3c7-560a-aa0c-40acef52cb79', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 12, 12, 'እኔን ግን ስለ ቅንነቴ ተቀበልኸኝ በፊትኽም ለዘለዓለም አጸናኸኝ'),
  ('1c14da19-97b1-5f89-afb2-999af9a9c26a', '1b7bd83e-b142-59bd-abd8-abc25c181b99', '838fa968-a32f-564c-a4c2-bf5678ffb9d9', 13, 13, 'ከዘለዓለም እስከ ዘለዓለም የእስራኤል አምላክ እግዚአብሔር ይባረክ አሜን አሜን'),
  ('f1b3c495-aae1-512e-a577-b5166e7b76c9', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 1, 1, 'ዋላ ወደ ውሃ ምንጭ እንደሚናፍቅ አቤቱ እንዲሁ ነፍሴ ወዳንተ ትናፍቃለች'),
  ('f525e31d-e035-5faf-aa94-e8345770c655', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 2, 2, 'ነፍሴ ወደ ሕያው አምላክ ተጠማች መቼ እደርሳለኹ የአምላክንስ ፊት መቼ አያለኹ'),
  ('a0c711d9-f878-5bfd-a951-386a79a27913', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 3, 3, 'ዘወትር አምላክኽ ወዴት ነው ሲሉኝ እንባዬ በቀንና በሌሊት ምግብ ኾነኝ'),
  ('df9dba1e-f8e2-5c48-a6ab-35ba4bdbe345', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 4, 4, 'ይህን ሳስብ ነፍሴ በእኔ ውስጥ ፈሰሰች ወደእግዚአብሔር ቤት ወደምስጋና መኖሪያ ስፍራ እገባለኹና በዓል የሚያደርጉ ሰዎች የደስታና ምስጋና ቃል አሰሙ'),
  ('0c985a84-8407-51de-a449-a881be326721', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 5, 5, 'ነፍሴ ሆይ ለምን ታዝኛለሽ ለምንስ ታውኪኛለሽ የፊቴን መድኀኒት አምላኬን አመሰግነው ዘንድ በእግ ዚአብሔር ታመኚ'),
  ('5c32f7e8-0ca3-536f-ace4-3e6054d9795e', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 6, 6, 'አምላኬ ሆይ ነፍሴ በእኔ ውስጥ ታወከች ስለዚህ በዮርዳኖስ ምድር በአርሞንኤምም በታናሹ ተራራ ዐ ስብኻለኹ'),
  ('140e5160-9fb1-5021-acd8-7636ac664317', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 7, 7, 'በፏፏቴኽ ድምፅ ቀላይ ቀላይን ትጠራታለች ማዕበልኽና ሞገድኽ ዅሉ በላዬ ዐለፈ'),
  ('15d3b2a2-99be-5862-a15f-18de29730c7e', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 8, 8, 'እግዚአብሔር በቀን ቸርነቱን ያዛ፟ል በሌሊትም ዝማሬው በእኔ ዘንድ ይኾናል የእኔ ስእለት ለሕይወ ቴ አምላክ ነው'),
  ('f2ab3fb1-e1a5-5170-a243-be198162cc1a', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 9, 9, 'እግዚአብሔርን፦አንተ መጠጊያዬ ነኽ ለምን ረሳኸኝ ጠላቶቼ ሲያስጨንቁኝ ለምን ዐዝኜ እመላለሳለኹ እለዋለኹ'),
  ('fdf0e10b-218e-5191-a3c0-22a99e5b4420', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 10, 10, 'ጠላቶቼ ዅልጊዜ፦አምላክኽ ወዴት ነው ባሉኝ ጊዜ ዐጥንቶቼን እየቀለጣጠሙ ሰደቡኝ'),
  ('8d64a1d2-5096-5bf9-a0c4-7ba528dd081e', 'c18e0868-7ca9-56fa-a736-4be47af544d5', '3afc2bf6-ffc6-5f82-a4f8-e5318ccf43f4', 11, 11, 'ነፍሴ ሆይ ለምን ታዝኛለሽ ለምንስ ታውኪኛለሽ የፊቴን መድኀኒት አምላኬን አመሰግነው ዘንድ በእ ግዚአብሔር ታመኚ'),
  ('dd5e127d-38df-54a4-abe8-a060208c2445', '3af5b26d-3df0-52af-a00c-234f8be4ed87', '82ecd33f-ad9b-5290-aa3a-af5cbb59b5a2', 1, 1, 'አቤቱ ፍረድልኝ ከጽድቅ ከራቁ ሕዝብም ክርክሬን ተከራከር ከሸንጋይና ከግፈኛ ሰው አድነኝ'),
  ('34a82ce7-59a6-5b0f-a8b7-2b4049144fa3', '3af5b26d-3df0-52af-a00c-234f8be4ed87', '82ecd33f-ad9b-5290-aa3a-af5cbb59b5a2', 2, 2, 'አንተ አምላኬ ኀይሌም ለምን ትተወኛለኽ ጠላቶቼ ሲያስጨንቁኝ ለምን ዐዝኜ እመላለሳለኹ'),
  ('14e725e3-ab6c-5f44-a38a-6289d06a1f85', '3af5b26d-3df0-52af-a00c-234f8be4ed87', '82ecd33f-ad9b-5290-aa3a-af5cbb59b5a2', 3, 3, 'ብርሃንኽንና እውነትኽን ላክ እነርሱ ይምሩኝ ወደቅድስናኽ ተራራና ወደ ማደሪያኽ ይውሰዱኝ'),
  ('b84e1484-e65c-5151-a720-06411642284d', '3af5b26d-3df0-52af-a00c-234f8be4ed87', '82ecd33f-ad9b-5290-aa3a-af5cbb59b5a2', 4, 4, 'ወደእግዚአብሔር መሠዊያ ጕልማሳነቴንም ደስ ወዳሠኛት ወደ አምላኬ እገባለኹ አቤቱ አምላኬ በበገና አመሰግንኻለኹ'),
  ('e8d9b6a8-f9a8-5a2f-af84-b4cbfcd89006', '3af5b26d-3df0-52af-a00c-234f8be4ed87', '82ecd33f-ad9b-5290-aa3a-af5cbb59b5a2', 5, 5, 'ነፍሴ ሆይ ለምን ታዝኛለሽ ለምንስ ታውኪኛለሽ የፊቴን መድኀኒት አምላኬን አመሰግነው ዘንድ በእግ ዚአብሔር ታመኚ'),
  ('93010b0d-fb2e-5d77-a1e3-a023a0d8d7a6', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 1, 1, 'አቤቱ በዦሯችን ሰማን አባቶቻችንም በዘመናቸው በቀድሞ ዘመን የሠራኸውን ሥራ ነገሩን'),
  ('4f44400f-d826-561c-aec8-cd286344bf7a', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 2, 2, 'እጅኽ አሕዛብን አጠፋች እነርሱንም ተከልኽ አሕዛብን ሣቀይኻቸው አሳደድኻቸውም'),
  ('22e2c408-bb6b-51bc-a7a0-3b3513b61109', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 3, 3, 'በሰይፋቸው ምድርን አልወረሱም ክንዳቸውም አላዳናቸው ቀኝኽና ክንድኽ የፊትኽም ብርሃን ነው እንጂ ወደ፟ኻቸዋልና'),
  ('fd5af75e-f494-5b3c-ae79-20f868124158', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 4, 4, 'አምላኬና ንጉሤ አንተ ነኽ ለያዕቆብ መድኀኒትን እዘዝ'),
  ('40dfe699-55dd-5362-ad54-9f70d2d14141', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 5, 5, 'ባንተ ጠላቶቻችንን እንወጋቸዋለን በስምኽም በላያችን የቆሙትን እናዋርዳቸዋለን'),
  ('a2e773f6-1187-57b9-a457-664fa44a00e8', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 6, 6, 'በቀስቴ የምታመን አይደለኹምና ሰይፌም አያድነኝምና'),
  ('b16844c1-5f83-54af-a5e2-48b71f7ddaf6', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 7, 7, 'አንተ ግን ከጠላቶቻችን አዳንኸን የሚጠሉንንም አሳፈርኻቸው'),
  ('22954e2f-f08f-5972-a843-0f9838339781', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 8, 8, 'ዅልጊዜ በእግዚአብሔር እንከብራለን ስምኽንም ለዘለዓለም እናመሰግናለን'),
  ('2af409ed-cf48-577d-acbd-021a8f277c60', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 9, 9, 'አኹን ግን ጠላኸን አሳፈርኸንም ከሰራዊታችንም ጋራ አትወጣም'),
  ('1c2694bd-8293-5455-a01e-f79c7c3cbfb4', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 10, 10, 'ከጠላቶቻችንም ፊት ወደ ዃላችን መለስኸን የሚጠሉንም ተነጣጠቁን'),
  ('eb6c5f04-c748-5d1e-a96c-3b8068fa533d', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 11, 11, 'እንደ በጎች ሊበሉን ሰጠኸን ወደ አሕዛብም በተንኸን'),
  ('ed4402a2-d604-562e-abe0-904f218ecd86', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 12, 12, 'ሕዝብኽን ያለዋጋ ሰጠኽ በመለወጣቸውም ትርፍ የለም'),
  ('012bfd8e-3705-5875-aca7-bbac562b9e12', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 13, 13, 'ለጎረቤቶቻችን ስድብ በዙሪያችንም ላሉ መሣቂያና መዘበቻ አደረግኸን'),
  ('d880574c-4e65-55dc-aac5-aefbecd105a1', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 14, 14, 'በአሕዛብ ዘንድ ምሳሌ በሕዝብም ዘንድ የራስ መንቀሳቀሻ አደረግኸን'),
  ('ba963614-5830-5c86-a466-8e41ca2c232e', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 15, 15, 'ጕስቍልናዬ ዅልጊዜም በፊቴ ነው የፊቴም ዕፍረት ሸፈነኝ'),
  ('883c03a0-8263-52af-a1d8-88f140e707fa', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 16, 16, 'ከሚሳደብና ከሚላገድ ቃል የተነሣ ከጠላትና ከቂመኛ ፊት የተነሣ ነው'),
  ('449700e3-b311-5f49-ace4-8c0027638ac6', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 17, 17, 'ይህ ዅሉ በእኛ ላይ ደረሰ አልረሳንኽም ኪዳንኽንም አልወነጀልንም'),
  ('7b92023f-fbb9-5320-a49a-1c02f150d4cd', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 18, 18, 'ልባችን ወደ ዃላው አልተመለሰም ፍለጋችንም ከመንገድኽ ፈቀቅ አላለም'),
  ('65fbb3a3-73c3-5f53-ab34-41f6b2aa697b', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 19, 19, 'በክፉ ስፍራ አዋርደኸናልና በሞት ጥላም ሰውረኸናልና'),
  ('b6a04bf5-404f-5e91-ad9d-4ac270928cf2', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 20, 20, 'የአምላካችንን ስም ረስተንስ ቢኾን እጃችንንም ወደ ሌላ አምላክ አንሥተንስ ቢኾን'),
  ('242d63ad-ae14-5c92-abc9-a44b3c63c51d', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 21, 21, 'እግዚአብሔር ይህንን አይመረምርም ነበርን ርሱ ልብ የሰወረውን ያውቃልና'),
  ('a6559dee-d2f6-5f36-a7b2-268d9cb5f5a6', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 22, 22, 'ስለ አንተ ዅልጊዜም ተገድለናል እንደሚታረዱም በጎች ኾነናል'),
  ('57f4da77-4a75-59cf-a5ef-de067a109429', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 23, 23, 'አቤቱ ንቃ ለምንስ ትተኛለኽ ተነሥ ለዘወትርም አትጣለን'),
  ('90f6674c-3390-5dce-a79c-ff76a1fb0516', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 24, 24, 'ለምንስ ፊትኽን ትሰውራለኽ መከራችንንና ችግራችንንስ ለምን ትረሳለኽ'),
  ('4d3552af-cfb2-544d-a22a-140eac92bbad', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 25, 25, 'ነፍሳችን በመሬት ላይ ተጐሳቍላለችና ሆዳችንም ወደ ምድር ተጣብቃለችና'),
  ('a1d719fd-d058-5ab8-a477-4d7497c6328d', '2c3aba3b-e6d4-5d65-aa7a-e2638c7e833c', '7fcb6eea-689f-57b0-ae5b-2b49ff9ff97a', 26, 26, 'አቤቱ ተነሥና ርዳን ስለ ስምኽም ተቤዠን'),
  ('59c9315b-90f4-5ff6-a77b-beaa8e6900e0', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 1, 1, 'ልቤ መልካም ነገርን አፈለቀ እኔ ሥራዬን ለንጉሥ እነግራለኹ አንደበቴ እንደ ፈጣን ጸሓፊ ብርዕ ነው'),
  ('2942df5e-5872-5272-aa7f-6353f9dc1df9', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 2, 2, 'ውበትኽ ከሰው ልጆች ይልቅ ያምራል ሞገስ በከንፈሮችኽ ፈሰሰ ስለዚህ እግዚአብሔር ለዘለዓለም ባረ ከኽ'),
  ('f789346b-407c-52dc-a79e-b598b317bf9b', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 3, 3, 'ኀያል ሆይ በቍንዥናኽና በውበትኽ ሰይፍኽን በወገብኽ ታጠቅ'),
  ('823908f5-2b95-5c17-ad24-0c3dfd40bd17', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 4, 4, 'ስለ ቅንነትና ስለ የዋህነት ስለ ጽድቅም አቅና ተከናወን ንገሥም ቀኝኽም በክብር ይመራኻል'),
  ('59020f38-0ebd-5b53-aa54-ec1742bdd393', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 5, 5, 'ኀያል ሆይ ፍላጻዎችኽ የተሳሉ ናቸው እነርሱም በንጉሥ ጠላቶች ልብ ውስጥ ይገባሉ አሕዛብም በበታ ችኽ ይወድቃሉ'),
  ('f335e073-88c3-50e5-a8e2-62dede1440bd', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 6, 6, 'አምላክ ሆይ ዙፋንኽ ለዘለዓለም ነው የመንግሥትኽ በትር የቅንነት በትር ነው'),
  ('87ad634d-205e-5068-a794-a2f43e76ce03', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 7, 7, 'ጽድቅን ወደድኽ ዐመፃንም ጠላኽ ስለዚህ ከባልንጀራዎችኽ ይልቅ እግዚአብሔር አምላክ የደስታ ዘይት ን ቀባኽ'),
  ('f5147286-3efb-5de8-abd1-fceb06bb514a', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 8, 8, 'በልብሶችኽ ዅሉ ከርቤና ሽቱ ዝባድም አሉ ከዝኆን ጥርሶች አዳራሽ ደስ ያሠኙኻል'),
  ('ddb00754-0086-5105-a669-83f52bc9b850', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 9, 9, 'የንጉሦች ሴት ልጆች ለክብርኽ ናቸው በወርቅ ልብስ ተጐናጽፋና ተሸፋፍና ንግሥቲቱ በቀኝኽ ትቆማለ ች'),
  ('a0f4caf9-bc45-5917-ab95-5066d3830f65', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 10, 10, 'ልጄ ሆይ ስሚ እዪ ዦሮሽንም አዘንብዪ ወገንሽን ያባትሽንም ቤት ርሺ'),
  ('44809817-e139-5027-a327-3d22ade8063e', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 11, 11, 'ንጉሥ ውበትሽን ወዷ፟ልና ርሱ ጌታሽ ነውና'),
  ('014c2150-ec74-586e-a2b0-d52565f0e104', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 12, 12, 'የጢሮስ ሴቶች ልጆች እጅ መንሻን ይዘው ይሰግዱለታል የምድር ባለጠጋዎች አሕዛብ በፊትኽ ይማለላ ሉ'),
  ('8865410c-7b9a-5d25-afda-b71f78ce29fb', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 13, 13, 'ለሐሴቦን ንጉሥ ልጅ ዅሉ ክብሯ ነው ልብሷ የወርቅ መጐናጸፊያ ነው'),
  ('885ab785-9937-5a95-a9d7-cb9068e56368', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 14, 14, 'በዃላዋ ደናግሉን ለንጉሥ ይወስዳሉ ባልንጀራዎቿንም ወዳንተ ያቀርባሉ'),
  ('7c9d42d5-4963-5b02-adc2-f4f03bcfba7e', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 15, 15, 'በደስታና በሐሴት ይወስዷቸዋል ወደንጉሥ ዕልፍኝም ያስገቧቸዋል'),
  ('916beacc-d1d0-5054-a184-784fff18459c', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 16, 16, 'በአባቶችሽ ፋንታ ልጆች ተወለዱልሽ በምድርም ዅሉ ላይ ገዢዎች አድርገሽ ትሾሚያቸዋለሽ'),
  ('c3aad21b-858d-59e5-a0fe-50dd35f642df', 'bbdbc3c9-86f3-5757-a184-dfbad6e00190', 'f5967777-8c2f-5809-afd3-62832ab275fe', 17, 17, 'ለልጅ ልጅ ዅሉ ስምሽን ያሳስባሉ ስለዚህ ለዓለምና ለዘለዓለም አሕዛብ ይገዙልኻል'),
  ('6d1c88fc-b963-508a-a7ba-af8033b5f5b3', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 1, 1, 'አምላካችን መጠጊያችንና ኀይላችን ባገኘን በታላቅ መከራም ረዳታችን ነው'),
  ('b4c5dfb8-22c3-5da1-a43d-eddb89384f62', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 2, 2, 'ስለዚህ ምድር ብትነዋወጥ ተራራዎችም ወደባሕር ልብ ቢወሰዱ አንፈራም'),
  ('e283f03e-12ea-5ef0-a3a2-d62f35288531', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 3, 3, 'ውሃዎቻቸው ጮኹ ተናወጡም ተራራዎችም ከኀይሉ የተነሣ ተናወጡ'),
  ('df8640ed-caca-55de-ad89-d331c87d5a1d', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 4, 4, 'የወንዝ ፈሳሾች የእግዚአብሔርን ከተማ ደስ ያሠኛሉ ልዑል ማደሪያውን ቀደሰ'),
  ('ffae6964-736f-5ef0-aa01-1770d5f63d10', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 5, 5, 'እግዚአብሔር በመካከሏ ነው አትናወጥም እግዚአብሔርም ፈጥኖ ይረዳታል'),
  ('ba9c4ea4-7308-59ac-a28a-3baade2fcb0a', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 6, 6, 'አሕዛብ ተናወጡ መንግሥታትም ተመለሱ ርሱ ቃሉን ሰጠ ምድርም ተንቀጠቀጠች'),
  ('a6398f84-1f32-50ce-a80b-06fdff1fba3b', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 7, 7, 'የሰራዊት ጌታ ከእኛ ጋራ ነው የያዕቆብ አምላክ መጠጊያችን ነው'),
  ('16a0c464-dc96-5adc-af3c-93c32600246a', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 8, 8, 'የእግዚአብሔርን ሥራ በምድር ያደረገውንም ተኣምራት እንድታዩ ኑ'),
  ('71ab2e30-d2c2-5d2f-a5cc-eb284ae3e138', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 9, 9, 'እስከምድር ዳርቻ ድረስ ጦርነት ይሽራል ቀስትን ይሰብራል ጦርንም ይቈርጣል በእሳትም ጋሻን ያቃጥ ላል'),
  ('d5c4ff31-85e2-5011-a6f6-6ee934eba063', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 10, 10, 'ዕረፉ እኔም አምላክ እንደ ኾንኹ ዕወቁ በአሕዛብ ዘንድ ከፍ ከፍ እላለኹ በምድርም ላይ ከፍ ከ ፍ እላለኹ'),
  ('2392e9b2-45da-5d35-a96d-a99a31efce76', '25f5a1b3-e99d-5433-a1ff-920453d53c75', '29f6c8a7-359d-5e6b-abbe-cec6978ef910', 11, 11, 'የሰራዊት ጌታ ከእኛ ጋራ ነው የያዕቆብ አምላክ መጠጊያችን ነው'),
  ('c9d97fbb-89c4-5890-a511-f0f8c881be4b', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 1, 1, 'አሕዛብ ዅላችኹ እጆቻችኹን አጨብጭቡ በደስታ ቃልም ለእግዚአብሔር እልል በሉ'),
  ('7ddce47e-6f23-5594-a1f8-ed1a4e0989cf', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 2, 2, 'እግዚአብሔር ልዑል ግሩምም ነውና በምድር ዅሉ ላይም ታላቅ ንጉሥ ነውና'),
  ('0a99c7b1-3d38-551d-a168-7f6d72d8a67a', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 3, 3, 'አሕዛብን ከእኛ በታች ወገኖችንም ከእግራችን በታች አስገዛልን'),
  ('ba551ff2-c44b-530c-a75b-a6879f9218ed', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 4, 4, 'ለርስቱ እኛን መረጠን የወደደውን የያዕቆብን ውበት'),
  ('d3d1d063-6d2a-55aa-ab6b-8da7ff6aa765', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 5, 5, 'አምላክ በእልልታ እግዚአብሔር በመለከት ድምፅ ዐረገ'),
  ('6111ab69-e7ac-5d7a-ad7d-99fba1f541f7', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 6, 6, 'ዘምሩ ለአምላካችን ዘምሩ ዘምሩ ለንጉሣችን ዘምሩ'),
  ('0d3b772c-32ea-5241-a773-55d970fde3b7', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 7, 7, 'እግዚአብሔር ለምድር ዅሉ ንጉሥ ነውና በማስተዋል ዘምሩ'),
  ('5ea2438f-db67-515a-a512-3321108637f0', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 8, 8, 'እግዚአብሔር በአሕዛብ ላይ ነገሠ እግዚአብሔር በቅድስናው ዙፋን ይቀመጣል'),
  ('1fe6732c-11b8-50c5-a64f-5423b7520f7c', '486cf523-3a38-5c50-ad69-6e635818599a', 'e3cc7fb8-3cd5-594a-aaef-d5d31464e624', 9, 9, 'የምድር ኀይለኛዎች ለእግዚአብሔር ናቸውና የአሕዛብ አለቃዎች ወደአብርሃም አምላክ ተሰበሰቡ ርሱን ም ከፍ ከፍ አደረጉት'),
  ('9e9db53e-e3e1-5091-a4a3-701e340d67d4', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 1, 1, 'እግዚአብሔር ትልቅ ነው በአምላካችን ከተማ በተቀደሰ ተራራ ምስጋናው ብዙ ነው'),
  ('cfa8eb48-6854-5b36-a880-ff611215317c', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 2, 2, 'በሰሜን ወገን በመልካም ስፍራ የቆመ የምድር ዅሉ ደስታ የጽዮን ተራራ ነው ርሱም የትልቁ ንጉሥ ከተማ ነው'),
  ('3800aef8-ba7a-5365-acb2-5a9abf039eed', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 3, 3, 'እግዚአብሔር በአዳራሾቿ መጠጊያ ኾኖ ይታወቃል'),
  ('4cf66334-5cf7-5689-aff0-67c16f579f9c', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 4, 4, 'እንሆ ነገሥታት ተከማችተው በአንድነት መጥተዋል'),
  ('be3446f2-b597-581c-afed-4b6ccefdaa46', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 5, 5, 'እነርሱስ አይተው ተደነቁ ደነገጡ ታወኩ'),
  ('3adaab9c-7b48-5971-a57f-ea450d84358e', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 6, 6, 'መንቀጥቀጥ እንደ ወላድ ምጥ በዚያ ያዛቸው'),
  ('0a4f1df7-c5af-585a-a14f-fffebdc3e2a3', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 7, 7, 'በኀይለኛ ነፋስ የተርሴስን መርከቦች ትሰብራለኽ'),
  ('137d3cc8-4313-5ed2-aa21-11d190781ed0', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 8, 8, 'እንደ ሰማን እንዲሁ አየን በሰራዊት ጌታ ከተማ በአምላካችን ከተማ እግዚአብሔር ለዘለዓለም ያጸና ታል'),
  ('36722a33-a0e4-5962-a1cb-d3dd5e56d26d', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 9, 9, 'አምላክ ሆይ በሕዝብኽ መካከል ምሕረትኽን ተቀበልን'),
  ('3aea4a00-cdca-53a1-a8e1-1d0551a678be', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 10, 10, 'አምላክ ሆይ እንደ ስምኽ እንዲሁም እስከምድር ዳርቻ ድረስ ምስጋናኽ ነው ቀኝኽ ጽድቅን የተሞላ ች ናት'),
  ('c06a46ed-67e2-5720-a996-ebdf4ae3cfde', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 11, 11, 'አቤቱ ስለ ፍርድኽ የጽዮን ተራራ ደስ ይበለው የአይሁድም ሴት ልጆች ሐሤት ያድርጉ'),
  ('6b6cdc6d-90c7-5864-a4aa-6e22ed39a51b', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 12, 12, 'ጽዮንን ክበቧት በዙሪያዋም ተመላለሱ ግንቦቿንም ቍጠሩ'),
  ('80933c9d-8517-546e-ab62-649db49aeec3', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 13, 13, 'በብርታቷ ልባችኹን አኑሩ አዳራሿን ዐስቡ ለሚመጣው ትውልድ ትነግሩ ዘንድ'),
  ('f6c5dedb-49c5-546d-a850-6269e49f0937', '0dfc424b-0d31-5d8c-a300-593a8e4a0c14', '9b0fb1fc-f625-50f7-abfc-32259190db9e', 14, 14, 'ለዓለምና ለዘለዓለም ይህ አምላካችን ነው ርሱም ለዘለዓለም ይመራናል'),
  ('b4fcf003-c361-5247-ab46-22f1baba90c4', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 1, 1, 'አሕዛብ ዅላችኹ ይህን ስሙ በዓለም የምትኖሩትም ዅላችኹ አድምጡ'),
  ('64ae049d-a88a-52f6-a997-b5e6cce2d51d', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 2, 2, 'ዝቅተኛዎችና ከፍተኛዎች ባለጠጋዎችና ድኻዎች በአንድነት'),
  ('faf85419-21ef-5a3b-a9a2-1929f526a12c', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 3, 3, 'አፌ ጥበብን ይናገራል የልቤም ዐሳብ ማስተዋልን'),
  ('a2af5e45-ac30-541c-a05f-dd76c8fd4f94', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 4, 4, 'ዦሮዬን ወደ ምሳሌ አዘነብላለኹ በበገናም ምስጢሬን እገልጣለኹ'),
  ('69900a8a-2ed3-5176-a286-8bea62c45bf6', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 5, 5, 'ኀጢአት ተረከዜን በከበበኝ ጊዜ በክፉ ቀን ለምን እፈራለኹ'),
  ('d3f7a518-083a-5033-a16f-c0e8cd6101b4', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 6, 6, 'በኀይላቸው የሚታመኑ በባለጠግነታቸውም ብዛት የሚመኩ'),
  ('7608666b-0537-5f12-aa18-7f6205b20459', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 7, 7, 'ወንድም ወንድሙን አያድንም ሰውም አያድንም ቤዛውን ለእግዚአብሔር አይሰጥም 8-9 ለዘለዓለም እንዲኖር ጥፋትንም እንዳያይ የነፍሳቸው ለውጥ ከብሯልና ለዘለዓለምም ቀርቷልና'),
  ('8aad9b0a-24ab-58d1-a7a8-fb1dc0dde1a6', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 8, 10, 'ብልኀተኛዎች እንዲሞቱ ሰነፎችና ደንቈሮዎች በአንድነት እንዲጠፉ ገንዘባቸውንም ለሌላዎች እንዲተ ዉ አይቷል'),
  ('b6920ed3-0d65-5408-a7e3-076b2f3b92a1', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 9, 11, 'በልባቸውም ቤታቸው ለዘለዓለም የሚኖር ማደሪያቸውም ለልጆች ልጅ የሚኾን ይመስላቸዋል በያገራቸው ም ስማቸው ይጠራል'),
  ('d58928e7-3a3e-57d8-a686-16318372398b', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 10, 12, 'ሰው ግን ክቡር ኾኖ ሳለ አያውቅም እንደሚጠፉ እንስሳዎች መሰለ'),
  ('c399db9d-e72d-55ca-aafe-4908cd7bea87', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 11, 13, 'ይህች መንገዳቸው መሰናክላቸው ናት ከነርሱም በዃላ የሚመጡ በአፋቸው ዕሺ ይላሉ'),
  ('c2077b31-1387-55b9-aa33-45ba61bafb48', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 12, 14, 'እንደ በጎች ወደ ሲኦል የሚኼዱ ናቸው እረኛቸውም ሞት ነው ቅኖችንም በማለዳ ይገዟቸዋል ውበታቸ ውም ከመኖሪያቸው ተለይታ በሲኦል ታረጃለች'),
  ('d7181a6a-0aab-54ab-a10c-9a2cbc57d52d', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 13, 15, 'ነገር ግን እግዚአብሔር ይቀበለኛልና ነፍሴን ከሲኦል እጅ ይቤዣታል'),
  ('dc2a8025-3d56-580a-af94-825e62851153', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 14, 16, 'የሰው ባለጠግነት የቤቱም ክብር በበዛ ጊዜ አትፍራ'),
  ('19037fea-614a-52bf-a5e7-69b6b23985c9', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 15, 17, 'በሞተ ጊዜ ከርሱ ጋራ ምንም አይወስድምና ክብሩም ከርሱ በዃላ አይወርድምና'),
  ('d98d65bd-d6c3-5042-a9c0-a86c34ed9852', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 16, 18, 'በሕይወቱ ሳለ ነፍሱን ባርኳልና ለሰውነቱ መልካም ብታደርግለት ያመሰግንኻል'),
  ('4d06e5bc-adf9-55dd-a6aa-9826809b03b5', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 17, 19, 'ኾኖም ወዳባቶቹ ትውልድ ይወርዳል ለዘለዓለም ብርሃንን አያይም'),
  ('40be9783-2b95-5853-ada0-38ef36e53468', 'aec5dd6b-2cdc-57ce-af46-2c55ecf24b6b', '07532d42-0eba-58d5-af68-a2152243bfb8', 18, 20, 'አእምሮ የሌለው ክቡር ሰው እንደሚጠፋ እንስሳዎች መሰለ'),
  ('e84f17d6-678e-5382-aa37-c7ad0770e5b9', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 1, 1, 'የአማልክት አምላክ እግዚአብሔር ተናገረ ከፀሓይም መውጫ ዠምሮ እስከ መግቢያዋ ድረስ ምድርን ጠራ ት'),
  ('2cd3b474-415d-5312-a5af-e473fb743f95', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 2, 2, 'ከክብሩ ውበት ከጽዮን እግዚአብሔር ግልጥ ኾኖ ይመጣል'),
  ('627cb0ab-02f6-58f0-a80f-1b4def6a9a0b', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 3, 3, 'አምላካችን ይመጣል ዝምም አይልም እሳት በፊት ይቃጠላል በዙሪያውም ብዙ ዐውሎ አለ'),
  ('e97a296a-29eb-507a-a47d-d70eb25022fa', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 4, 4, 'በላይ ያለውን ሰማይን ምድርንም በሕዝቡ ለመፍረድ ይጠራል'),
  ('cdba1735-86de-51c3-ade0-9331c666247e', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 5, 5, 'ከርሱ ጋራ ለመሥዋዕት ኪዳን የቆሙትን ቅዱሳኑን ሰብስቡለት'),
  ('f66176a9-9f70-5594-ad5c-e92a326bc2e1', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 6, 6, 'ሰማያት ጽድቁን ይናገራሉ እግዚአብሔር ፈራጅ ነውና'),
  ('ed3bfd07-3a16-59f4-a05c-1262de769f6c', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 7, 7, 'ሕዝቤ ስማኝ ልንገርኽ እስራኤልም ስማኝ ልመስክርብኽ አምላክስ እኔ አምላክኽ ነኝ'),
  ('c124293a-0b8f-56c1-aced-a2d4569307b4', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 8, 8, 'ስለ ቍርባንኽ የምዘልፍኽ አይደለኹም የሚቃጠል መሥዋዕትኽ ዅልጊዜ በፊቴ ነው'),
  ('42c0e8cf-40d6-5f77-a97e-80085fb08efe', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 9, 9, 'ከቤትኽ ፍሪዳን ከመንጋኽም አውራ ፍየልን አልወስድም'),
  ('aca1041d-44e6-5982-ab5e-4ef0a779f393', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 10, 10, 'የምድረ በዳ አራዊት ዅሉ በሺሕ ተራራዎች ያሉ እንስሳዎችም የእኔ ናቸውና'),
  ('420f1105-02df-512b-a520-6632ba0a8010', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 11, 11, 'የሰማይን አዕዋፍ ዅሉ ዐውቃለኹ የምድረ በዳ አራዊትም በእኔ ዘንድ ናቸው'),
  ('19ca7003-7979-53a0-a2bf-d9610e0302bb', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 12, 12, 'ብራብም ለአንተ አልነግርኽም ዓለምና ሞላው የእኔ ነውና'),
  ('5c9a3f4b-2063-5b67-adf0-eea81e42126f', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 13, 13, 'የፍሪዳውን ሥጋ እበላለኹን የፍየሉንስ ደም እጠጣለኹን'),
  ('c6d66a49-59d7-549b-a524-f64ab9d5b775', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 14, 14, 'ለእግዚአብሔር የምስጋናን መሥዋዕት ሠዋ ለልዑልም ስእለትኽን ስጥ'),
  ('b5939b80-1246-533c-a6af-51fa997638f7', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 15, 15, 'በመከራ ቀን ጥራኝ አድንኽማለኹ አንተም ታከብረኛለኽ'),
  ('8b359f38-1c64-5835-a4d5-963d9360ab1d', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 16, 16, 'ኀጢአተኛውን ግን እግዚአብሔር አለው፦ለምን አንተ ሕጌን ትናገራለኽ ኪዳኔንም በአፍኽ ለምን ትወ ስዳለኽ'),
  ('aa958779-c9d7-5928-a6d5-dd7e51f93fa6', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 17, 17, 'አንተስ ተግሣጼን ጠላኽ ቃሎቼንም ወደ ዃላኽ ጣልኽ'),
  ('f17a8f6a-9a8f-5209-a9f7-59d961c67161', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 18, 18, 'ሌባውን ባየኽ ጊዜ ከርሱ ጋራ ትሮጥ ነበር ዕድል ፈንታኽንም ከአመንዝራዎች ጋራ አደረግኽ'),
  ('3c4e785f-ec54-5f66-a3a6-21e4402df9e0', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 19, 19, 'አፍኽ ክፋትን አበዛ አንደበትኽም ሽንገላን ተበተበ'),
  ('2afaee67-9bf6-5a0d-a379-25e83b18f379', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 20, 20, 'ተቀምጠኽ ወንድምኽን ዐማኸው ለእናትኽም ልጅ ዕንቅፋት አኖርኽ'),
  ('c70285ce-3ffc-54bf-a25d-a86764a3692d', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 21, 21, 'ይህን አድርገኽ ዝም አልኹኽ እኔ እንደ አንተ እኾን ዘንድ ጠረጠርኽ እዘልፍኻለኹ በፊትኽም እቆ ማለኹ'),
  ('48406f24-c31e-513c-a3b1-eb766a7ff564', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 22, 22, 'እግዚአብሔርን የምትረሱ እናንተ ይህን አስተውሉ አለዚያ ግን ይነጥቃል የሚያድንም የለም'),
  ('d11d80ca-6b53-5580-ac3c-10808a89838b', '060a43c9-5b59-5e90-a12d-6af50767415c', 'af3dea27-7205-56ec-a579-7d8d719b0127', 23, 23, 'ምስጋና የሚሠዋ ያከብረኛል የእግዚአብሔርን ማዳን ለርሱ የማሳይበት መንገድ ከዚያ አለ'),
  ('0558b33d-d2d4-59fc-a46b-d5eea137ea7b', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 1, 1, 'አቤቱ እንደ ቸርነትኽ መጠን ማረኝ እንደ ምሕረትኽም ብዛት መተላለፌን ደምስስ'),
  ('9f48d746-d885-5685-aeb6-2dfb9f2f31c3', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 2, 2, 'ከበደሌ ፈጽሞ ዕጠበኝ ከኀጢአቴም አንጻኝ'),
  ('b6d896dd-8d14-5e51-af47-08bdceb9d465', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 3, 3, 'እኔ መተላለፌን ዐውቃለኹና ኀጢአቴም ዅልጊዜ በፊቴ ነውና'),
  ('d20acfd7-e8dc-5440-aac1-14887e556796', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 4, 4, 'አንተን ብቻ በደልኹ በፊትኽም ክፋትን አደረግኹ በነገርኽም ትጸድቅ ዘንድ በፍርድኽም ንጹሕ ትኾን ዘንድ'),
  ('d10795a2-4ecb-5bb0-a434-c0704395792d', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 5, 5, 'እንሆ በዐመፃ ተፀነስኹ እናቴም በኀጢአት ወለደችኝ'),
  ('e71aa2a3-fbcf-577d-a188-908ee48022d5', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 6, 6, 'እንሆ እውነትን ወደድኽ የማይታይ ስውር ጥበብን አስታወቅኸኝ'),
  ('55e2827b-7366-51bd-af91-4c513a4a6345', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 7, 7, 'በሂሶጵ ርጨኝ እነጻማለኹ ዕጠበኝ ከበረዶም ይልቅ ነጭ እኾናለኹ'),
  ('c9c2b30f-b602-5687-a8b9-f2dde088208f', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 8, 8, 'ሐሤትንና ደስታን አሰማኝ የሰበርኻቸውም ዐጥንቶቼ ደስ ይላቸዋል'),
  ('61dc424a-b03b-5576-a40f-4162019ce4ec', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 9, 9, 'ከኀጢአቴ ፊትኽን መልስ በደሌንም ዅሉ ደምስስልኝ'),
  ('652b4314-b1b9-55d1-a0d5-c2ac64fd7a6f', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 10, 10, 'አቤቱ ንጹሕ ልብን ፍጠርልኝ የቀናውንም መንፈስ በውስጤ ዐድስ'),
  ('b4341a69-4011-5f70-a4e7-608f59164738', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 11, 11, 'ከፊትኽ አትጣለኝ ቅዱስ መንፈስኽንም ከእኔ ላይ አትውሰድብኝ'),
  ('2aa71605-6ae4-5d31-a2d2-faac048f7e46', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 12, 12, 'የማዳንኽን ደስታ ስጠኝ በእሽታ መንፈስም ደግፈኝ'),
  ('9da19a2a-a21d-511c-a86b-cc9c29d81ccd', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 13, 13, 'ለሕግ ተላላፊዎች መንገድኽን አስተምራለኹ ኀጢአተኛዎችም ወዳንተ ይመለሳሉ'),
  ('abc0047e-4500-5377-a82a-0f9fb0826a07', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 14, 14, 'የመድኀኒቴ አምላክ እግዚአብሔር ሆይ ከደም አድነኝ አንደበቴም ባንተ ጽድቅ ትደሰታለች'),
  ('092f1a24-6028-5ccc-a66e-a55c4cab2828', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 15, 15, 'አቤቱ ከንፈሮቼን ክፈት አፌም ምስጋናኽን ያወራል'),
  ('92df1029-0f6c-5591-aa8d-a76346bf73e0', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 16, 16, 'መሥዋዕትን ብትወድ፟ስ በሰጠኹኽ ነበር የሚቃጠለውም መሥዋዕት ደስ አያሠኝኽም'),
  ('2b8b6a37-3225-5687-af59-b9b41e2f28b9', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 17, 17, 'የእግዚአብሔር መሥዋዕት የተሰበረ መንፈስ ነው የተሰበረውንና የተዋረደውን ልብ እግዚአብሔር አይ ንቅም'),
  ('12c5529f-ccd6-5458-a371-aedf44edf582', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 18, 18, 'አቤቱ በውዴታኽ ጽዮንን አሰማምራት የኢየሩሳሌምንም ቅጽሮች ሥራ'),
  ('b8d7770e-d3fc-52a9-a62f-d2711b1302cb', '27254fce-5160-58f5-a821-e7655f05ef84', '7a56a4d0-fd13-5d43-ad6f-d1742791480d', 19, 19, 'የጽድቁን መሥዋዕት መባውንም የሚቃጠለውንም መሥዋዕት በወደድኽ ጊዜ ያን ጊዜ በመሠዊያኽ ላይ ፍ ሪዳዎችን ይሠዋሉ'),
  ('2256bc35-f641-5dfd-a5a9-2fceb843bca5', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 1, 1, 'ኀያል ሆይ በክፋት ለምን ትጓደዳለኽ ዅልጊዜስ በመተላለፍ'),
  ('50a86ddb-d359-5491-a6ff-655088ab9855', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 2, 2, 'አንደበትኽ ኀጢአትን ያስባል እንደ ተሳለ ምላጭ ሽንገላን አደረግኽ'),
  ('d63d2e7c-ed17-5a86-a775-b2dbe87ca32b', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 3, 3, 'ከመልካም ይልቅ ክፋትን ጽድቅንም ከመናገር ይልቅ ዐመፃን ወደድኽ'),
  ('a4402f65-7b2c-50a8-a3f5-8b47588f0a64', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 4, 4, 'የሚያጠፉ ቃልን ዅሉ የሽንገላ ምላስን ወደድኽ'),
  ('5087c40b-74c2-54ff-ac13-69dd080957a5', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 5, 5, 'ስለዚህ እግዚአብሔር ለዘለዓለም ያፈርስኻል ከቤትኽም ይነቅልኻል ያፈልስኻልም ሥርኽንም ከሕያዋን ምድር'),
  ('a73085ac-9a69-573f-a9fa-a900028b904d', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 6, 6, 'ጻድቃን አይተው ይፈራሉ በርሱም ይሥቃሉ እንዲህም ይላሉ፦'),
  ('7b3d4a52-aede-5d9b-a04b-15f17db5e1f6', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 7, 7, 'እግዚአብሔርን ረዳቱ ያላደረገ በባለጠግነቱም ብዛት የታመነ በከንቱ ነገርም የበረታ ያ ሰው እንሆ'),
  ('d055590a-5bcb-59ab-a0b5-01a9211e455d', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 8, 8, 'እኔስ በእግዚአብሔር ቤት እንደ ለመለመ እንደ ወይራ ዛፍ ነኝ ለዓለምና ለዘለዓለም በእግዚአብሔር ምሕረት ታመንኹ'),
  ('90f5a5cc-51c2-5990-aeb2-901b25f0dbf6', 'f7c48c0e-ee6e-5ab6-a76e-a0a623156c70', '34720d82-ae80-5f9b-a7ad-d9e2bb9a3949', 9, 9, 'አድርገኽልኛልና ለዘለዓለም አመሰግንኻለኹ በቅዱሳንኽም ዘንድ መልካም ነውና ስምኽን ተስፋ አደርጋ ለኹ'),
  ('0038b52e-d3ed-5826-a449-095ee0af9f4b', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 1, 1, 'ሰነፍ በልቡ፦አምላክ የለም ይላል ረከሱ በበደላቸውም ጐሰቈሉ በጎ ነገርን የሚያደርጋት የለም'),
  ('0d1abc42-84a7-5927-a273-0812ff51e1d1', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 2, 2, 'የሚያስተውል እግዚአብሔርንም የሚፈልግ እንዳለ ያይ ዘንድ እግዚአብሔር ከሰማይ የሰው ልጆችን ተመ ለከተ'),
  ('05655ed3-3112-50fd-af96-e962fe027564', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 3, 3, 'ዅሉ በደሉ ዐብረውም ረከሱ አንድ ስንኳ በጎን ነገር የሚያደርጋት የለም'),
  ('db061e1e-9911-5c70-a1b4-273fc55c2f66', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 4, 4, 'ሕዝቤን እንጀራ እንደሚበላ የሚበሉ ግፍ አድራጊዎች ዅሉ አያውቁምን እግዚአብሔርንም አይጠሩትም'),
  ('a7b4f286-cfd3-5cea-a905-c8e65133c14d', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 5, 5, 'እግዚአብሔር የግብዞችን ዐጥንቶች በትኗልና በዚያ የሚያስፈራ ሳይኖር እጅግ ፈሩ እግዚአብሔር ንቋ ቸዋልና አሳፈርኻቸው'),
  ('36a52640-2978-5ea9-ad91-281df9f57a60', 'fc7876a6-7d9d-5c25-ac5c-93a47d88bdd8', 'e911b0d3-c7da-54a8-a47e-cb4e03b6b4c2', 6, 6, 'መድኀኒትን ከጽዮን ለእስራኤል ማን በሰጠ! እግዚአብሔር የሕዝቡን ምርኮ በመለሰ ጊዜ ያዕቆብ ደስ ይለዋል እስራኤልም ሐሤት ያደርጋል'),
  ('ee34ed2b-3d6b-501b-ae98-490fe0f572d5', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 1, 1, 'አቤቱ በስምኽ አድነኝ በኀይልኽም ፍረድልኝ'),
  ('9b6af102-1cae-51be-a563-8a60e9940118', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 2, 2, 'አቤቱ ጸሎቴን ስማኝ የአፌንም ቃል አድምጥ'),
  ('53125a33-3a6a-5110-a3c7-ea474a6c3d01', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 3, 3, 'እንግዳዎች ቁመውብኛልና ኀያላንም ነፍሴን ሽተዋታልና እግዚአብሔርን በፊታቸው አላደረጉትም'),
  ('98bac553-f780-5597-a678-3662e16d8674', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 4, 4, 'እንሆ እግዚአብሔር ይረዳኛል ጌታዬም ለነፍሴ ደጋፊዋ ነው'),
  ('05be7fdb-be1c-5204-aad2-3151216fba6c', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 5, 5, 'ክፋትን ወደ ጠላቶቼ ይመልሳታል በእውነትኽም አጥፋቸው'),
  ('dc2f0464-4189-5db2-a1bd-05801761e0af', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 6, 6, 'ከፈቃዴ እሠዋልኻለኹ አቤቱ መልካም ነውና ስምኽን አመሰግናለኹ'),
  ('d1a9a681-1197-583b-a73d-b4441181d86d', 'f015e2aa-b554-5855-a36f-9683e9aa23af', '236e6dc8-1d9b-59f1-a9ff-1dd029a74d7a', 7, 7, 'ከመከራ ዅሉ አድኖኛልና ዐይኔም በጠላቶቼ ላይ አይታለችና'),
  ('0c29fba5-472f-58b8-a9f1-3a00fc7a3e8d', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 1, 1, 'አቤቱ ጸሎቴን አድምጥ ልመናዬንም ቸል አትበል'),
  ('fc565113-2ab9-59de-abe0-7e29fae76cf9', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 2, 2, 'ተመልከተኝ ስማኝም በሐዘኔ ተቅበዘበዝኹ ተናወጥኹም'),
  ('32b81245-a686-59aa-a6aa-6ff1bf3296e0', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 3, 3, 'ከጠላት ድምፅ ከዐመፀኛም ግፍ የተነሣ ዐመፃን በላዬ ጥለውብኛልና በቍጣም ጠልተውኛልና'),
  ('cdda2d14-7546-5345-ad4e-340b1ff27b1f', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 4, 4, 'ልቤ በላዬ ተናወጠብኝ የሞት ድንጋጤም ወደቀብኝ'),
  ('b9699350-25d1-5a43-a87a-5553d3d956ac', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 5, 5, 'ፍርሀትና እንቅጥቅጥ መጡብኝ ጨለማም ሸፈነኝ'),
  ('7975a83d-374b-5312-a98b-1106fc4b9b73', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 6, 6, 'በርሬ ዐርፍ ዘንድ እንደ ርግብ ክንፍን ማን በሰጠኝ!'),
  ('58884107-7589-5b9f-ad3c-33d66bcad1a6', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 7, 7, 'እንሆ ኰብልዬ በራቅኹ በምድረ በዳም በተቀመጥኹ'),
  ('918fd009-1e92-5094-a299-5f925513d44e', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 8, 8, 'ከዐውሎና ከብርቱ ነፋስ ሸሽቼ በፈጠንኹ አልኹ'),
  ('451a4829-6796-5420-a58d-aa5fc1925780', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 9, 9, 'አቤቱ ግፍንና ጠብን በከተማ ውስጥ አይቻለኹና አስጥማቸው አንደበታቸውንም ቍረጥ'),
  ('8d9c3dab-098c-5fb9-a86f-da6f6a4e0fdc', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 10, 10, 'በቀንና በሌሊት በቅጥሯ ይከቧ፟ታል ዐመፃና ድካም ኀጢአትም በመካከሏ ነው'),
  ('3e76a34b-57cf-5bda-a5b1-71841a875098', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 11, 11, 'ተንኰልና ሽንገላ ከአደባባይዋ አይርቁም'),
  ('4a9883f4-ca9f-573d-a52a-41fa532a4e04', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 12, 12, 'ጠላትስ ቢሰድበኝ በታገሥኹ ነበር የሚጠላኝም ራሱን በላዬ ከፍ ከፍ ቢያደርግ ከርሱ በተሸሸግኹ ነበር'),
  ('3cb268c0-a46f-5fca-a480-fd14481f0102', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 13, 13, 'አንተ ግን እኩያዬ ሰው ባልንጀራዬና የልቤ ወዳጅ'),
  ('32933e84-73cc-566b-a6d0-3b708f8abf50', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 14, 14, 'መብልን ከእኔ ጋራ በአንድነት ያጣፈጥኽ ባንድ ልብ በእግዚአብሔር ቤት ተራመድን'),
  ('26dfac2d-816c-596a-a123-0c42bf2d49f1', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 15, 15, 'ሞት ይምጣባቸው በሕይወት ሳሉ ወደ ሲኦል ይውረዱ ክፋት በማደሪያቸውና በመካከላቸው ነውና'),
  ('598b481a-8987-598e-ae0b-3d28ece79305', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 16, 16, 'እኔ ግን ወደ እግዚአብሔር ጮኽኹ እግዚአብሔርም ሰማኝ'),
  ('f94d93bd-ae44-5c3e-acca-88f6f21399f1', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 17, 17, 'በማታና በጧት በቀትርም እናገራለኹ እጮኽማለኹ ቃሌንም ይሰማኛል'),
  ('c77f2228-e5fb-5cf9-aec3-a80fa842bc62', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 18, 18, 'በእኔ ላይ ብዙ ነበሩና ከሚቃረቡኝ ነፍሴን በሰላም አድናት'),
  ('ce42c466-52da-535a-a443-72982c443454', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 19, 19, 'ቤዛ የላቸውምና እግዚአብሔርንም አልፈሩትምና ከጥንት ዠምሮ የነበረ እግዚአብሔር ሰምቶ ያጐሰቍላ ቸዋል'),
  ('6e0ef853-3006-593c-abdd-ed68f3ff82b3', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 20, 20, 'ከርሱ ጋራ ሰላም በነበሩት ላይ እጁን ዘረጋ ኪዳኑንም አረከሱ'),
  ('2fe41a01-c21f-5fd9-aa1b-7189bd68e2f0', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 21, 21, 'አፉ ከቅቤ ይልቅ ለዘበ በልቡ ግን ሰልፍ ነበረ ቃሎቹም ከዘይት ይልቅ ለሰለሱ እነርሱ ግን እን ደ ተመዘዘ ሰይፍ ናቸው'),
  ('7e593dee-28e1-5577-a888-cbfdecc6303b', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 22, 22, 'ትካዜኽን በእግዚአብሔር ላይ ጣል ርሱም ይደግፍኻል ለጻድቁም ለዘለዓለም ሁከትን አይሰጠውም'),
  ('1394e5b7-72d2-5d21-a78c-3c6dbc404cc0', '0bde26c6-5330-54d5-a96e-c5a867ce7481', '0d6d6ae1-a6df-5db3-a940-ac45ba9e83ca', 23, 23, 'አንተ ግን አቤቱ ወደሞት ጕድጓድ ታወርዳቸዋለኽ የደም ሰዎችና ሸንጋዮች ዘመናቸው ግማሽ አይሞላ ም እኔ ግን አቤቱ እታመንኻለኹ'),
  ('02cd62cf-4327-59e2-a950-c37f3ff6cbab', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 1, 1, 'አቤቱ ሰው ረግጦኛልና ማረኝ ዅልጊዜም በሰልፍ አስጨንቆኛል'),
  ('7491fa73-d112-55f9-a213-0ac048d5b460', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 2, 2, 'የሚዋጉኝ በዝተዋልና ዅልጊዜ ቀኑን ዅሉ ጠላቶቼ ረገጡኝ'),
  ('405a911e-e32b-5a8e-a6b0-b1c893a1a9ad', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 3, 3, 'እኔ ግን ፈራኹ ባንተም ታመንኹ'),
  ('8514b82a-80b7-5eeb-af1b-7691c6df0cfa', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 4, 4, 'በእግዚአብሔር ቃሉን አመሰግናለኹ በእግዚአብሔር ታመንኹ አልፈራም ሰው ምን ያደርገኛል'),
  ('0ace0f1e-f867-54c2-a78b-2b338faa866d', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 5, 5, 'ዅልጊዜ ቃሎቼን ያጸይፉብኛል በእኔ ላይም የሚመክሩት ዅሉ ለክፉ ነው'),
  ('6adf46ef-c2cb-5b2e-a327-41c96fda412e', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 6, 6, 'ይሸምቁብኛል ይሸሽጉኝማል እነርሱም ተረከዜን ይመለካከታሉ ዅልጊዜም ነፍሴን ይሸምቁባታል'),
  ('5ee9caa5-5dcd-5351-a950-558f5400fd08', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 7, 7, 'በምንም ምን አታድናቸውም አሕዛብን በቍጣ ትጥላቸዋለኽ'),
  ('14700e26-4bb5-5984-a1f1-d3e14bc5ffb5', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 8, 8, 'አምላክ ሆይ ሕይወቴን ነገርኹኽ እንባዬን እንደ ትእዛዝኽ በፊትኽ አኖርኽ'),
  ('99463b09-146a-5303-a7b8-ebbfbbc8d1b2', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 9, 9, 'በጠራኹኽ ጊዜ ጠላቶቼ ወደ ዃላቸው ይመለሳሉ አንተ አምላኬ እንደ ኾንኽ እንሆ ዐወቅኹ'),
  ('0eb495e7-2496-58b9-acc6-7a7095eff996', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 10, 10, 'በእግዚአብሔር ቃሉን አመሰግናለኹ በእግዚአብሔር ቃሉን አከብራለኹ'),
  ('af72a287-529e-5cc5-a818-64f2ecb90f21', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 11, 11, 'በእግዚአብሔር ታመንኹ አልፈራም ሰው ምን ያደርገኛል'),
  ('0825744f-34ff-50d8-a757-3409cc03bc4b', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 12, 12, 'አቤቱ የምስጋና ስእለት የምሰጥኽ ከእኔ ዘንድ ነው'),
  ('501cb199-5808-5fc6-a164-f003dac3a498', '980a59d5-d40f-540f-a5f0-f7fbc940cd96', 'a7105d0b-7c3a-5671-a7b9-f8e7bc506ffc', 13, 13, 'ነፍሴን ከሞት እግሮቼን ከመውደቅ አድነኻልና በሕያዋን ብርሃን እግዚአብሔርን ደስ አሠኘው ዘንድ'),
  ('25a8186c-ab39-5ba6-a816-8fc82a653fcd', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 1, 1, 'ማረኝ አቤቱ ማረኝ ነፍሴ አንተን ታምናለችና ጕዳት እስክታልፍ ድረስ በክንፎችኽ ጥላ እታመናለኹ'),
  ('c4ceca90-2051-590e-a220-84e55c5d7a8a', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 2, 2, 'ወደሚረዳኝ እግዚአብሔር ወደ ልዑል እግዚአብሔር እጮኻለኹ'),
  ('c2cf72e4-25e8-5dc8-aaf5-a5f65bb7ac6c', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 3, 3, 'ከሰማይ ልኮ አዳነኝ ለረገጡኝም ውርደትን ሰጣቸው እግዚአብሔር ቸርነቱንና እውነቱን ላከ'),
  ('a4426687-358c-5fe1-aa06-2404ab3e4597', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 4, 4, 'ነፍሴን ከአንበሳዎች መካከል አዳናት ደንግጬ ተኛኹ የሰው ልጆች ጥርሳቸው ጦርና ፍላጻ አንደበታቸ ው የተሳለ ሾተል ነው'),
  ('33a82cee-cffa-5768-a871-d1a75bc2cb63', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 5, 5, 'አምላክ ሆይ በሰማያት ላይ ከፍ ከፍ በል ክብርኽም በምድር ዅሉ ላይ ትኹን'),
  ('026f15b4-142d-56e9-a9ba-e56015d32253', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 6, 6, 'ለእግሮቼ ወጥመድን አዘጋጁ ነፍሴንም አጐበጧት ጕድጓድ በፊቴ ቈፈሩ በርሱም ወደቁ'),
  ('7cbf1354-3907-529b-a5aa-24935e9be9cd', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 7, 7, 'ልቤ ጨካኝ ነው አቤቱ ልቤ ጨካኝ ነው እቀኛለኹ እዘምራለኹ'),
  ('2367a92b-fa29-545e-a3e7-885c9717635d', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 8, 8, 'ክብሬ ይነሣ በገናና መሰንቆም ይነሡ እኔም ማልጄ እነሣለኹ'),
  ('dca5226d-3494-5b64-a5b4-e10eb8430042', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 9, 9, 'አቤቱ በአሕዛብ ዘንድ አመሰግንኻለኹ በወገኖችም ዘንድ እዘምርልኻለኹ'),
  ('3736d862-a93f-50d5-ac1a-e3348d7b7676', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 10, 10, 'ምሕረትኽ እስከ ሰማይ ድረስ ከፍ ብላለችና እውነትኽም እስከ ደመናት ድረስ')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('09ce21f4-ec21-5c06-a312-015918324cc5', '476521c9-9760-577a-a48e-b0648009d523', '70aee7b7-007e-52e5-ad4e-b4f2e04d8950', 11, 11, 'አምላክ ሆይ በሰማያት ላይ ከፍ ከፍ በል ክብርኽም በምድር ዅሉ ላይ ትኹን'),
  ('7d84ced2-3505-599a-a9e3-eeffcf5aa467', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 1, 1, 'በእውነት ጽድቅን ብትናገሩስ የሰው ልጆች ሆይ በቅን ትፈርዳላችኹ'),
  ('be92beb2-faa9-5ac0-aae7-8ad5d3bb78d4', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 2, 2, 'በልባችኹ በምድር ላይ ኀጢአትን ትሠራላችኹና እጆቻችኹም ግፍን ይታታሉና'),
  ('e2013424-3aa1-5e78-abb5-6c30863809e3', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 3, 3, 'ኃጥኣን ከማሕፀን ዠምረው ተለዩ ከሆድም ዠምረው ሳቱ ሐሰትንም ተናገሩ'),
  ('619e250e-6ce3-58a2-adad-6e9b544198b4', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 4, 4, 'ቍጣቸው እንደ እባብ መርዝ ነው እንደምድር አውሬም ዦሮዋ የተደፈነ ነው'),
  ('21732c53-73fb-5768-abf9-303e9036e43d', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 5, 5, 'ዐዋቂ ሲደግምባት የአስማተኛውን ቃል እንደማትሰማ'),
  ('34e57b93-b7e0-53c9-ae81-f6778fb15f4d', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 6, 6, 'እግዚአብሔር ጥርሳቸውን በአፋቸው ውስጥ ይሰብራል እግዚአብሔር የአንበሳዎቹን መንጋጋቸውን ያደቃ፟ ል'),
  ('2a5c8266-5742-502f-af57-0b25d4b9bd2f', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 7, 7, 'እንደሚፈስ፟ ውሃ ይቀልጣሉ እስኪያደክማቸው ድረስ ፍላጻዎቹን ይገትራል'),
  ('7e2a3a73-fb91-5487-ae95-092e99bd5279', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 8, 8, 'እንደሚቀልጥ ሠም ያልቃሉ እሳት ወደቀች ፀሓይንም አላይዋትም'),
  ('0d804c99-f21b-56a7-a73d-8b2c7cda9560', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 9, 9, 'እሾኻችኹ ሳይታወቅ በትር ኾነ ሕያዋን ሳላችኹ በመዓቱ ይነጥቃችዃል'),
  ('8e448f6a-e6f7-531d-ac79-d551c67289fe', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 10, 10, 'ጻድቅ በቀልን ባየ ጊዜ ደስ ይለዋል በኀጢአተኛው ደምም እጁን ይታጠባል'),
  ('ce9dff22-b4d5-522e-ad5d-0272ad09c5ec', '46c37a6b-268c-56b6-af33-3d343f0b4b4f', '3c2e0ff5-acae-5f73-a374-a7356c4f7a88', 11, 11, 'ሰውም፦በእውነት ለጻድቅ ፍሬ አለው በእውነት በምድር ላይ የሚፈርድ አምላክ አለ ይላል'),
  ('edad7138-e3a9-5484-a870-6619abaf83fa', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 1, 1, 'አምላኬ ሆይ ከጠላቶቼ አድነኝ በላዬም ከቆሙት አስጥለኝ'),
  ('20cee298-7a31-5c4a-a0fc-b8eb2b42743a', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 2, 2, 'ከግፍ አድራጊዎች ታደገኝ ከደም ሰዎችም አድነኝ'),
  ('268003c9-0366-5233-a622-669848d25158', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 3, 3, 'እንሆ ነፍሴን ሸምቀውባታልና ብርቱዎችም በላዬ ተሰበሰቡ አቤቱ በበደሌም አይደለም በኀጢአቴም አይ ደለም'),
  ('1cda45cc-8a8b-5ad2-a0f4-8edb6f764ba6', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 4, 4, 'ያለበደል ሮጥኹ ተዘጋጀኹም ተነሥ ተቀበለኝ እይም'),
  ('99f25606-bb01-5967-a2ed-51e53f850271', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 5, 5, 'አንተም አቤቱ የኀያላን አምላክ የእስራኤል አምላክ አሕዛብን ዅሉ ትጐበኛቸው ዘንድ ተነሥ ዐመፅ የሚያደርጉትን ዅሉ አትማራቸው'),
  ('9997c90a-a451-5735-ae90-3829550caf9e', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 6, 6, 'ማታ ይመለሱ እንደ ውሻዎችም ይራቡ በከተማም ይዙሩ'),
  ('41dddfba-a2e1-5ef3-af6a-1e230979c1f4', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 7, 7, 'እንሆ በአፋቸው አሰምተው ይናገራሉ ሰይፍም በከንፈሮቻቸው አለ ማን ይሰማል ይላሉ'),
  ('b59a917c-0458-5149-ac0e-e7ab1018d932', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 8, 8, 'አንተ ግን አቤቱ ትሥቅባቸዋለኽ አሕዛብንም ዅሉ ትንቃቸዋለኽ'),
  ('4b65bd5e-f918-517c-a771-5c2cc487e20b', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 9, 9, 'እግዚአብሔር መጠጊያዬ ነውና ኀይሌን ወዳንተ አስጠጋለኹ'),
  ('61ced6dc-be99-5740-acb5-6ac7b640440d', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 10, 10, 'የአምላኬ ቸርነቱ ይገናኘኛል አምላኬ በጠላቶቼ ላይ ያሳየኛል'),
  ('68c38e44-a768-504d-a67f-40976e6cd32e', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 11, 11, 'ሕግኽን እንዳይረሱ አትግደላቸው አቤቱ ጋሻዬ በኀይልኽ በትናቸው አውርዳቸውም'),
  ('0dbc899e-6d1e-5098-a93f-7ba6a683c175', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 12, 12, 'ስለአፋቸው ኀጢአት ስለከንፈራቸውም ቃል መርገምንና ሐሰትን ስለሚናገሩ በትዕቢታቸው ይጠመዱ'),
  ('25815542-a6ec-5c2b-a730-9777c233630c', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 13, 13, 'በቍጣ አጥፋቸው እንዳይኖሩም አጥፋቸው የያዕቆብም አምላክ እስከምድር ዳርቻ ድረስ እንዲገዛ ይወ ቁ'),
  ('5bca26b3-5313-514a-a89a-677af236fc98', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 14, 14, 'ማታ ይመለሱ እንደ ውሻዎችም ይራቡ በከተማም ይዙሩ'),
  ('7e6025c8-a992-589f-a057-f9b0ac270974', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 15, 15, 'እነርሱም መብል ለመፈለግ ይበተኑ ያልጠገቡ እንደ ኾነም ያንጐረጕራሉ'),
  ('106cad55-1a64-557f-a064-8a448ea0545a', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 16, 16, 'እኔ ግን ለኀይልኽ እቀኛለኹ በምሕረትኽም ማልዶ ደስ ይለኛል በመከራዬ ቀን መጠጊያዬና ዐምባዬ ኾነኸኛልና'),
  ('2538f1d0-2821-561e-a514-2422600bc81b', '690f4226-6ac7-577c-aa5d-3f4d2e93f8b4', 'c0d1913a-9472-5c67-a72e-b8e4c5f1b336', 17, 17, 'ረዳቴ ሆይ ለአንተ ለአምላኬ እዘምራለኹ አንተ አምላኬ መጠጊያዬ ምሕረቴም ነኽና'),
  ('99270947-94a8-599e-ac78-6cbf52de96bd', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 1, 1, 'አቤቱ ጣልኸን አፈረስኸንም ተቈጣኸን ይቅርም አልኸን'),
  ('719ece0b-0dca-5fbc-a01c-b5c5ed1bed48', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 2, 2, 'ምድርን አናወጥኻት አወክኻትም ተናውጣለችና ቍስሏን ፈውስ'),
  ('ce003e3c-ec26-5cb9-a658-3a93db3dc65b', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 3, 3, 'ለሕዝብኽ ጭንቅን አሳየኻቸው አስደንጋጩንም ወይን አጠጣኸን'),
  ('75b0ac8b-b462-5c41-a629-27a02b5bb92e', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 4, 4, 'ከቀስት ፊት ያመልጡ ዘንድ ለሚፈሩኽ ምልክትን ሰጠኻቸው'),
  ('8a46e92d-bdad-5af4-ae3e-1c2924601f9c', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 5, 5, 'ወዳጆችኽ እንዲድኑ በቀኝኽ አድን አድምጠኝም'),
  ('7b2ebf49-5306-5869-ab5a-496e37ea8de9', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 6, 6, 'እግዚአብሔር በቅድስናው ተናገረ ደስ ይለኛል ሴኬምንም እካፈላለኹ የሱኮትንም ሸለቆ እሰፍራለኹ'),
  ('66d1ee16-994f-5b49-aa6e-9584f59fca7b', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 7, 7, 'ገለዓድ የእኔ ነው ምናሴም የእኔ ነው ኤፍሬም የራሴ መጠጊያ ነው ይሁዳ ንጉሤ ነው'),
  ('959d8111-cd60-57a7-a05a-5b2a3e88c616', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 8, 8, 'ሞዐብ መታጠቢያዬ ነው በኤዶምያስ ላይ ጫማዬን እዘረጋለኹ ፍልስጥኤም ይገዙልኛል'),
  ('0387cb1e-c1fa-596d-ae4f-fb708552b4ec', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 9, 9, 'ወደ ጽኑ ከተማ ማን ይወስደኛል ማንስ እስከ ኤዶምያስ ይመራኛል'),
  ('6e4fb152-e405-504f-aa40-304035fdbea1', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 10, 10, 'አቤቱ የጣልኸን አንተ አይደለኽምን አምላክ ሆይ ከሰራዊታችን ጋራ አትወጣም'),
  ('1f08cff6-86bf-525c-a3ac-1997a971d0f1', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 11, 11, 'በመከራችን ረድኤትን ስጠን የሰውም ማዳን ከንቱ ነው'),
  ('4b3f128b-13f0-538b-a9b8-ace3a2e58cbf', '8871a3c1-f2b7-5d5a-a78f-34b6484a265f', '96b74493-7bfe-5c8c-a686-53ec71dcca54', 12, 12, 'በእግዚአብሔር ኀይልን እናደርጋለን ርሱ የሚያስጨንቁንን ያዋርዳቸዋልና'),
  ('afbe8a9f-61a1-54ea-aad0-7e6f6f43113a', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 1, 1, 'አምላክ ሆይ ልመናዬን ስማ ጸሎቴንም አድምጥ'),
  ('5cd7c27c-e715-5355-a30c-af465fd48f3a', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 2, 2, 'ልቤ ተስፋ በቈረጠ ጊዜ ከምድር ዳርቻ ወዳንተ እጮኻለኹ በድንጋይ ላይ ከፍ ከፍ አደረግኸኝ'),
  ('8a8d3ada-c41f-588b-aba9-5090fc7401a2', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 3, 3, 'ጽኑ ግንብ በጠላት ፊት ተስፋዬም ኾነኸኛልና መራኸኝ'),
  ('ec26c03c-3c37-52d5-a3fc-2b6d0343b621', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 4, 4, 'በድንኳንኽ ለዘለዓለም እኖራለኹ በክንፎችኽም ጥላ እጋረዳለኹ'),
  ('fbf05616-bba6-5014-af3a-40971654fa19', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 5, 5, 'አቤቱ አንተ ስእለቴን ሰምተኻልና ስምኽንም ለሚፈሩ ርስትኽን ሰጠኻቸው'),
  ('cb53688a-7bfb-59df-a4f5-ca91dfd94df4', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 6, 6, 'ለንጉሥ ከቀን በላይ ቀን ትጨምራለኽ ዓመታቱም ከትውልድ ወደ ትውልድ ይኾናሉ'),
  ('31df51a9-2281-5eeb-a4bd-c3222e8d51a1', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 7, 7, 'በእግዚአብሔር ፊት ለዘለዓለም ይኖራል ይጠብቁት ዘንድ ምሕረትንና እውነትን አዘጋጅለት'),
  ('97f5809f-8ea4-5ad3-a89d-458b1cca8b55', '5b60bf67-afe2-520c-a10e-2f7baeda021a', '5aeff855-7168-5058-ac60-f57b5d37b356', 8, 8, 'እንዲሁ ለስምኽ ለዘለዓለም እዘምራለኹ ስእለቴን ዅልጊዜ እፈጽም ዘንድ'),
  ('c94540cd-c6d8-5643-a3bf-d46963ae4f7c', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 1, 1, 'ነፍሴ ለእግዚአብሔር የምትገዛ አይደለችምን መድኀኒቴ ከርሱ ዘንድ ናትና'),
  ('a6c92fd5-2f09-5943-a308-c99948eaf71c', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 2, 2, 'ርሱ አምላኬ መድኀኒቴም ነውና ርሱ መጠጊያዬ ነው እጅግም አልታወክም'),
  ('570d6df6-fd43-5fab-a8f8-ef29ad36c184', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 3, 3, 'እስከ መቼ በሰው ላይ ትቆማላችኹ እናንተ ዅላችኹ እንዳዘነበለ ግድግዳ እንደ ፈረሰም ቅጥር ትገድ ላላችኹ'),
  ('623db718-182f-510f-a84e-52a1f66b81c0', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 4, 4, 'ነገር ግን ክብሬን ይሽሩ ዘንድ መከሩ ሐሰትንም ይወዳ፟ሉ በአፋቸው ይባርካሉ በልባቸውም ይረግማሉ'),
  ('9d3dea91-c8b8-594a-a264-cac727e72ca8', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 5, 5, 'ነገር ግን ነፍሴ ሆይ አንቺ ለእግዚአብሔር ተገዢ ተስፋዬ ከርሱ ዘንድ ናትና'),
  ('aba87948-5527-5fd1-a341-521912bb7e63', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 6, 6, 'ርሱ አምላኬ መድኀኒቴም ነውና ርሱ መጠጊያዬ ነው አልታወክም'),
  ('3e204a4b-8de2-5324-a41f-5afebd2126de', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 7, 7, 'መድኀኒቴና ክብሬ በእግዚአብሔር ነው የረድኤቴ አምላክ ተስፋዬም እግዚአብሔር ነው'),
  ('11416203-be7f-517c-a5a2-205c5f7a0d21', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 8, 8, 'የሕዝብ ማኅበር ዅላችኹ በርሱ ታመኑ ልባችኹንም በፊቱ አፍሱ፟ እግዚአብሔር ረዳታችን ነው'),
  ('0bd6fce7-2126-5f6a-adbd-3f47ec3922a2', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 9, 9, 'ነገር ግን የሰው ልጆች ከንቱ ናቸው የሰው ልጆችም ሐሰተኛዎች ናቸው በሚዛንም ይበድላሉ እነርሱስ በፍጹም ከንቱ ናቸው'),
  ('5f2a290f-c084-5ed2-a3bd-1fa30492460e', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 10, 10, 'ዐመፃን ተስፋ አታድርጉ ቅሚያንም አትተማመኑት ባለጠግነት ቢበዛ ልባችኹ አይኵራ'),
  ('6a78e9b6-593f-5102-af32-a86f41995b29', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 11, 11, 'እግዚአብሔር አንድ ጊዜ ተናገረ እኔም ይህን ብቻ ሰማኹ ኀይል የእግዚአብሔር ነው'),
  ('19baecd1-7864-5042-acd1-2a6cd8720bcb', '21712e0a-e110-5ad7-abbb-31fa1eee436c', 'c5dc888b-a5a4-5e9b-a50c-7f33269899f2', 12, 12, 'አቤቱ ምሕረትም ያንተ ነው አንተ ለያንዳንዱ እንደ ሥራው ፍዳውን ትሰጣለኽና'),
  ('6903fbbb-5610-5391-a881-0910ea016117', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 1, 1, 'አምላኬ አምላኬ ወዳንተ እገሠግሣለኹ ነፍሴ አንተን ተጠማች ሥጋዬ አንተን እንዴት ናፈቀች ዕንጨት ና ውሃ በሌለበት በምድረ በዳ'),
  ('f59199a2-27d2-5dbb-a0e7-a36909ca19d7', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 2, 2, 'ኀይልኽንና ክብርኽን አይ ዘንድ እንዲሁ በመቅደስ ውስጥ ተመለከትኹኽ'),
  ('e4eebc56-3004-55b4-adbc-e9290ca31b19', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 3, 3, 'ምሕረትኽ ከሕይወት ይሻላልና ከንፈሮቼ ያመሰግኑኻል'),
