  ('f12aa9f2-e7e0-57df-a1c2-23635ca073ab', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 5, 5, 'ነፍሴ በቅቤና በስብ እንደሚጠግቡ ትጠግባለች ከንፈሮቼም ስምኽን በደስታ ያመሰግናሉ'),
  ('4523bdee-6adc-5e4b-a0df-99b9d661bb87', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 6, 6, 'በመኝታዬም ዐስብኻለኹ በማለዳም እናገርልኻለኹ'),
  ('ca58baa2-1762-57e2-a5f6-0dbcf9b83424', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 7, 7, 'ረዳቴ ኾነኸኛልና በክንፎችኽም ጥላ ደስ ይለኛልና'),
  ('afaee387-fb75-5f18-a3b3-73f9955cb8fb', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 8, 8, 'ነፍሴ በዃላኽ ተከታተለች እኔንም ቀኝኽ ተቀበለችኝ'),
  ('cfa072a4-d83c-5361-a89c-87db8691a9b8', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 9, 9, 'እነርሱ ግን ነፍሴን ለከንቱ ፈለጓት ወደ ምድር ጥልቅ ይገባሉ'),
  ('0d2f5c34-9966-5605-ad6a-d90ab429a90e', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 10, 10, 'ለሰይፍ እጅ ዐልፈው ይሰጣሉ የቀበሮም ዕድል ፈንታ ይኾናሉ'),
  ('c6386fb5-bd60-595d-a310-3c45b00d0ce5', 'bcfbb663-4012-588c-a06a-50d772d8d13e', 'b376b674-62d9-506c-a890-77251354d0c4', 11, 11, 'ንጉሥ ግን በእግዚአብሔር ደስ ይለዋል በርሱ የሚምል ዅሉ ይከብራል ሐሰትን የሚናገር አፍ ይዘጋ ልና'),
  ('5717423a-edf5-59a3-abe1-3af09d4f4e60', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 1, 1, 'አቤቱ ወዳንተ በለመንኹ ጊዜ ጸሎቴን ስማኝ ከጠላትም ፍርሀት ነፍሴን አድን'),
  ('901f10c8-116d-59ed-aa02-98bff9ec8cc9', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 2, 2, 'ከክፉዎች ሸንጎ ከዐመፀኛዎችም ብዛት ሰውረኝ'),
  ('98f9d6bc-221f-5c01-a6bf-2781c9fb6abc', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 3, 3, 'እንደ ሰይፍ ምላሳቸውን አሰሉ መራራ ነገርን ለማድረግ'),
  ('caa4cff8-d1f0-5c9d-a514-e85928c5940f', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 4, 4, 'ንጹሕንም በስውር ለመንደፍ ቀስትን ገተሩ ድንገት ይነድፉታል አይፈሩምም'),
  ('8221ac42-8173-5ea1-a9a8-94c99ababf7f', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 5, 5, 'ለእነርሱ ለራሳቸው ክፉ ነገርን አጸኑ ወጥመድን ይሰውሩ ዘንድ ተማከሩ ማንስ ያየናል ይላሉ'),
  ('74ed38b4-6a31-58bc-a829-27fb685e24bf', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 6, 6, 'ዐመፃን ፈልጓት ሲፈትኑም አለቁ የሰው የውስጥ ዐሳቡና ልቡ የጠለቀ ነው'),
  ('31f204ae-bfbb-5f7a-a1ce-07296ab2bf24', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 7, 7, 'እግዚአብሔርም ከፍ ከፍ ይላል የድንገትም ፍላጻ ያቈስላቸዋል'),
  ('7f0a856d-0c65-549f-aa52-ee65a48a6ccb', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 8, 8, 'አንደበታቸው ያሰናክላቸዋል የሚያይዋቸውም ዅሉ ይደነግጣሉ'),
  ('2b93320a-dbcf-5cb6-a05e-869dca2c2e48', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 9, 9, 'ሰዎች ዅሉ ፈሩ የእግዚአብሔርንም ሥራ ተናገሩ ሥራውንም አስተዋሉ'),
  ('86f4d608-1590-5945-a4a6-affbfc0350f5', '980ac543-3122-5601-a409-cab66318978f', 'e2cb1cfa-b119-57e0-a229-af790b0cde86', 10, 10, 'ጻድቅ በእግዚአብሔር ደስ ይለዋል በርሱም ይታመናል ልባቸውም የቀና ዅሉ እልል ይላሉ'),
  ('0a14dabc-b223-5367-a2ca-ff3968266ca4', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 1, 1, 'አቤቱ በጽዮን ለአንተ ምስጋና ይገ፟ባ፟ል ለአንተም ጸሎት ይቀርባል'),
  ('54444437-a336-5221-ac6c-d2683eb01e3f', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 2, 2, 'ሥጋ ዅሉ ጸሎትን ወደምትሰማ ወዳንተ ይመጣል'),
  ('1eecbc89-e660-5a69-a6cc-8243b18e8502', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 3, 3, 'የዐመፃ ነገር በረታብን ኀጢአታችንንስ አንተ ይቅር ትላለኽ'),
  ('04f95a52-5030-59ae-acc7-55d7f854193c', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 4, 4, 'አንተ የመረጥኸው በአደባባዮችኽም ለማደር የተቀበልኸው ምስጉን ነው ከቤትኽ በረከት እንጠግባለን'),
  ('3a5c3e69-0a54-5b6c-af8f-11d744b44583', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 5, 5, 'ቤተ መቅደስኽ ቅዱስ ነው በጽድቅም ድንቅ ነው በምድር ዳርቻ ዅሉና በሩቅ ባሕር ውስጥ ላሉ ተስፋ ቸው የኾንኽ አምላካችንና መድኀኒታችን ሆይ ስማን'),
  ('657f2da4-226f-594c-a1e8-a398b6d09d6d', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 6, 6, 'በጕልበትኽ ተራራዎችን አጸናኻቸው በኀይልም ታጥቀኻል'),
  ('89b157eb-06c9-5ba2-a1a7-ac0b6e777ba2', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 7, 7, 'የባሕሩን ጥልቀት የሞገድንም ጩኸት ታናውጣለኽ'),
  ('e348399f-051d-5df1-aece-93b3dc868a73', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 8, 8, 'ከተኣምራትኽ የተነሣ አሕዛብ ይደነግጣሉ በምድር ዳርቻም የሚኖሩ ይፈራሉ የጧትንና የማታን መውጫ ደስ ታሠኛቸዋለኽ'),
  ('2371bb5b-0a71-5bab-a12a-f5a88a85d602', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 9, 9, 'ምድርን ጐበኘኻት አጠጣኻትም ብልጥግናዋንም እጅግ አበዛኽ የእግዚአብሔርን ወንዝ ውሃን የተመላ ነ ው ምግባቸውን አዘጋጀኽ እንዲሁ ታሰናዳለኽና'),
  ('887e9043-d261-5f2a-a8e2-d78e500fc60b', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 10, 10, 'ትልሟን ታረካለኽ ቦይዋንም ታስተካክላለኽ በነጠብጣብ ታለሰልሳታለኽ ቡቃያዋንም ትባርካለኽ'),
  ('a93fd737-a496-5d9d-afc5-52b6509c268b', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 11, 11, 'በቸርነትኽ ዓመትን ታቀዳጃለኽ ምድረ በዳውም ስብን ይጠግባል'),
  ('e3c00560-457d-511a-a246-98f91d5b0262', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 12, 12, 'የምድረ በዳ ተራራዎች ይረካሉ ኰረብታዎችም በደስታ ይታጠቃሉ'),
  ('4e2b64e0-7a09-5d32-a214-2cc7f097820c', 'ebfa0368-1c7c-5072-a999-ffad36212d1b', '684345d6-4401-5199-aa4e-77eb576f9b84', 13, 13, 'ማሰማሪያዎች መንጋዎችን ለበሱ ሸለቆዎችም በእኽል ተሸፈኑ በደስታ ይጮኻሉ ይዘምራሉም'),
  ('d43f71dd-b502-5e42-a255-4d24667381f2', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 1, 1, 'በምድር ያላችኹ ዅሉ ለእግዚአብሔር እልል በሉ'),
  ('885fcf01-3842-55e4-a09d-c25fd57a4503', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 2, 2, 'ለስሙም ዘምሩ ለምስጋናውም ክብርን ስጡ'),
  ('3a2bf536-e026-5521-a490-f39c9a908c1e', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 3, 3, 'እግዚአብሔርን እንዲህ በሉት፦ሥራኽ ግሩም ነው ኀይልኽ ብዙ ሲኾን ጠላቶች ዋሹብኽ'),
  ('b9c1aac6-800d-5575-aff0-56d382a76deb', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 4, 4, 'በምድር ያሉ ዅሉ ለአንተ ይሰግዳሉ ለአንተም ይዘምራሉ ለስምኽም ይዘምራሉ'),
  ('e6d57220-58bd-5b0c-a30c-578a94961b8f', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 5, 5, 'ኑ የእግዚአብሔርንም ሥራ እዩ ከሰው ልጆች ይልቅ በምክር ግሩም ነው'),
  ('e75c901b-9572-55f3-a17a-2724f0cdd304', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 6, 6, 'ባሕርን የብስ አደረጋት ወንዙንም በእግር ተሻገሩ በዚያ በርሱ ደስ ይለናል'),
  ('a3027da7-d68b-520c-ad5d-43f2640b927e', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 7, 7, 'በኀይሉ ለዘለዓለም ይገዛል ዐይኖቹ ወደ አሕዛብ ይመለከታሉ ዐመፀኛዎች ራሳቸውን ከፍ ከፍ አያድር ጉ'),
  ('ec355109-8085-571e-a409-26821449e598', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 8, 8, 'አሕዛብ ሆይ አምላካችንን ባርኩ የምስጋናውንም ድምፅ አሰሙ'),
  ('bc0eb113-6428-513c-ac82-59e9a8e53221', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 9, 9, 'ነፍሴን በሕይወት ያኖራታል እግሮቼንም ለመናወጥ አልሰጠም'),
  ('b1a0afdb-526e-5987-a576-6d41c9d2c29d', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 10, 10, 'አቤቱ ፈትነኸናልና ብርንም እንደሚያነጥሩት አንጥረኸናልና'),
  ('63c16217-7a86-51ba-a369-735e31b87df7', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 11, 11, 'ወደ ወጥመድ አገባኸን በዠርባችንም መከራን አኖርኽ'),
  ('2010a3f7-4449-513f-ae07-9b00c9a7167d', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 12, 12, 'በራሳችን ላይ ሰውን አስረገጥኸን በእሳትና በውሃ መካከል ዐለፍን ወደ ዕረፍትም አወጣኸን 13-14 ከሚቃጠል መሥዋዕት ጋራ ወደ ቤትኽ እገባለኹ በመከራዬ ጊዜ በአፌ የተናገርኹትን ከንፈሮቼም ያ ሉትን ስእለቴን ለአንተ እፈጽማለኹ'),
  ('dfe013d9-5177-5e37-a1dc-23402205933e', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 13, 15, 'ከዕጣንና ከወጠጤዎች ጋራ ለሚቃጠል መሥዋዕት ፍሪዳን አቀርባለኹ ላሞችንና ፍየሎችን እሠዋልኻለኹ'),
  ('4cc0c40a-7ad8-5c4c-a167-8fcc368904e6', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 14, 16, 'እግዚአብሔርን የምትፈሩት ዅሉ ኑ ስሙኝ ለነፍሴ ያደረገላትን ልንገራችኹ'),
  ('2334d3f6-94c3-5707-a243-e6458497ce1d', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 15, 17, 'በአፌ ወደ ርሱ ጮኽኹ በአንደበቴም አመሰገንኹት'),
  ('f91a637f-554f-570c-a2f8-1a375e55b717', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 16, 18, 'በልቤስ በደልን አይቼ ብኾን ጌታ አይሰማኝም ነበር'),
  ('32ec332f-21be-515c-aaa9-1934938d2215', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 17, 19, 'ስለዚህ እግዚአብሔር ሰማኝ የልመናዬን ድምፅ አደመጠ'),
  ('47a9ab3d-628c-5440-adee-992d499b5e35', '8a7ea611-1fae-5601-a0f7-44f01b705e80', '8a0a2dc1-fbe1-51d8-a681-aa7182cf4cf8', 18, 20, 'ጸሎቴን ያልከለከለኝ ምሕረቱንም ከእኔ ያላራቀ እግዚአብሔር ይመስገን'),
  ('331ca594-634a-50e0-acca-154614e3406b', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 1, 1, 'እግዚአብሔር ይማረን ይባርከንም ፊቱንም በላያችን ያብራ'),
  ('27e27b74-e7bd-5962-aa69-57abe35c7081', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 2, 2, 'በአሕዛብ ዅሉ መካከል ማዳንኽን መንገድኽንም በምድር እናውቅ ዘንድ'),
  ('5f8ae8b9-0a4f-59f7-ae20-f66fedeb8522', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 3, 3, 'አቤቱ አሕዛብ ያመስግኑኽ አሕዛብ ዅሉ ያመስግኑኽ'),
  ('781112f6-9ce6-5051-ad10-43e034326162', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 4, 4, 'ለአሕዛብ በቅን ትፈርድላቸዋለኽና አሕዛብንም በምድር ላይ ትመራለኽና አሕዛብ ደስ ይበላቸው ሐሤት ም ያድርጉ'),
  ('a124035e-684d-5fa7-a083-cf28ef5dc11b', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 5, 5, 'አቤቱ አሕዛብ ያመስግኑኽ አሕዛብ ዅሉ ያመስግኑኽ'),
  ('f1c4f314-fe76-54fe-a0c8-6faac7f9b4bf', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 6, 6, 'ምድር ፍሬዋን ሰጠች እግዚአብሔር አምላካችንም ይባርከናል'),
  ('db56ae8a-5b5d-5b71-a950-bad88a3dbc43', 'a6e91a0f-0951-56d0-a02a-7b4b3cb9151b', 'afb18631-cbbe-57e1-a714-972dcdeb1202', 7, 7, 'እግዚአብሔር ይባርከናል የምድርም ዳርቻ ዅሉ ይፈሩታል'),
  ('e2c1127f-df18-5499-aa60-a424b47caabc', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 1, 1, 'እግዚአብሔር ይነሣ ጠላቶቹም ይበተኑ የሚጠሉትም ከፊቱ ይሽሹ'),
  ('58e2fc54-c8cb-57ba-a983-133c885ee118', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 2, 2, 'ጢስ እንደሚበን፟ እንዲሁ ይብነኑ ሠም በእሳት ፊት እንደሚቀልጥ እንዲሁ ኃጥኣን ከእግዚአብሔር ፊ ት ይጥፉ'),
  ('00a065da-40a0-57e3-ab4f-26f0433e64e3', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 3, 3, 'ጻድቃንም ደስ ይበላቸው በእግዚአብሔርም ፊት ሐሤት ያድርጉ በደስታም ደስ ይበላቸው'),
  ('60e01255-bf97-549e-ac0e-d102c6b2e9ea', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 4, 4, 'ለእግዚአብሔር ተቀኙ ለስሙም ዘምሩ ወደ ምድረ በዳ ለወጣም መንገድ አድርጉ ስሙ እግዚአብሔር ነው በፊቱም ደስ ይበላችኹ በፊቱም ይደነግጣሉ'),
  ('af6eb54d-56d8-5f4c-af3f-9f96c965c912', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 5, 5, 'እግዚአብሔር በቅዱስ ቦታው ለድኻ አደጎች አባት ለባልቴቶችም ዳኛ ነው'),
  ('6c951443-fa8f-5bd1-ab6d-c7536948995a', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 6, 6, 'እግዚአብሔር ብቸኛዎችን በቤት ያሳድራቸዋል እስረኛዎችንም በኀይሉ ያወጣቸዋል ዐመፀኛዎች ግን በም ድረ በዳ ይኖራሉ'),
  ('1dc46660-55a5-5281-aa43-cc780eee7ad5', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 7, 7, 'አቤቱ በሕዝብም ፊት በወጣኽ ጊዜ በምድረ በዳም ባለፍኽ ጊዜ ምድር ተናወጠች'),
  ('abf529ec-64b2-51cb-acbd-d9009e9384e9', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 8, 8, 'ከሲና አምላክ ፊት ከእስራኤል አምላክ ፊት ሰማያትም አንጠበጠቡ'),
  ('cf364a20-5e8d-596b-a1fe-41c7f1e088a5', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 9, 9, 'አቤቱ የሞገስን ዝናብ ለርስትኽ አዘነብኽ በደከመም ጊዜ አንተ አጸናኸው'),
  ('5e42b3b6-4715-50e3-abeb-bbd795413a59', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 10, 10, 'እንስሳዎችኽ በውስጡ ዐደሩ አቤቱ በቸርነትኽ ለድኻዎች አዘጋጀኽ'),
  ('28dc8841-9973-5cfa-a720-7bf182bf9ec0', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 11, 11, 'እግዚአብሔር ቃሉን ሰጠ የሚያወሩት ብዙ ሰራዊት ናቸው'),
  ('0d53c72e-b033-5ccc-a38d-8ed08c6b50b3', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 12, 12, 'የሰራዊት ነገሥታት ፈጥነው ይሸሻሉ በቤትም የምትኖር ምርኮን ተካፈለች'),
  ('79744d4a-9212-557b-a73d-1cdd00272d0d', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 13, 13, 'በርስቶች መካከል ብታድሩ ከብር እንደ ተሠሩ እንደ ርግብ ክንፎች በቅጠልያ ወርቅም እንደ ተለበ ጡ ላባዎቿ ትኾናላችኹ'),
  ('9e6ad9ae-45c4-5ae2-a1af-37afb9de353f', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 14, 14, 'ሰማያዊ ንጉሥ በላይዋ ባዘዘ ጊዜ በሰልሞን ላይ በረዶ ዘነበ'),
  ('b7583e14-0f14-5cd8-ac74-6d108ced4b1b', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 15, 15, 'የእግዚአብሔር ተራራ የለመለመ ተራራ ነው የጸና ተራራና የለመለመ ተራራ ነው'),
  ('d5a5b565-644f-5f23-a2e9-101163f94737', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 16, 16, 'የጸኑ ተራራዎች ለምን ይነሣሉ እግዚአብሔር ይህን ተራራ ያድርበት ዘንድ ወደደው በእውነት እግዚ አብሔር ለዘለዓለም ያድርበታል'),
  ('ba40e316-b823-5478-a73f-4ca6999b77a4', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 17, 17, 'የእግዚአብሔር ሠረገላዎች የብዙ ብዙ ሺሕ ናቸው ጌታ በመቅደሱ በሲና በመካከላቸው ነው'),
  ('6fdfd802-aa21-50e3-a747-902611d0cd19', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 18, 18, 'ወደ ላይ ዐረግኽ ምርኮን ማረክኽ ስጦታንም ለሰዎች ሰጠኽ ደግሞም ለዐመፀኛዎች በዚያ ያድሩ ዘን ድ'),
  ('23e388f7-90f8-5276-a22f-48a54fdb5b07', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 19, 19, 'እግዚአብሔር አምላክ ቡሩክ ነው እግዚአብሔር በየዕለቱ ቡሩክ ነው የመድኀኒታችን አምላክ ይረዳና ል'),
  ('b716eb9c-0233-5f4b-a259-aa249d29c077', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 20, 20, 'አምላካችንስ የደኅንነት አምላክ ነው ከሞት መውጣትም ከእግዚአብሔር ነው'),
  ('5c080661-32f6-5401-a57e-961440748459', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 21, 21, 'ነገር ግን እግዚአብሔር የጠላቶቹን ራስ በኀጢአት የሚኼድንም የጠጕሩን ዐናት ይቀጠቅጣል'),
  ('4f8bfb0a-4a19-5cef-a829-b226fb7b9da2', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 22, 22, 'እግዚአብሔር እንዲህ አለ፦ከባሳን አመጣቸዋለኹ ከባሕርም ጥልቅ እመልሳቸዋለኹ'),
  ('6c560057-f2a0-51c5-abde-3b851c9c89b9', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 23, 23, 'እግሮችኽ በደም ይረገጡ ዘንድ የውሻዎችኽ ምላስ በጠላቶች ላይ ይኾን ዘንድ'),
  ('18fda528-f20b-5ca6-a64b-17aba2632483', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 24, 24, 'የአምላኬ የንጉሥ መንገድ በመቅደሱ አቤቱ መንገድኽ ተገለጠ'),
  ('59cd5252-a3c5-5f0b-aec0-0474ed56bdca', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 25, 25, 'አለቃዎች ቀደሙ መዘምራንም ተከተሉ ከበሮን በሚመቱ በቈነዣዥት መካከል'),
  ('f107a9cc-681b-5487-a564-75a299f397fb', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 26, 26, 'እግዚአብሔርን በጉባኤ ጌታችንንም በእስራኤል ምንጭ አመስግኑት'),
  ('ca61f7cf-5633-5e13-a4d9-d6d1a240e698', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 27, 27, 'ወጣቱ ብንያም በጕልበቱ በዚያ አለ ገዢዎቻቸው የይሁዳ አለቃዎች የዛብሎን አለቃዎችና የንፍታሌም ም አለቃዎች'),
  ('02b04396-dcb4-5f64-af63-1d0898fc6baa', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 28, 28, 'አቤቱ ኀይልኽን እዘዝ አቤቱ ይህንም ለእኛ የሠራኸውን አጽናው'),
  ('1be45c04-d7a1-55f8-a31f-217ab5e9b537', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 29, 29, 'በኢየሩሳሌም ስላለው መቅደስኽ ነገሥታት እጅ መንሻን ለአንተ ያመጣሉ'),
  ('7a60f0f2-d565-5b24-a89b-0e562233592d', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 30, 30, 'በሸምበቆ ውስጥ ያሉትን አራዊት በአሕዛብ ውስጥ ያሉትን የበሬዎችንና የወይፈኖችን ጉባኤ ገሥጽ እንደ ብር የተፈተኑት አሕዛብ እንዳይዘጉ ሰልፍን የሚወዱትን አሕዛብን በትናቸው'),
  ('8802198c-5e2f-517a-ad8f-7f7206c43477', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 31, 31, 'መኳንንት ከግብጽ ይመጣሉ ኢትዮጵያ እጆቿን ወደ እግዚአብሔር ትዘረጋለች'),
  ('8c262813-9829-592f-a088-48eacd8d9851', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 32, 32, 'የምድር ነገሥታት ለእግዚአብሔር ተቀኙ ለጌታም ዘምሩ'),
  ('ed29b4e8-1411-5130-a980-66c441dd32e7', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 33, 33, 'በምሥራቅ በኩል ወደ ሰማየ ሰማያት ለወጣ ለእግዚአብሔር ዘምሩ የኀይል ቃል የኾነ ቃሉን እንሆ ይሰጣል'),
  ('579c9676-2e54-5fb5-a3b7-442f43123bd6', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 34, 34, 'ለእግዚአብሔር ክብርን ስጡ ግርማው በእስራኤል ላይ ኀይሉም በደመናት ላይ ነው'),
  ('895795f0-90f5-5f2a-aefe-66294d0031bf', '25e46286-cf5d-5c61-a0d5-a93a7b331ae8', '029c35fd-14b8-5cf2-a05d-1a8f88943d21', 35, 35, 'እግዚአብሔር በቅዱሳኑ ላይ ድንቅ ነው የእስራኤል አምላክ ርሱ ኀይልን ብርታትንም ለሕዝቡ ይሰጣ ል እግዚአብሔርም ይመስገን'),
  ('94e53edb-b42d-5f7b-ac96-96693f64421d', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 1, 1, 'አቤቱ ውሃ እስከ ነፍሴ ደርሶብኛልና አድነኝ'),
  ('88ac8484-9f5b-500e-a4e6-f388ccf2393d', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 2, 2, 'በጥልቅ ረግረግ ጠለቅኹ መቋሚያም የለኝም ወደ ጥልቅ ባሕር ገባኹ ማዕበልም አሰጠመኝ'),
  ('bd4dfc7c-83e0-569b-a08f-5e9a9a459bc6', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 3, 3, 'በጩኸት ደከምኹ ጕረሮዬም ሰለለ አምላኬን ስጠብቅ ዐይኖቼ ፈዘዙ'),
  ('00ab05e2-8265-5443-a947-d68363d2c2c5', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 4, 4, 'በከንቱ የሚጠሉኝ ከራሴ ጠጕር በዙ በዐመፅ ያሚያሳድዱኝ ጠላቶቼ በረቱ በዚያን ጊዜ ያልቀማኹትን መለስኹ'),
  ('f3a0621d-7aaa-53f1-a909-5a90c210fc34', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 5, 5, 'አቤቱ አንተ ስንፍናዬን ታውቃለኽ ኀጢአቴም ከአንተ አልተሰወረም'),
  ('46e66836-db3f-57c0-a371-25c889bfc816', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 6, 6, 'አቤቱ የሰራዊት አምላክ ተስፋ የሚያደርጉኽ በእኔ አይፈሩ የእስራኤል አምላክ ሆይ የሚሹኽ በእኔ አይነወሩ'),
  ('2f771a2b-87d8-524d-a36f-9b0623e4eacc', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 7, 7, 'ስለ አንተ ስድብን ታግሻለኹና ዕፍረትም ፊቴን ሸፍናለችና'),
  ('e13afdf8-c593-5cda-abfb-53189a8e1660', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 8, 8, 'ለወንድሞቼ እንደ ሌላ ለእናቴ ልጆችም እንደ እንግዳ ኾንኹባቸው'),
  ('cae8de2c-86be-5adb-abe9-517a4e26643b', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 9, 9, 'የቤትኽ ቅንአት በልታኛለችና የሚሰድቡኽም ስድብ በላዬ ወድቋልና'),
  ('ccc0ed33-dfb4-5e51-a90f-7ac14b4a3558', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 10, 10, 'ነፍሴን በጾም አስመረርዃት ለስድብም ኾነብኝ'),
  ('d830bd84-d4bc-5079-aab1-95bfbbe7b0a0', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 11, 11, 'ማቅ ለበስኹ ምሳሌም ኾንኹላቸው'),
  ('8d764aec-37cd-5cce-a70f-5b682cd4c7e7', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 12, 12, 'በደጅ የሚቀመጡ በእኔ ይጫወታሉ ወይን የሚጠጡ እኔን ይዘፍናሉ'),
  ('13507b1b-585e-51d4-a4a2-d3af61e5a17a', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 13, 13, 'አቤቱ በመልካሙ ጊዜ ጸሎቴ ወዳንተ ነው አቤቱ በምሕረትኽ ብዛት በማዳንኽም እውነት አድምጠኝ'),
  ('fe2626b9-f340-5cda-aed8-0db805b39a17', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 14, 14, 'እንዳይውጠኝ ከረግረግ አውጣኝ ከሚጠሉኝና ከጥልቅ ውሃ አስጥለኝ'),
  ('eec2b115-9daf-5e9f-ae5b-894f09dbe618', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 15, 15, 'የውሃው ማዕበል አያስጥመኝ ጥልቁም አይዋጠኝ ጕድጓድም አፉን በእኔ ላይ አይዝጋ'),
  ('e0d01646-17a5-5a66-a153-5faa0316874f', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 16, 16, 'አቤቱ ምሕረትኽ መልካም ናትና ስማኝ እንደ ርኅራኄኽም ብዛት ወደ እኔ ተመልከት'),
