  ('1445ea65-cd7a-5d3e-a20f-afb77c823aba', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 20, 20, 'ነፍሴ ስድብንና ኃሣርን ታገሠች አስተዛዛኝም ተመኘኹ አላገኘኹም የሚያጽናናኝም ዐጣኹ'),
  ('a188fd43-9879-504e-a9a6-ff903e2af71a', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 21, 21, 'ለመብሌ ሐሞት ሰጡኝ ለጥማቴም ሖምጣጤ አጠጡኝ'),
