  ('c5ddfeb5-b967-5e5f-ab93-625981186e88', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 27, 27, 'በኀጢአታቸው ላይ ኀጢአትን ጨምርባቸው በጽድቅኽም አይግቡ'),
