  ('f9ea7252-61b4-5213-a315-81284921a32d', '02122e7c-8411-5b56-a0cb-fa2675530b34', '8a5ed911-a9c1-5fdb-a0f5-096e8f3f6243', 30, 30, 'የእግዚአብሔርን ስም በዝማሬ አመሰግናለኹ በምስጋናም ከፍ ከፍ አደርገዋለኹ'),
