  ('21ce17b2-14e6-5626-a4c2-4d359fa2de45', 'd68aff3a-08a6-598a-ad92-3007066d888f', '2a6db974-cd2d-57ab-a6f7-04d58cb627e9', 1, 1, 'አቤቱ እኔን ለማዳን ተመልከት አቤቱ እኔን ለመርዳት ፍጠን'),
