  ('d9ef2e9d-fbd6-5288-a609-c3a65dbb1319', 'd68aff3a-08a6-598a-ad92-3007066d888f', '2a6db974-cd2d-57ab-a6f7-04d58cb627e9', 5, 5, 'እኔ ችግረኛና ምስኪን ነኝ አቤቱ ርዳኝ ረዳቴ ታዳጊዬም አንተ ነኽ አቤቱ አትዘግይ'),
  ('72ee6239-c18f-5ad7-a82e-bc4fbfc6fed4', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 1, 1, 'አቤቱ አንተን ታመንኹ ለዘለዓለም አልፈር'),
