  ('7dae7ffd-b83d-575d-a2df-9611fadd209f', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 11, 11, 'እግዚአብሔር ትቶታል የሚያድነው የለምና ተከትላችኹ ያዙት'),
