  ('04b9b631-d4d7-511a-ae42-379ed69c6f44', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 13, 13, 'ነፍሴን የሚቃወሟት ይፈሩ ይጥፉም ጕዳቴንም የሚፈልጉ ዕፍረትንና ኃሣርን ይልበሱ'),
  ('0d4d2fcb-8cc1-54dc-a48f-bf1a4c22aef2', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 14, 14, 'እኔ ግን ዅልጊዜ ተስፋ አደርጋለኹ በምስጋናኽም ዅሉ ላይ እጨምራለኹ'),
  ('854692ff-a52d-5de6-af15-f4cc9043146c', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 15, 15, 'ሥራን አላውቅምና አፌ ጽድቅኽን ዅልጊዜም ማዳንኽን ይናገራል'),
  ('88a78dc7-3e6f-5a32-a5cb-a74776977df4', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 16, 16, 'በእግዚአብሔር ኀይል እገባለኹ አቤቱ ጽድቅኽን ብቻ ዐስባለኹ'),
  ('ec47342f-51f9-51d5-a107-fcf9fc5a3267', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 17, 17, 'አምላኬ ከታናሽነቴ ዠምረኽ አስተማርኸኝ እስከ ዛሬም ተኣምራትኽን እነግራለኹ'),
  ('5e6d983f-0337-5d1d-a8c6-64e752d50249', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 18, 18, 'እስካረጅም እስክሸመግልም ድረስ ለሚመጣ ትውልድም ዅሉ ክንድኽን ኀይልኽንም ጽድቅኽንም እስክነግ ር ድረስ አቤቱ አትተወኝ'),
  ('53544a20-cb3e-5a10-ac06-811d58126aad', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 19, 19, 'አቤቱ እስከ አርያም ታላላቅ ነገሮችን አደረግኽ አምላክ ሆይ እንደ አንተ ያለ ማን ነው'),
  ('4deb1275-6b20-5d89-ae60-c056fceddf61', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 20, 20, 'ብዙ ጭንቀትንና መከራን አሳይተኸኛልና ተመለስኽ ሕያውም አደረግኸኝ ከምድር ጥልቅም እንደ ገና አወጣኸኝ'),
  ('e6e530ec-052a-5871-a373-c77c227e2ecf', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 21, 21, 'ጽድቅኽንም አብዛው ተመልሰኽም ደስ አሠኘኝ ከጥልቅም እንደ ገና አወጣኸኝ'),
  ('96be5424-e296-5071-ab11-2239d22449c7', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 22, 22, 'እኔም በበገና ስለ እውነትኽ አመሰግንኻለኹ የእስራኤል ቅዱስ አምላክ ሆይ በመሰንቆ እዘምርልኻለ ኹ'),
  ('084c2470-2761-56dc-a6e6-a976064f4d61', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 23, 23, 'ዝማሬን ባቀርብኹልኽ ጊዜ ከንፈሮቼ ደስ ይላቸዋል አንተ ያዳንኻትም ነፍሴ'),
  ('1ad079e1-caca-53eb-a6bc-8274bfaa9baa', '676f2498-3079-567f-a41e-0f404e6ff73d', '18940508-c6bf-50bb-ac9f-f17ba97820f1', 24, 24, 'ጕዳቴን የሚሹ ባፈሩና በተነወሩ ጊዜ አንደበቴ ደግሞ ዅልጊዜ ጽድቅኽን ይናገራል'),
  ('74dc183e-e883-5cb8-a5d2-af8123ab8455', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 1, 1, 'አቤቱ ፍርድኽን ለንጉሥ ስጥ ጽድቅኽንም ለንጉሥ ልጅ'),
  ('2ee3e60c-8a72-5541-ac89-de2e459c0f82', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 2, 2, 'ሕዝብኽን በጽድቅ ችግረኛዎችኽንም በፍርድ ይዳኝ ዘንድ'),
  ('2e3a57fb-f3a6-5faa-a4af-fb0fb18a16b7', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 3, 3, 'ተራራዎችና ኰረብታዎች ለሕዝብኽ ሰላምን ይቀበሉ'),
  ('042928dc-9d0b-5997-ac09-9e38ecbb11e6', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 4, 4, 'ለችግረኛዎች ሕዝብ በጽድቅ ትፈርዳለኽ የድኻዎችንም ልጆች ታድናለኽ ክፉውንም ታዋርደዋለኽ'),
  ('7cc24350-fa90-563a-a596-9d7ce32bd24c', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 5, 5, 'ፀሓይ በሚኖርበት ዘመን ዅሉ በጨረቃም ፊት ለፊት ለልጅ ልጅ ይኖራል'),
  ('ffc19eb9-a364-5ffd-a72e-e9336c5205fe', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 6, 6, 'እንደ ዝናብ በታጨደ መስክ ላይ በምድርም ላይ እንደሚንጠባጠብ ጠብታ ይወርዳል'),
  ('0de55de2-1208-561e-a87f-902996cdceb6', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 7, 7, 'በዘመኑም ጽድቅ ያብባል ጨረቃም እስኪያልፍ ድረስ ሰላም ብዙ ነው'),
  ('90f2e267-94b8-5692-a4fc-d716b6b4b83e', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 8, 8, 'ከባሕር እስከ ባሕር ድረስ ከወንዝም እስከ ምድር ዳርቻ ድረስ ይገዛል'),
  ('151e63dd-bc8e-51aa-a49f-0fd4d539fdb1', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 9, 9, 'በፊቱም ኢትዮጵያ ይሰግዳሉ ጠላቶቹም ዐፈር ይልሳሉ'),
  ('d8d3161d-fe4e-51fc-adc6-d5aa960f4b7f', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 10, 10, 'የተርሴስና የደሴቶች ነገሥታት ስጦታን ያመጣሉ የዐረብና የሳባ ነገሥታት እጅ መንሻን ያቀርባሉ'),
  ('00ddccd3-da84-56f0-a6ad-ed7f6cdc72a1', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 11, 11, 'ነገሥታት ዅሉ ይሰግዱለታል አሕዛብም ዅሉ ይገዙለታል'),
  ('e2af42d1-5b16-5aba-ab24-214ea10906d0', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 12, 12, 'ችግረኛውን ከቀማኛው እጅ ረዳት የሌለውንም ምስኪን ያድነዋልና'),
  ('08d5c20a-4eb1-54d4-a45f-a48d4b0ff77d', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 13, 13, 'ለችግረኛና ለምስኪን ይራራል የችግረኛዎችንም ነፍስ ያድናል'),
  ('b2f9c5ad-872b-569a-a96f-27016e465db5', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 14, 14, 'ከግፍና ከጭንቀት ነፍሳቸውን ያድናል ስማቸው በፊቱ ክቡር ነው'),
  ('4c84b42b-ae4a-5dc2-a601-9a12abccd1d2', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 15, 15, 'ርሱ ይኖራል ከዐረብም ወርቅ ይሰጡታል ዅልጊዜም ወደ ርሱ ይጸልያሉ ዘወትርም ይባርኩታል'),
  ('8f437478-faef-59b5-acbf-cee792a827e6', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 16, 16, 'በምድር ውስጥ በተራራዎች ላይ መጠጊያ ይኾናል ፍሬውም ከሊባኖስ ይልቅ ከፍ ከፍ ይላል እንደምድ ር ሣር በከተማ ይበቅላል'),
  ('8d6f3047-cb87-50ab-abec-0e4f30ae9e55', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 17, 17, 'ስሙ ለዘለዓለም ቡሩክ ይኾናል ከፀሓይም አስቀድሞ ስሙ ይኖራል የምድር አሕዛብ ዅሉ በርሱ ይባረ ካሉም አሕዛብ ዅሉ ያመሰግኑታል'),
  ('2c106fe3-3990-5449-ad6d-6c06c2e111d2', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 18, 18, 'ብቻውን ተኣምራትን የሚያደርግ የእስራኤል አምላክ እግዚአብሔር ይባረክ'),
  ('e3a57f11-08c1-571b-ad41-e980184d4eb2', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 19, 19, 'የምስጋናው ስም ለዓለምና ለዘለዓለም ይባረክ ምስጋናውም ምድርን ዅሉ ይምላ ይኹን ይኹን'),
  ('9a785aed-381b-55c2-aa07-7b7afb61d3b6', '46e152c9-521e-5ece-a91e-aaba59634ffa', '7242ef8a-c5b8-5f79-ab5c-99e8dc8997fb', 20, 20, 'የእሴይ ልጅ የዳዊት መዝሙር ተፈጸመ'),
  ('2651a930-e69b-5eaa-ad94-cbcb1e499e2b', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 1, 1, 'ልባቸው ለቀና ለእስራኤል እግዚአብሔር እንዴት ቸር ነው'),
  ('d55d5add-f460-5f41-a50b-8170eb41ff12', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 2, 2, 'እኔ ግን እግሮቼ ሊሰናከሉ አረማመዴም ሊወድቅ ትንሽ ቀረ'),
  ('8c6f82ad-75a9-5890-a825-39a4f3b7c09e', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 3, 3, 'የኀጢአተኛዎችን ሰላም አይቼ በዐመፀኛዎች ቀንቼ ነበርና'),
  ('65f1ac56-c6b9-56cc-a941-e5d10c003a3e', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 4, 4, 'ለሞታቸው መጣጣር የለውምና ኀይላቸውም ጠንካራ ነውና'),
  ('5c292907-bf93-5c8a-aa8b-cc5949409ae1', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 5, 5, 'እንደ ሰው በድካም አልኾኑም ከሰው ጋራም አልተገረፉም'),
  ('ec277c3a-4cf0-5583-a40d-5d3ca08a2a9b', '27468706-6b5f-5b50-ac72-706b27eb0b44', 'c28c6bf3-1954-5a3c-ab2c-f87767e86efe', 6, 6, 'ስለዚህ ትዕቢት ያዛቸው ኀጢአትንና በደልን ተጐናጸፏት'),
